INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6c5266af-dda2-410c-96e6-be6f5fcbadee', 'edf61200-28f2-5cbe-9d72-1f0278a15e39', 'ප්‍රෝටීන සංශ්ලේෂණයේදී, ප්‍රභේදන, විකෘත', 'ප්‍රෝටීන සංශ්ලේෂණයේදී, ප්‍රභේදන, විකෘත', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1abea6bf-b063-43d3-9a83-1cc32973172b', 'edf61200-28f2-5cbe-9d72-1f0278a15e39', 'ඌනන විභාජනයේදී, විකෘති, විෂමයුග්මකයින්', 'ඌනන විභාජනයේදී, විකෘති, විෂමයුග්මකයින්', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4d3f79f0-9128-5da8-a4d0-765911b94f03', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 30, '<p>ටර්නර් සහලක්ෂණය හොඳින් ම විදහා දැක්වෙනුයේ පහත සඳහන් කුමන පුද්ගලයාගේ ද?</p>', '<p>ටර්නර් සහලක්ෂණය හොඳින් ම විදහා දැක්වෙනුයේ පහත සඳහන් කුමන පුද්ගලයාගේ ද?</p>', NULL, 'ටර්නර් සහලක්ෂණය (Turner syndrome) යනු ලිංගික වර්ණදේහ ඌනතාවයකි ($45, XO$). මෙය ඇතිවන්නේ එක් $X$ වර්ණදේහයක් පමණක් දරන ගැහැණු දරුවන් තුළය.', 'ටර්නර් සහලක්ෂණය (Turner syndrome) යනු ලිංගික වර්ණදේහ ඌනතාවයකි ($45, XO$). මෙය ඇතිවන්නේ එක් $X$ වර්ණදේහයක් පමණක් දරන ගැහැණු දරුවන් තුළය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2c81d33d-0c66-4722-944b-240e71f04323', '4d3f79f0-9128-5da8-a4d0-765911b94f03', '$X$ වර්ණදේහයේ ජාන විකෘතියක් සහිතව උපන් ගැහැණු දරුවෙක්', '$X$ වර්ණදේහයේ ජාන විකෘතියක් සහිතව උපන් ගැහැණු දරුවෙක්', NULL, 'sanitized', 'v1', 0, 1);
