INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eecee8a6-0eff-4c60-a7a1-67ed608b3ed3', '4d3f79f0-9128-5da8-a4d0-765911b94f03', 'එක් $X$ වර්ණදේහයක් පමණක් සහිතව උපන් ගැහැණු දරුවෙක් හෝ පිරිමි දරුවෙක්', 'එක් $X$ වර්ණදේහයක් පමණක් සහිතව උපන් ගැහැණු දරුවෙක් හෝ පිරිමි දරුවෙක්', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6bd55af4-8098-4124-9163-59fffe6c8490', '4d3f79f0-9128-5da8-a4d0-765911b94f03', 'එක් $X$ වර්ණදේහයක් පමණක් සහිතව උපන් ගැහැණු දරුවෙක්', 'එක් $X$ වර්ණදේහයක් පමණක් සහිතව උපන් ගැහැණු දරුවෙක්', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b857fa0d-3e5c-434b-a561-2237b0c547ea', '4d3f79f0-9128-5da8-a4d0-765911b94f03', 'අතිරේක $Y$ වර්ණ දේහයක් සහිතව උපන් පිරිමි දරුවෙක්', 'අතිරේක $Y$ වර්ණ දේහයක් සහිතව උපන් පිරිමි දරුවෙක්', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0d97252b-e2c9-52d4-ad3d-1379d05c78e5', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 31, '<p>ප්‍රවේණිකව විකරණය කරන ලද ජීවියෙක් එම විශේෂයේම වෙනත් සාමාජිකයන්ගෙන් වෙනස් වන්නේ,</p>', '<p>ප්‍රවේණිකව විකරණය කරන ලද ජීවියෙක් එම විශේෂයේම වෙනත් සාමාජිකයන්ගෙන් වෙනස් වන්නේ,</p>', NULL, 'ප්‍රවේණිකව විකරණය කරන ලද ජීවියෙකු (GMO) යනු කෘත්‍රිමව වෙනත් විශේෂයකින් හෝ ප්‍රභවයකින් ලබාගත් ජානයක් හෝ ජාන කිහිපයක් දේහයට ඇතුළත් කිරීමෙන් නිර්මාණය කරන ලද ජීවියෙකි. එමනිසා එම ජීවියා විශේෂයේ අනෙකුත් සාමාජිකයන්ගෙන් වෙනස් වේ.', 'ප්‍රවේණිකව විකරණය කරන ලද ජීවියෙකු (GMO) යනු කෘත්‍රිමව වෙනත් විශේෂයකින් හෝ ප්‍රභවයකින් ලබාගත් ජානයක් හෝ ජාන කිහිපයක් දේහයට ඇතුළත් කිරීමෙන් නිර්මාණය කරන ලද ජීවියෙකි. එමනිසා එම ජීවියා විශේෂයේ අනෙකුත් සාමාජිකයන්ගෙන් වෙනස් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b1c27af7-b342-499a-8c5f-b29f4179be86', '0d97252b-e2c9-52d4-ad3d-1379d05c78e5', 'එම ජීවියා අතිරේක වර්ණ දේහයක් දරන බැවිනි.', 'එම ජීවියා අතිරේක වර්ණ දේහයක් දරන බැවිනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('76b89e46-d4d0-463e-8c14-ff34ba7a5e81', '0d97252b-e2c9-52d4-ad3d-1379d05c78e5', 'එම ජීවියා වෙනත් ජීවියෙකුගේ ජානයක් හෝ ජාන දරන බැවිනි.', 'එම ජීවියා වෙනත් ජීවියෙකුගේ ජානයක් හෝ ජාන දරන බැවිනි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ff7400ec-c147-4162-98e1-c601bae6e5c6', '0d97252b-e2c9-52d4-ad3d-1379d05c78e5', 'එම ජීවියා වෙනත් ජීවියෙකු ක්ලෝනීකරණය කිරීම මගින් ජනනය කර ඇති බැවිනි.', 'එම ජීවියා වෙනත් ජීවියෙකු ක්ලෝනීකරණය කිරීම මගින් ජනනය කර ඇති බැවිනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a8155fb-9c33-4f53-a5c9-a7356f659ccc', '0d97252b-e2c9-52d4-ad3d-1379d05c78e5', 'එම ජීවියාට එම විශේෂයේ අනිත් සාමාජිකයන් සමග අන්තර් අභිජනනයෙන් සරු ජනිතයකු නිපදවිය නොහැකි බැවිනි.', 'එම ජීවියාට එම විශේෂයේ අනිත් සාමාජිකයන් සමග අන්තර් අභිජනනයෙන් සරු ජනිතයකු නිපදවිය නොහැකි බැවිනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ed8cc5c-b30f-4b19-85f5-735430609c50', '0d97252b-e2c9-52d4-ad3d-1379d05c78e5', 'එම ජීවියාගේ ජාන ප්‍රකාශනය හොඳින් යාමනය වී ඇති බැවිනි.', 'එම ජීවියාගේ ජාන ප්‍රකාශනය හොඳින් යාමනය වී ඇති බැවිනි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cb7d8720-27bf-506d-aeb6-79047b844572', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 32, '<p>ප්‍රවේණි උපදේශකයෙකු පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>ප්‍රවේණි උපදේශකයෙකු පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ප්‍රවේණි උපදේශකයෙකුගේ කාර්යය වන්නේ පවුල තුළ ප්‍රවේණික රෝගයක සම්භාවිතාවය, එහි ස්වභාවය හා අවදානම පැහැදිලි කිරීමයි. ගබ්සා කිරීම් (භ්‍රෑණය ගබ්සා කිරීම) සඳහා උපදෙස් දීම ඔවුන්ගේ වෘත්තීය සදාචාරයට හෝ වගකීම් වලට අයත් නොවේ.', 'ප්‍රවේණි උපදේශකයෙකුගේ කාර්යය වන්නේ පවුල තුළ ප්‍රවේණික රෝගයක සම්භාවිතාවය, එහි ස්වභාවය හා අවදානම පැහැදිලි කිරීමයි. ගබ්සා කිරීම් (භ්‍රෑණය ගබ්සා කිරීම) සඳහා උපදෙස් දීම ඔවුන්ගේ වෘත්තීය සදාචාරයට හෝ වගකීම් වලට අයත් නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('20fe09a4-ec78-4d04-a041-3ad1f7029d10', 'cb7d8720-27bf-506d-aeb6-79047b844572', 'ඔහුට මිනිසුන්ගේ ප්‍රවේණික ආබාධ පිළිබඳව දැනුමක් ඇත.', 'ඔහුට මිනිසුන්ගේ ප්‍රවේණික ආබාධ පිළිබඳව දැනුමක් ඇත.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29cd3f78-39c2-4cef-be3e-5d8972e284ab', 'cb7d8720-27bf-506d-aeb6-79047b844572', 'ඔහු ප්‍රවේණික ආබාධ සහිත පුද්ගලයන්ට ගැටළුවේ ස්වාභාවය පිළිබඳව උපදෙස් දෙයි.', 'ඔහු ප්‍රවේණික ආබාධ සහිත පුද්ගලයන්ට ගැටළුවේ ස්වාභාවය පිළිබඳව උපදෙස් දෙයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('82273136-ae9a-4954-88fb-41f1ab1f3c05', 'cb7d8720-27bf-506d-aeb6-79047b844572', 'දෙමව්පියන්ගෙන් එක් අයෙකු ප්‍රවේණික ආබාධයක් සඳහා වාහකයෙකු නම් ඔහු භ්‍රෑණය ගබ්සා කිරීමට උපදෙස් දෙයි.', 'දෙමව්පියන්ගෙන් එක් අයෙකු ප්‍රවේණික ආබාධයක් සඳහා වාහකයෙකු නම් ඔහු භ්‍රෑණය ගබ්සා කිරීමට උපදෙස් දෙයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e5d6f82e-64ec-4661-8c4e-a322409693ae', 'cb7d8720-27bf-506d-aeb6-79047b844572', 'ප්‍රවේණික ආබාධය සහිත පුද්ගලයාගේ පවුලේ සාමාජිකයන්ට තත්ත්වය කළමනාකරණය කර ගැනීමට ඔහු සහාය වෙයි.', 'ප්‍රවේණික ආබාධය සහිත පුද්ගලයාගේ පවුලේ සාමාජිකයන්ට තත්ත්වය කළමනාකරණය කර ගැනීමට ඔහු සහාය වෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('760f3117-7c45-4384-9f7f-8f93289ff85c', 'cb7d8720-27bf-506d-aeb6-79047b844572', 'ප්‍රවේණික ආබාධය සහිත පුද්ගලයාට සහ පවුලේ සාමාජිකයන්ට ඔහු රෝගය ප්‍රවේණිගත වන ආකාරය පැහැදිලි කරයි.', 'ප්‍රවේණික ආබාධය සහිත පුද්ගලයාට සහ පවුලේ සාමාජිකයන්ට ඔහු රෝගය ප්‍රවේණිගත වන ආකාරය පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3fa8b9dd-6958-5b43-a6a9-70c948388ea7', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 33, '<p>පරිසර පද්ධතියක දළ ප්‍රාථමික නිෂ්පාදනතාව සහ තුන්වැනි පෝෂී මට්ටමේ ඇති ශක්ති ප්‍රමාණය පිළිවෙළින් $2000~kJ~m^{-2}year^{-1}$ සහ $11~kJ~m^{-2}year^{-1}$ ලෙස නිර්ණය කරන ලදී. එක් පෝෂී මට්ටමක සිට ඊලඟ පෝෂී මට්ටමට ගලා යාමේ දී ශක්තිය $90\%$ ක් හානි වේ නම් මෙම පරිසර පද්ධතියේ ප්‍රාථමික නිෂ්පාදකයන් විසින් ශ්වසනය සඳහා භාවිත කරනු ලබන ශක්ති ප්‍රමාණය</p>', '<p>පරිසර පද්ධතියක දළ ප්‍රාථමික නිෂ්පාදනතාව සහ තුන්වැනි පෝෂී මට්ටමේ ඇති ශක්ති ප්‍රමාණය පිළිවෙළින් $2000~kJ~m^{-2}year^{-1}$ සහ $11~kJ~m^{-2}year^{-1}$ ලෙස නිර්ණය කරන ලදී. එක් පෝෂී මට්ටමක සිට ඊලඟ පෝෂී මට්ටමට ගලා යාමේ දී ශක්තිය $90\%$ ක් හානි වේ නම් මෙම පරිසර පද්ධතියේ ප්‍රාථමික නිෂ්පාදකයන් විසින් ශ්වසනය සඳහා භාවිත කරනු ලබන ශක්ති ප්‍රමාණය</p>', NULL, 'එක් මට්ටමකින් ඊළඟ මට්ටමට ගමන් කරන්නේ ශක්තියෙන් $10\%$ කි. <br>තුන්වන පෝෂී මට්ටමේ ශක්තිය = $11~kJ~m^{-2}year^{-1}$.<br>එබැවින් දෙවන මට්ටමට ශක්තිය = $11 \times 10 = 110~kJ~m^{-2}year^{-1}$.<br>පළමු මට්ටමෙන් දෙවන මට්ටමට යන ශක්තිය (ශුද්ධ ප්‍රාථමික නිෂ්පාදනය හෙවත් $NPP$) = $110 \times 10 = 1100~kJ~m^{-2}year^{-1}$.<br>දළ ප්‍රාථමික නිෂ්පාදනය ($GPP$) = $2000~kJ~m^{-2}year^{-1}$.<br>ශ්වසන හානිය ($R$) = $GPP - NPP = 2000 - 1100 = 900~kJ~m^{-2}year^{-1}$.', 'එක් මට්ටමකින් ඊළඟ මට්ටමට ගමන් කරන්නේ ශක්තියෙන් $10\%$ කි. <br>තුන්වන පෝෂී මට්ටමේ ශක්තිය = $11~kJ~m^{-2}year^{-1}$.<br>එබැවින් දෙවන මට්ටමට ශක්තිය = $11 \times 10 = 110~kJ~m^{-2}year^{-1}$.<br>පළමු මට්ටමෙන් දෙවන මට්ටමට යන ශක්තිය (ශුද්ධ ප්‍රාථමික නිෂ්පාදනය හෙවත් $NPP$) = $110 \times 10 = 1100~kJ~m^{-2}year^{-1}$.<br>දළ ප්‍රාථමික නිෂ්පාදනය ($GPP$) = $2000~kJ~m^{-2}year^{-1}$.<br>ශ්වසන හානිය ($R$) = $GPP - NPP = 2000 - 1100 = 900~kJ~m^{-2}year^{-1}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
