INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03842cf5-3119-4a06-a4e2-67ebd8c3c417', '85ef2527-e986-585f-b49e-7f9b3ce5ef5a', 'හුණුගල් ස්මාරක ඛාදනය වීම සඳහා දායක වේ.', 'හුණුගල් ස්මාරක ඛාදනය වීම සඳහා දායක වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27dbd12c-1a10-46a8-8983-456312decdd3', '85ef2527-e986-585f-b49e-7f9b3ce5ef5a', 'මුහුදු මට්ටම ඉහළ යෑමට දායක වේ.', 'මුහුදු මට්ටම ඉහළ යෑමට දායක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c961d5b5-afb4-4cf6-b6e2-41e0377736b6', '85ef2527-e986-585f-b49e-7f9b3ce5ef5a', 'නිවර්තන කලාපික රෝග වල ව්‍යාප්ති පරාසය අඩු වීම සඳහා දායක වේ.', 'නිවර්තන කලාපික රෝග වල ව්‍යාප්ති පරාසය අඩු වීම සඳහා දායක වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9dc45d16-fd68-5460-97dc-20609591de74', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 35, '<p>ස්ටැන්ලි මිලර්ගේ පරීක්ෂණ මගින්</p>', '<p>ස්ටැන්ලි මිලර්ගේ පරීක්ෂණ මගින්</p>', NULL, 'ස්ටැන්ලි මිලර් සහ හැරල්ඩ් යුරේ විසින් කරන ලද පරීක්ෂණය මගින් මුල් පෘථිවියේ පැවති තත්ත්වයන් යටතේ අකාබනික වායු ($CH_4, NH_3, H_2$ සහ ජල වාෂ්ප) ප්‍රතික්‍රියා කිරීමෙන් ඇමයිනෝ අම්ල වැනි සරල කාබනික අණු සංශ්ලේෂණය විය හැකි බව ප්‍රායෝගිකව පෙන්වා දෙන ලදී.', 'ස්ටැන්ලි මිලර් සහ හැරල්ඩ් යුරේ විසින් කරන ලද පරීක්ෂණය මගින් මුල් පෘථිවියේ පැවති තත්ත්වයන් යටතේ අකාබනික වායු ($CH_4, NH_3, H_2$ සහ ජල වාෂ්ප) ප්‍රතික්‍රියා කිරීමෙන් ඇමයිනෝ අම්ල වැනි සරල කාබනික අණු සංශ්ලේෂණය විය හැකි බව ප්‍රායෝගිකව පෙන්වා දෙන ලදී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
