INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43f9d07e-eedd-4ae7-b884-95b94fc971b4', '9dc45d16-fd68-5460-97dc-20609591de74', 'අකාබනික වායු වලින් කාබනික අණු තැනිය හැකි බව පෙන්නුම් කෙරුණි.', 'අකාබනික වායු වලින් කාබනික අණු තැනිය හැකි බව පෙන්නුම් කෙරුණි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ad590a90-69f6-4c9b-a6bf-5b6c2c59b1f6', '9dc45d16-fd68-5460-97dc-20609591de74', 'ශ්වාන්, ශ්ලයිඩන් සහ වර්වොව් විසින් ඉදිරිපත් කරනු ලැබූ වාදයට සාක්ෂි සැපයුණි.', 'ශ්වාන්, ශ්ලයිඩන් සහ වර්වොව් විසින් ඉදිරිපත් කරනු ලැබූ වාදයට සාක්ෂි සැපයුණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('579e76c2-cb2d-4a97-835e-93a5fda95ccf', '9dc45d16-fd68-5460-97dc-20609591de74', 'වසර මිලියන 3500 කට පෙර ජීවය සම්භවය වූ බව පෙන්නුම් කෙරුණි.', 'වසර මිලියන 3500 කට පෙර ජීවය සම්භවය වූ බව පෙන්නුම් කෙරුණි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bf8af3c3-bdda-5b18-9f8e-c85b9e3d474e', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 36, '<p>Nitrosomonas යනු</p>', '<p>Nitrosomonas යනු</p>', NULL, 'Nitrosomonas යනු නයිට්‍රීකරණ බැක්ටීරියාවකි. එය රසායනික ස්වයංපෝෂී (Chemoautotroph) ජීවියෙකු වන අතර, පසෙහි ඇති ඇමෝනියම් අයන් ($NH_4^+$) නයිට්‍රයිට් ($NO_2^-$) බවට ඔක්සිකරණය කිරීමෙන් තමන්ට අවශ්‍ය ශක්තිය ලබා ගනී.', 'Nitrosomonas යනු නයිට්‍රීකරණ බැක්ටීරියාවකි. එය රසායනික ස්වයංපෝෂී (Chemoautotroph) ජීවියෙකු වන අතර, පසෙහි ඇති ඇමෝනියම් අයන් ($NH_4^+$) නයිට්‍රයිට් ($NO_2^-$) බවට ඔක්සිකරණය කිරීමෙන් තමන්ට අවශ්‍ය ශක්තිය ලබා ගනී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8694d417-b519-444b-bd95-05d06021789a', 'bf8af3c3-bdda-5b18-9f8e-c85b9e3d474e', '$N_2$, $NH_4^+$ බවට ඔක්සිහරණය කරන රසායන - ස්වයංපෝෂියෙකි.', '$N_2$, $NH_4^+$ බවට ඔක්සිහරණය කරන රසායන - ස්වයංපෝෂියෙකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('132dedde-b2b4-471e-9ff4-6beccd38219a', 'bf8af3c3-bdda-5b18-9f8e-c85b9e3d474e', '$NH_4^+$, $NO_2^-$ බවට ඔක්සිකරණය කරන රසායන - විෂම පෝෂියෙකි.', '$NH_4^+$, $NO_2^-$ බවට ඔක්සිකරණය කරන රසායන - විෂම පෝෂියෙකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f69f74f2-68fa-4cb1-ac66-c31603b294aa', 'bf8af3c3-bdda-5b18-9f8e-c85b9e3d474e', '$NH_4^+$, $NO_2^-$ බවට ඔක්සිකරණය කරන රසායන - ස්වයංපෝෂියෙකි.', '$NH_4^+$, $NO_2^-$ බවට ඔක්සිකරණය කරන රසායන - ස්වයංපෝෂියෙකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3c2aa357-808d-423d-88e5-18e8dfd5e142', 'bf8af3c3-bdda-5b18-9f8e-c85b9e3d474e', '$NO_3^-$, $NO_2^-$ බවට ඔක්සිහරණය කරන රසායන - ස්වයංපෝෂියෙකි.', '$NO_3^-$, $NO_2^-$ බවට ඔක්සිහරණය කරන රසායන - ස්වයංපෝෂියෙකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d8fa4be-ab75-408f-88b5-0585afb11721', 'bf8af3c3-bdda-5b18-9f8e-c85b9e3d474e', '$N_2$, $NH_4^+$ බවට ඔක්සිහරණය කරන රසායන - විෂම පෝෂියෙකි.', '$N_2$, $NH_4^+$ බවට ඔක්සිහරණය කරන රසායන - විෂම පෝෂියෙකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a0a2a7c1-da70-55c5-ab56-48ccc84f67cc', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 37, '<p>රෝපණ මාධ්‍යයක සංඝටකයක් ඉහළ උෂ්ණත්වයට නිරාවරණය කළ විට විනාශ වීමට ඉඩ ඇත් නම් එම මාධ්‍යය පිළියෙළ කිරීමට වඩාත්ම සුදුසු ක්‍රමය වන්නේ</p>', '<p>රෝපණ මාධ්‍යයක සංඝටකයක් ඉහළ උෂ්ණත්වයට නිරාවරණය කළ විට විනාශ වීමට ඉඩ ඇත් නම් එම මාධ්‍යය පිළියෙළ කිරීමට වඩාත්ම සුදුසු ක්‍රමය වන්නේ</p>', NULL, 'සමහර විටමින්, ප්‍රෝටීන වැනි තාප සංවේදී සංඝටක පීඩන තාපකයේ (Autoclave) ඉහළ උෂ්ණත්වයට ඔරොත්තු නොදෙයි. එබැවින් තාපයට ප්‍රතිරෝධී අනෙකුත් මාධ්‍ය කොටස් පීඩන තාපකයේ ජීවානුහරණය කර, තාප සංවේදී කොටස් පමණක් පටල පෙරහනකින් (Membrane filter) පෙරා පසුව ජීවානුහරිත තත්ත්ව යටතේ මිශ්‍ර කරනු ලැබේ.', 'සමහර විටමින්, ප්‍රෝටීන වැනි තාප සංවේදී සංඝටක පීඩන තාපකයේ (Autoclave) ඉහළ උෂ්ණත්වයට ඔරොත්තු නොදෙයි. එබැවින් තාපයට ප්‍රතිරෝධී අනෙකුත් මාධ්‍ය කොටස් පීඩන තාපකයේ ජීවානුහරණය කර, තාප සංවේදී කොටස් පමණක් පටල පෙරහනකින් (Membrane filter) පෙරා පසුව ජීවානුහරිත තත්ත්ව යටතේ මිශ්‍ර කරනු ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('48d8ffdb-3198-400c-b721-ccb9e23c16dc', 'a0a2a7c1-da70-55c5-ab56-48ccc84f67cc', 'මාධ්‍යය පැය දෙකක් $80^{\circ}C$ හි රත් කිරීමයි.', 'මාධ්‍යය පැය දෙකක් $80^{\circ}C$ හි රත් කිරීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a338983a-4545-4828-b0ba-98b2c7a83cb9', 'a0a2a7c1-da70-55c5-ab56-48ccc84f67cc', 'මාධ්‍යය පීඩන තාපකයක රත් කර $0.45~\mu m$ සිදුරු සහිත පටල පෙරහනකින් පෙරීමයි.', 'මාධ්‍යය පීඩන තාපකයක රත් කර $0.45~\mu m$ සිදුරු සහිත පටල පෙරහනකින් පෙරීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8558769a-a673-4843-9932-680c833c2ed1', 'a0a2a7c1-da70-55c5-ab56-48ccc84f67cc', 'තාප සංවේදී සංඝටකය රහිත මාධ්‍යය සහ තාප සංවේදී සංඝටකයේ ද්‍රාවණය වෙන වෙන ම පීඩන තාපකයක රත් කර ඒවා සිසිල් වූ පසු මිශ්‍ර කිරීමයි.', 'තාප සංවේදී සංඝටකය රහිත මාධ්‍යය සහ තාප සංවේදී සංඝටකයේ ද්‍රාවණය වෙන වෙන ම පීඩන තාපකයක රත් කර ඒවා සිසිල් වූ පසු මිශ්‍ර කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('61c22ea7-c90a-4ced-a896-a637c969f434', 'a0a2a7c1-da70-55c5-ab56-48ccc84f67cc', 'තාප සංවේදී සංඝටකය රහිත මාධ්‍යය පීඩන තාපකයක් රත් කර තාප සංවේදී සංඝටකයේ ද්‍රාවණය $0.45~\mu m$ සිදුරු සහිත පෙරහනකින් පෙරා සිසිල් වූ පසු මිශ්‍ර කිරීමයි.', 'තාප සංවේදී සංඝටකය රහිත මාධ්‍යය පීඩන තාපකයක් රත් කර තාප සංවේදී සංඝටකයේ ද්‍රාවණය $0.45~\mu m$ සිදුරු සහිත පෙරහනකින් පෙරා සිසිල් වූ පසු මිශ්‍ර කිරීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('de7616c1-cd9b-4311-8eb9-ffae266164e2', 'a0a2a7c1-da70-55c5-ab56-48ccc84f67cc', 'මාධ්‍යයේ සියලු සංඝටක වීදුරු ප්ලාස්කුවක් තුළ මිශ්‍ර කර පාරජම්බූල විකිරණ භාවිත කර ජීවානුහරණය කිරීමයි.', 'මාධ්‍යයේ සියලු සංඝටක වීදුරු ප්ලාස්කුවක් තුළ මිශ්‍ර කර පාරජම්බූල විකිරණ භාවිත කර ජීවානුහරණය කිරීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8f9e46de-a567-5df2-a809-7d22c0bed6cb', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 38, '<p>දිලීරවල ලාක්ෂණික ගුණයක් වන්නේ,</p>', '<p>දිලීරවල ලාක්ෂණික ගුණයක් වන්නේ,</p>', NULL, 'දිලීර යනු විෂමපෝෂීන් වේ. ඒවා සෛලයෙන් පිටතට ජීරණ එන්සයිම ස්‍රාවය කර පරිසරයේ ඇති කාබනික ද්‍රව්‍ය බාහිරව ජීරණය කොට, ජීර්ණය වූ සරල පෝෂක අවශෝෂණය කර ගනී. මෙය විෂම පෝෂී අවශෝෂණ පෝෂණය ලෙස හැඳින්වේ.', 'දිලීර යනු විෂමපෝෂීන් වේ. ඒවා සෛලයෙන් පිටතට ජීරණ එන්සයිම ස්‍රාවය කර පරිසරයේ ඇති කාබනික ද්‍රව්‍ය බාහිරව ජීරණය කොට, ජීර්ණය වූ සරල පෝෂක අවශෝෂණය කර ගනී. මෙය විෂම පෝෂී අවශෝෂණ පෝෂණය ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ede47f11-f141-4284-9951-6e6d5d9d6dde', '8f9e46de-a567-5df2-a809-7d22c0bed6cb', 'ග්ලයිකොපෙප්ටයිඩ වලින් තැනුන සෛල බිත්ති තිබීමයි.', 'ග්ලයිකොපෙප්ටයිඩ වලින් තැනුන සෛල බිත්ති තිබීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2130be92-a250-47df-aca6-2124f67ba07b', '8f9e46de-a567-5df2-a809-7d22c0bed6cb', 'විෂම පෝෂී අවශෝෂණ පෝෂණයක් තිබීමයි.', 'විෂම පෝෂී අවශෝෂණ පෝෂණයක් තිබීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54cfd4d1-67f7-44a3-bc12-f37efacc5936', '8f9e46de-a567-5df2-a809-7d22c0bed6cb', 'ආහාර අධි ග්‍රහණය කර ජීරණය කිරීමයි.', 'ආහාර අධි ග්‍රහණය කර ජීරණය කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4426398e-677b-4d2c-b867-d43ff4b6a3d3', '8f9e46de-a567-5df2-a809-7d22c0bed6cb', 'ආහාර පිෂ්ටය ලෙස තැන්පත් කිරීමයි.', 'ආහාර පිෂ්ටය ලෙස තැන්පත් කිරීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3478771f-b1e9-416a-90f6-ed9a1acf5dd0', '8f9e46de-a567-5df2-a809-7d22c0bed6cb', 'අන්තඃබීජාණු මගින් ප්‍රජනනය කිරීමයි.', 'අන්තඃබීජාණු මගින් ප්‍රජනනය කිරීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a451fac0-9047-5416-9b4d-e8d0b8a7725f', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 39, '<p>සනීපාරක්ෂක භූ පිරවීම් භාවිතය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>සනීපාරක්ෂක භූ පිරවීම් භාවිතය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'සනීපාරක්ෂක භූ පිරවීම් වලදී (Sanitary landfills) අපද්‍රව්‍ය පස් තට්ටු අතර සිරකර ට්‍රැක්ටර් වැනි යන්ත්‍ර මගින් හොඳින් සම්පීඩනය කරනු ලැබේ. මේ නිසා ඝන අපද්‍රව්‍ය වල පරිමාව සැලකිය යුතු ලෙස අඩුවේ.', 'සනීපාරක්ෂක භූ පිරවීම් වලදී (Sanitary landfills) අපද්‍රව්‍ය පස් තට්ටු අතර සිරකර ට්‍රැක්ටර් වැනි යන්ත්‍ර මගින් හොඳින් සම්පීඩනය කරනු ලැබේ. මේ නිසා ඝන අපද්‍රව්‍ය වල පරිමාව සැලකිය යුතු ලෙස අඩුවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dd417f33-22a9-430b-b102-0bffa383eb7e', 'a451fac0-9047-5416-9b4d-e8d0b8a7725f', 'ක්‍රියාකරවීමේ වියදම අධික බැවින් එය හොඳ තේරීමක් නොවේ.', 'ක්‍රියාකරවීමේ වියදම අධික බැවින් එය හොඳ තේරීමක් නොවේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b1a97cea-de22-47af-b160-162abf1bd8e2', 'a451fac0-9047-5416-9b4d-e8d0b8a7725f', 'එය ඉඩම් ගොඩ කිරීම සඳහා නාගරික ඝන අපද්‍රව්‍ය තෙත්බිම්වලට හෙලීම හා සම්බන්ධ ය.', 'එය ඉඩම් ගොඩ කිරීම සඳහා නාගරික ඝන අපද්‍රව්‍ය තෙත්බිම්වලට හෙලීම හා සම්බන්ධ ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('73c7c36e-814c-4d99-b3d5-6ab203e54ff6', 'a451fac0-9047-5416-9b4d-e8d0b8a7725f', 'එය ඝන අපද්‍රව්‍ය වල පරිමාව අඩු කරන ක්‍රමයකි.', 'එය ඝන අපද්‍රව්‍ය වල පරිමාව අඩු කරන ක්‍රමයකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d97f8069-ebad-4154-92b4-a57e2e0b1523', 'a451fac0-9047-5416-9b4d-e8d0b8a7725f', 'භූගත ජල මට්ටම අඩු බැවින් බොහෝ ප්‍රදේශ වල එය සීමා වී ඇත.', 'භූගත ජල මට්ටම අඩු බැවින් බොහෝ ප්‍රදේශ වල එය සීමා වී ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('05a9df11-0ec8-479a-88bd-bc883bef5c6c', 'a451fac0-9047-5416-9b4d-e8d0b8a7725f', 'එහිදී අපද්‍රව්‍ය වියෝජනය වීමක් සිදු නොවේ.', 'එහිදී අපද්‍රව්‍ය වියෝජනය වීමක් සිදු නොවේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f88ded1e-82d6-57dd-82f3-565e02d47651', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 40, '<p>ආහාර පරිරක්ෂණය පහත සඳහන් මූලධර්ම මත පදනම් වේ.<br><br>a - ආහාර තුළට ක්ෂුද්‍රජීවීන් ඇතුළුවීම වැළැක්වීම<br>b - ආහාරවල ක්ෂුද්‍රජීවීන්ගේ වර්ධනය සහ ක්‍රියාකාරිත්වය වැළැක්වීම<br>c - ආහාරවල ක්ෂුද්‍රජීවීන් ඉවත් කිරීම හෝ නැසීම<br><br>ආහාර ටින් කිරීම ඉහත සඳහන් කුමන මූලධර්ම මත පදනම් වේ ද?</p>', '<p>ආහාර පරිරක්ෂණය පහත සඳහන් මූලධර්ම මත පදනම් වේ.<br><br>a - ආහාර තුළට ක්ෂුද්‍රජීවීන් ඇතුළුවීම වැළැක්වීම<br>b - ආහාරවල ක්ෂුද්‍රජීවීන්ගේ වර්ධනය සහ ක්‍රියාකාරිත්වය වැළැක්වීම<br>c - ආහාරවල ක්ෂුද්‍රජීවීන් ඉවත් කිරීම හෝ නැසීම<br><br>ආහාර ටින් කිරීම ඉහත සඳහන් කුමන මූලධර්ම මත පදනම් වේ ද?</p>', NULL, 'ආහාර ටින් කිරීමේ ක්‍රියාවලියේදී, අධික තාපය යෙදීමෙන් ආහාරයේ ඇති ක්ෂුද්‍රජීවීන් විනාශ කිරීම (c), ටින් එක තුළ ක්ෂුද්‍රජීවීන්ට වර්ධනය වීමට අවශ්‍ය ඔක්සිජන් ඉවත් කිරීමෙන් වර්ධනය වැළැක්වීම (b), සහ සම්පූර්ණයෙන් වාතය නොයන ලෙස මුද්‍රා තැබීමෙන් නව ක්ෂුද්‍රජීවීන් ඇතුළුවීම වැළැක්වීම (a) යන මූලධර්ම තුනම භාවිතා වේ.', 'ආහාර ටින් කිරීමේ ක්‍රියාවලියේදී, අධික තාපය යෙදීමෙන් ආහාරයේ ඇති ක්ෂුද්‍රජීවීන් විනාශ කිරීම (c), ටින් එක තුළ ක්ෂුද්‍රජීවීන්ට වර්ධනය වීමට අවශ්‍ය ඔක්සිජන් ඉවත් කිරීමෙන් වර්ධනය වැළැක්වීම (b), සහ සම්පූර්ණයෙන් වාතය නොයන ලෙස මුද්‍රා තැබීමෙන් නව ක්ෂුද්‍රජීවීන් ඇතුළුවීම වැළැක්වීම (a) යන මූලධර්ම තුනම භාවිතා වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
