INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('48d4bb0f-c69f-4492-94c7-a5300fe01899', '4654d412-bf22-566c-b222-0f25b0918558', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි ය.', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('09694445-c8f7-5d78-bb5c-03ada3ff2d5f', '7415979c-a5df-5e71-81e4-f52fb6a2f97d', 43, '<p>ශාක පටක තුළ පමණක් දක්නට ලැබෙන්නේ පහත සඳහන් ඒවා අතුරෙන් කුමක්ද?/ කුමන ඒවාද?<br><br>(A) ග්ලයොක්සිසෝම<br>(B) ප්ලාස්මඩෙස්මටා<br>(C) ලයිසොසෝම<br>(D) පෙරොක්සිසෝම<br>(E) තද සන්ධි</p>', '<p>ශාක පටක තුළ පමණක් දක්නට ලැබෙන්නේ පහත සඳහන් ඒවා අතුරෙන් කුමක්ද?/ කුමන ඒවාද?<br><br>(A) ග්ලයොක්සිසෝම<br>(B) ප්ලාස්මඩෙස්මටා<br>(C) ලයිසොසෝම<br>(D) පෙරොක්සිසෝම<br>(E) තද සන්ධි</p>', NULL, 'ග්ලයොක්සිසෝම (A) සහ ප්ලාස්මඩෙස්මටා (B) යනු සත්ත්ව සෛලවල දැකිය නොහැකි, ශාක සෛලවලට අනන්‍ය වූ ව්‍යුහයන් වේ. ලකුණු දීමේ පටිපාටියට අනුව පිළිතුරු 3 (A හා B) හෝ 5 නිවැරදි ලෙස සලකා ඇති අතර, මෙහිදී වඩාත් ගැලපෙන පිළිතුර 3 වේ.', 'ග්ලයොක්සිසෝම (A) සහ ප්ලාස්මඩෙස්මටා (B) යනු සත්ත්ව සෛලවල දැකිය නොහැකි, ශාක සෛලවලට අනන්‍ය වූ ව්‍යුහයන් වේ. ලකුණු දීමේ පටිපාටියට අනුව පිළිතුරු 3 (A හා B) හෝ 5 නිවැරදි ලෙස සලකා ඇති අතර, මෙහිදී වඩාත් ගැලපෙන පිළිතුර 3 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
