INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('65183218-2526-46c2-8e00-1a2fd8ed68d6', '7211a65e-68ac-5d5f-9d08-d9f10b6c9138', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි ය.', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('15d4dab7-9cc1-5eb9-9346-153a4424020f', '748cbb44-65a6-5187-a58c-ce2bce56566e', 1, '<p>පහත දක්වා ඇති භෞතික රාශි යුගල අතුරෙන් එක සමාන මාන ඇත්තේ කුමකට ද?</p>', '<p>පහත දක්වා ඇති භෞතික රාශි යුගල අතුරෙන් එක සමාන මාන ඇත්තේ කුමකට ද?</p>', NULL, 'කාර්යය (Work) සහ ශක්තිය (Energy) යන දෙකටම ඇත්තේ සමාන මාන වේ ($ML^2T^{-2}$). ප්‍රත්‍යාබලයට පීඩනයේ මාන ඇති අතර වික්‍රියාව මාන රහිත වේ. බර යනු බලයක් වන අතර ස්කන්ධය මූලික රාශියකි.', 'කාර්යය (Work) සහ ශක්තිය (Energy) යන දෙකටම ඇත්තේ සමාන මාන වේ ($ML^2T^{-2}$). ප්‍රත්‍යාබලයට පීඩනයේ මාන ඇති අතර වික්‍රියාව මාන රහිත වේ. බර යනු බලයක් වන අතර ස්කන්ධය මූලික රාශියකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
