INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('614b5d67-cd85-5bd9-838b-2f99ef7594fc', '748cbb44-65a6-5187-a58c-ce2bce56566e', 8, '<p>down ක්වාක් (d) එකක ආරෝපණය කොපමණ ද? (මූලික ආරෝපණය e වේ.)</p>', '<p>down ක්වාක් (d) එකක ආරෝපණය කොපමණ ද? (මූලික ආරෝපණය e වේ.)</p>', NULL, 'මූලික අංශු භෞතික විද්‍යාවට අනුව Up (u) ක්වාක් එකක ආරෝපණය $+\frac{2}{3}e$ වන අතර Down (d) ක්වාක් එකක ආරෝපණය $-\frac{1}{3}e$ වේ.', 'මූලික අංශු භෞතික විද්‍යාවට අනුව Up (u) ක්වාක් එකක ආරෝපණය $+\frac{2}{3}e$ වන අතර Down (d) ක්වාක් එකක ආරෝපණය $-\frac{1}{3}e$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
