INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('71381b21-0e90-4578-8e52-447f2854991f', 'd33b2b98-32f0-5c6c-b316-b865029372ee', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', '(A), (B) සහ (C) යන සියල්ලම සත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c91dd8d6-2e39-525c-9739-c1d8b4ffb63e', '748cbb44-65a6-5187-a58c-ce2bce56566e', 16, '<p>හරස්කඩ වර්ග ඵලය $A$ වූ තිරස් බටයක් තුළින් $3v$ වේගයෙන් ගලා යන්නා වූ ඝනත්වය $\rho$ වන ද්‍රවයක් සිරස් බිත්තියකට ලම්බකව ගැටී, පොළා පැනීමකින් තොරව බිත්තිය දිගේ පහළට ගලා යයි. ද්‍රවය මගින් බිත්තිය මත ඇති කරනු ලබන බලය වන්නේ,</p>', '<p>හරස්කඩ වර්ග ඵලය $A$ වූ තිරස් බටයක් තුළින් $3v$ වේගයෙන් ගලා යන්නා වූ ඝනත්වය $\rho$ වන ද්‍රවයක් සිරස් බිත්තියකට ලම්බකව ගැටී, පොළා පැනීමකින් තොරව බිත්තිය දිගේ පහළට ගලා යයි. ද්‍රවය මගින් බිත්තිය මත ඇති කරනු ලබන බලය වන්නේ,</p>', NULL, 'ද්‍රවයේ ස්කන්ධ ගලායාමේ ශීඝ්‍රතාවය (Mass flow rate) $= A \times (3v) \times \rho = 3A\rho v$<br>ද්‍රවය බිත්තියේ ගැටී පොළා නොපැන පහළට ගලා යන බැවින්, තිරස් දිශාවට ප්‍රවේගයේ වෙනස $= 3v - 0 = 3v$<br>නිව්ටන්ගේ දෙවන නියමයට අනුව ඇතිවන බලය ගම්‍යතා වෙනස් වීමේ ශීඝ්‍රතාවයට සමාන වේ.<br>$F = \frac{\Delta p}{\Delta t} = (3A\rho v) \times (3v) = 9\rho A v^{2}$.', 'ද්‍රවයේ ස්කන්ධ ගලායාමේ ශීඝ්‍රතාවය (Mass flow rate) $= A \times (3v) \times \rho = 3A\rho v$<br>ද්‍රවය බිත්තියේ ගැටී පොළා නොපැන පහළට ගලා යන බැවින්, තිරස් දිශාවට ප්‍රවේගයේ වෙනස $= 3v - 0 = 3v$<br>නිව්ටන්ගේ දෙවන නියමයට අනුව ඇතිවන බලය ගම්‍යතා වෙනස් වීමේ ශීඝ්‍රතාවයට සමාන වේ.<br>$F = \frac{\Delta p}{\Delta t} = (3A\rho v) \times (3v) = 9\rho A v^{2}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
