INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('51b2b502-17cc-5d77-af0b-2412113f2bfe', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 2, '<p>පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක දේශපාලන විධායකය වන්නේ,</p>', '<p>පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක දේශපාලන විධායකය වන්නේ,</p>', NULL, 'පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක (බ්‍රිතාන්‍ය ආකෘතියේ) සැබෑ දේශපාලන විධායකය වන්නේ පාර්ලිමේන්තුවේ බහුතර බලය හිමි අගමැතිවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයයි.<br>මෙහිදී රජු හෝ නාමමාත්‍රික ජනාධිපතිවරයෙකු නාමමාත්‍රික විධායකය ලෙස කටයුතු කරයි.', 'පාර්ලිමේන්තු ආණ්ඩු ක්‍රමයක (බ්‍රිතාන්‍ය ආකෘතියේ) සැබෑ දේශපාලන විධායකය වන්නේ පාර්ලිමේන්තුවේ බහුතර බලය හිමි අගමැතිවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයයි.<br>මෙහිදී රජු හෝ නාමමාත්‍රික ජනාධිපතිවරයෙකු නාමමාත්‍රික විධායකය ලෙස කටයුතු කරයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cec9c75f-460e-4c71-91d7-55abec89dbd7', '51b2b502-17cc-5d77-af0b-2412113f2bfe', 'ජනාධිපතිවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයයි.', 'ජනාධිපතිවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයයි.', NULL, 'sanitized', 'v1', 0, 1);
