INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dae64e6f-422a-50a1-a733-fda2df8bf196', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 3, '<p>බහු සංස්කෘතික සමාජයක පුරවැසියකු ප්‍රගුණ කළ යුතු ගුණාංගයක් වන්නේ මින් කුමක්ද?</p>', '<p>බහු සංස්කෘතික සමාජයක පුරවැසියකු ප්‍රගුණ කළ යුතු ගුණාංගයක් වන්නේ මින් කුමක්ද?</p>', NULL, 'බහු සංස්කෘතික සමාජයක විවිධ ජාතීන්, ආගම් හා සංස්කෘතීන්ට අයත් ජනතාව ජීවත් වන බැවින්, අන්‍යෝන්‍ය ගෞරවය සහ සහජීවනය පවත්වා ගනිමින් අන් අය සමඟ ගැටුම් ඇති නොවන සේ ජීවත් වීම යහපත් පුරවැසියෙකුගේ ප්‍රධාන ලක්ෂණයකි.', 'බහු සංස්කෘතික සමාජයක විවිධ ජාතීන්, ආගම් හා සංස්කෘතීන්ට අයත් ජනතාව ජීවත් වන බැවින්, අන්‍යෝන්‍ය ගෞරවය සහ සහජීවනය පවත්වා ගනිමින් අන් අය සමඟ ගැටුම් ඇති නොවන සේ ජීවත් වීම යහපත් පුරවැසියෙකුගේ ප්‍රධාන ලක්ෂණයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('39e8e1c0-db7f-4380-8951-74408da884e5', 'dae64e6f-422a-50a1-a733-fda2df8bf196', 'එක් ජන වර්ගයකට අයත් අයිතිවාසිකම් ආරක්ෂා කිරීම', 'එක් ජන වර්ගයකට අයත් අයිතිවාසිකම් ආරක්ෂා කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9aa3e97-9213-41ec-8320-a4192be0f736', 'dae64e6f-422a-50a1-a733-fda2df8bf196', 'අන්‍ය ආගම් පිළිගෙන ඒවා අනුගමනය කිරීම', 'අන්‍ය ආගම් පිළිගෙන ඒවා අනුගමනය කිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0e5acc0b-c26e-463a-8ec5-14b2cd37d486', 'dae64e6f-422a-50a1-a733-fda2df8bf196', 'අන් අයගේ මතවාද හා අදහස් සන්නිවේදනය කිරීම', 'අන් අයගේ මතවාද හා අදහස් සන්නිවේදනය කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('92717b3f-11f8-4fa4-a8f0-e7df0d13a751', 'dae64e6f-422a-50a1-a733-fda2df8bf196', 'අන් අය සමග ගැටුම් ඇති නොවන සේ ජීවත්වීම', 'අන් අය සමග ගැටුම් ඇති නොවන සේ ජීවත්වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('090fc0f1-051a-52fa-b092-ce3f75232082', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 4, '<p>ශ්‍රී ලංකාව තුළ ආගමක් පදනම් කරගෙන සකස් වී ඇති නීතිය කුමක්ද?</p>', '<p>ශ්‍රී ලංකාව තුළ ආගමක් පදනම් කරගෙන සකස් වී ඇති නීතිය කුමක්ද?</p>', NULL, 'ශ්‍රී ලංකාවේ ක්‍රියාත්මක වන පුද්ගල නීති අතරින් ''මුස්ලිම් නීතිය'' (Muslim Law) ඉස්ලාම් ආගමික මූලධර්ම සහ අල් කුරානය පදනම් කරගෙන සකස් වී ඇත.', 'ශ්‍රී ලංකාවේ ක්‍රියාත්මක වන පුද්ගල නීති අතරින් ''මුස්ලිම් නීතිය'' (Muslim Law) ඉස්ලාම් ආගමික මූලධර්ම සහ අල් කුරානය පදනම් කරගෙන සකස් වී ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
