INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4084171d-2516-59df-af06-58f8366426d6', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 7, '<p>ශ්‍රී ලංකාව කාන්තා අයිතිවාසිකම් ආරක්ෂා කරදීම සඳහා ගෙන ඇති ක්‍රියා මාර්ගයක් වන්නේ,</p>', '<p>ශ්‍රී ලංකාව කාන්තා අයිතිවාසිකම් ආරක්ෂා කරදීම සඳහා ගෙන ඇති ක්‍රියා මාර්ගයක් වන්නේ,</p>', NULL, 'කාන්තාවන්ට සහ ළමයින්ට එරෙහිව සිදුවන ගෘහස්ථ හිංසනයන් හා විවිධ අපයෝජනයන්ගෙන් ඔවුන් ආරක්ෂා කර ගැනීම සඳහා ශ්‍රී ලංකා පොලිස් දෙපාර්තමේන්තුව විසින් සෑම පොලිස් ස්ථානයකම ''ළමා හා කාන්තා කාර්යාංශයක්'' පිහිටුවා ඇත.', 'කාන්තාවන්ට සහ ළමයින්ට එරෙහිව සිදුවන ගෘහස්ථ හිංසනයන් හා විවිධ අපයෝජනයන්ගෙන් ඔවුන් ආරක්ෂා කර ගැනීම සඳහා ශ්‍රී ලංකා පොලිස් දෙපාර්තමේන්තුව විසින් සෑම පොලිස් ස්ථානයකම ''ළමා හා කාන්තා කාර්යාංශයක්'' පිහිටුවා ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ccad9c9d-9f01-40d8-b33d-7148f11559b6', '4084171d-2516-59df-af06-58f8366426d6', 'කාන්තාවන්ට රැකියාවල නිරත වීමට අවසර ලබාදීමයි.', 'කාන්තාවන්ට රැකියාවල නිරත වීමට අවසර ලබාදීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7f7d8670-d33c-4c04-84d9-9abda03d2deb', '4084171d-2516-59df-af06-58f8366426d6', 'සෑම පොලිසියකම ළමා හා කාන්තා අංශයක් පිහිටුවීමයි.', 'සෑම පොලිසියකම ළමා හා කාන්තා අංශයක් පිහිටුවීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4a609625-c3e2-4a44-b2d6-8aa8507ac9e3', '4084171d-2516-59df-af06-58f8366426d6', 'කාන්තාවන් සඳහා සෞඛ්‍ය සායන පවත්වා ගෙන යාමයි.', 'කාන්තාවන් සඳහා සෞඛ්‍ය සායන පවත්වා ගෙන යාමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fc6aa974-6695-4ac8-bbc6-3ceac14f5d55', '4084171d-2516-59df-af06-58f8366426d6', 'අවුරුදු 18 ට වැඩි කාන්තාවන් සඳහා ඡන්ද බලය ලබාදීමයි.', 'අවුරුදු 18 ට වැඩි කාන්තාවන් සඳහා ඡන්ද බලය ලබාදීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('91f04279-3349-5661-9fca-2bb27073ead5', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 8, '<p>සමාජ පරිසරයට හානි පැමිණ වීම නිසා ඇති විය හැකි ප්‍රතිඵලයක් වන්නේ,</p>', '<p>සමාජ පරිසරයට හානි පැමිණ වීම නිසා ඇති විය හැකි ප්‍රතිඵලයක් වන්නේ,</p>', NULL, 'නොදිරන අපද්‍රව්‍ය එකතුවීම, රෝග පැතිරීම සහ අස්වැන්න අඩුවීම භෞතික හා ජෛව පාරිසරික ගැටලු වේ.<br>පවුල් සංස්ථාව බිඳවැටීම, අපරාධ ඉහළ යාම සහ මත්ද්‍රව්‍ය භාවිතය වැනි කරුණු ''සමාජ පරිසරයට'' හානි වීමෙන් ඇතිවන ප්‍රතිඵල වේ.', 'නොදිරන අපද්‍රව්‍ය එකතුවීම, රෝග පැතිරීම සහ අස්වැන්න අඩුවීම භෞතික හා ජෛව පාරිසරික ගැටලු වේ.<br>පවුල් සංස්ථාව බිඳවැටීම, අපරාධ ඉහළ යාම සහ මත්ද්‍රව්‍ය භාවිතය වැනි කරුණු ''සමාජ පරිසරයට'' හානි වීමෙන් ඇතිවන ප්‍රතිඵල වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1c149d03-3884-4b20-83e9-c9112b550567', '91f04279-3349-5661-9fca-2bb27073ead5', 'පවුල් සංස්ථා බිඳවැටීමයි.', 'පවුල් සංස්ථා බිඳවැටීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2401fb16-f7a9-4fd0-8ddd-6e6ab74818b8', '91f04279-3349-5661-9fca-2bb27073ead5', 'නොදිරන අපද්‍රව්‍ය එකතු වීමයි.', 'නොදිරන අපද්‍රව්‍ය එකතු වීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f5df0442-8766-4020-8675-f266daabe247', '91f04279-3349-5661-9fca-2bb27073ead5', 'වසංගත රෝග පැතිරීමයි.', 'වසංගත රෝග පැතිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7e59c911-8e3d-4c48-9409-bca591078423', '91f04279-3349-5661-9fca-2bb27073ead5', 'කෘෂි අස්වැන්න අඩු වීමයි.', 'කෘෂි අස්වැන්න අඩු වීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('48893b01-a8da-5229-8d3f-2d49161666be', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 9, '<p>ණය අර්බුදයෙන් මිදීම සඳහා මෑතකදී ශ්‍රී ලංකාවට ආධාර ලබාදුන් ජාත්‍යන්තර ආයතනය කුමක්ද?</p>', '<p>ණය අර්බුදයෙන් මිදීම සඳහා මෑතකදී ශ්‍රී ලංකාවට ආධාර ලබාදුන් ජාත්‍යන්තර ආයතනය කුමක්ද?</p>', NULL, 'මෑතකදී ඇතිවූ දැඩි ආර්ථික හා ගෙවුම් තුලන අර්බුදයෙන් මිදීම සඳහා ශ්‍රී ලංකාව ජාත්‍යන්තර මූල්‍ය අරමුදලේ (IMF - International Monetary Fund) විස්තීර්ණ මූල්‍ය පහසුකම යටතේ ණය ආධාර ලබා ගන්නා ලදී.', 'මෑතකදී ඇතිවූ දැඩි ආර්ථික හා ගෙවුම් තුලන අර්බුදයෙන් මිදීම සඳහා ශ්‍රී ලංකාව ජාත්‍යන්තර මූල්‍ය අරමුදලේ (IMF - International Monetary Fund) විස්තීර්ණ මූල්‍ය පහසුකම යටතේ ණය ආධාර ලබා ගන්නා ලදී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
