INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fafa9d23-7931-4ca9-8459-838ba0ee655a', '48893b01-a8da-5229-8d3f-2d49161666be', 'ආසියානු සංවර්ධන බැංකුව', 'ආසියානු සංවර්ධන බැංකුව', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d2a3be12-7ca8-444d-93ba-b80f757ad3ea', '48893b01-a8da-5229-8d3f-2d49161666be', 'චීන සංවර්ධන බැංකුව', 'චීන සංවර්ධන බැංකුව', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('72e60379-7f47-5e45-b3ce-c35fd64e4981', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 10, '<p>ඡන්ද කොට්ඨාස අනුව පාර්ලිමේන්තුවට මහජන නියෝජිතයන් තෝරා ගැනීම නිසා ලැබෙන වාසියක් වන්නේ,</p>', '<p>ඡන්ද කොට්ඨාස අනුව පාර්ලිමේන්තුවට මහජන නියෝජිතයන් තෝරා ගැනීම නිසා ලැබෙන වාසියක් වන්නේ,</p>', NULL, 'කේවල හෙවත් කොට්ඨාස ක්‍රමය යටතේ සෑම ප්‍රාදේශීය කොට්ඨාසයක් සඳහාම වගකියන මන්ත්‍රීවරයෙකු පත්වන බැවින්, තම ප්‍රදේශයේ ගැටලු පාර්ලිමේන්තුවට ඉදිරිපත් කර ප්‍රාදේශීය සංවර්ධනයට අවස්ථා සලසා ගැනීමට ජනතාවට හැකියාව ලැබේ.', 'කේවල හෙවත් කොට්ඨාස ක්‍රමය යටතේ සෑම ප්‍රාදේශීය කොට්ඨාසයක් සඳහාම වගකියන මන්ත්‍රීවරයෙකු පත්වන බැවින්, තම ප්‍රදේශයේ ගැටලු පාර්ලිමේන්තුවට ඉදිරිපත් කර ප්‍රාදේශීය සංවර්ධනයට අවස්ථා සලසා ගැනීමට ජනතාවට හැකියාව ලැබේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('265abc2e-38cd-45a0-af48-3e16fe74f4a2', '72e60379-7f47-5e45-b3ce-c35fd64e4981', 'නිදහස් මැතිවරණ පැවැත්වීමට හැකි වීමයි.', 'නිදහස් මැතිවරණ පැවැත්වීමට හැකි වීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9ab5043d-9e0b-4535-b4e1-bb3bc38f4e59', '72e60379-7f47-5e45-b3ce-c35fd64e4981', 'සාමකාමී වාතාවරණයක් ඇති කිරීමට හැකිවීමයි.', 'සාමකාමී වාතාවරණයක් ඇති කිරීමට හැකිවීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f12581e0-d25e-48c6-807a-aa4bc901b930', '72e60379-7f47-5e45-b3ce-c35fd64e4981', 'ප්‍රජාතන්ත්‍ර විරෝධී ක්‍රියා පාලනය කිරීමට හැකි වීමයි.', 'ප්‍රජාතන්ත්‍ර විරෝධී ක්‍රියා පාලනය කිරීමට හැකි වීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8a962466-263f-4074-89c4-786a268f1c53', '72e60379-7f47-5e45-b3ce-c35fd64e4981', 'ප්‍රාදේශීය සංවර්ධනයට අවස්ථා සැලසීමට හැකිවීමයි.', 'ප්‍රාදේශීය සංවර්ධනයට අවස්ථා සැලසීමට හැකිවීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e9344f39-e275-5886-a976-d3a36b705782', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 11, '<p>පුද්ගලික පාර්ශ්ව දෙකක් අතර ඇතිවන ආරවුල් නිරාකරණය සඳහා යොදා ගත හැකි නීතිය කුමක්ද?</p>', '<p>පුද්ගලික පාර්ශ්ව දෙකක් අතර ඇතිවන ආරවුල් නිරාකරණය සඳහා යොදා ගත හැකි නීතිය කුමක්ද?</p>', NULL, 'පුද්ගලයන් දෙදෙනෙකු හෝ පාර්ශ්ව දෙකක් අතර ඇතිවන දේපළ ආරවුල්, ගිවිසුම් කඩවීම්, වන්දි ඉල්ලා සිටීම් වැනි පෞද්ගලික ආරවුල් විසඳීම සඳහා ''සිවිල් නීතිය'' (Civil Law) යොදා ගැනේ.<br>සමාජයට එරෙහිව කෙරෙන බරපතළ වරදවල් සඳහා අපරාධ නීතිය අදාළ වේ.', 'පුද්ගලයන් දෙදෙනෙකු හෝ පාර්ශ්ව දෙකක් අතර ඇතිවන දේපළ ආරවුල්, ගිවිසුම් කඩවීම්, වන්දි ඉල්ලා සිටීම් වැනි පෞද්ගලික ආරවුල් විසඳීම සඳහා ''සිවිල් නීතිය'' (Civil Law) යොදා ගැනේ.<br>සමාජයට එරෙහිව කෙරෙන බරපතළ වරදවල් සඳහා අපරාධ නීතිය අදාළ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
