INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e030ca0e-35aa-40fd-b629-bde55a629c0d', 'e9344f39-e275-5886-a976-d3a36b705782', 'රෝම ලන්දේසි නීතිය', 'රෝම ලන්දේසි නීතිය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5022ba5b-557b-550f-b03d-4adfe7d8f2fd', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 12, '<p>රටක ව්‍යවස්ථාදායකය සතු කාර්යයක් සඳහන් වන වරණය තෝරන්න.</p>', '<p>රටක ව්‍යවස්ථාදායකය සතු කාර්යයක් සඳහන් වන වරණය තෝරන්න.</p>', NULL, 'ආණ්ඩුවේ ප්‍රධාන අංශ තුනෙන්, ව්‍යවස්ථාදායකයේ (පාර්ලිමේන්තුවේ) ප්‍රධාන කාර්යය වන්නේ ''නීති සම්පාදනය කිරීම හෙවත් නීති සම්මත කිරීමයි''.<br>නීති ක්‍රියාවට නැංවීම විධායකය සතු වන අතර, නීති විවරණය කිරීම හා පසිඳලීම අධිකරණය සතු කාර්යයන් වේ.', 'ආණ්ඩුවේ ප්‍රධාන අංශ තුනෙන්, ව්‍යවස්ථාදායකයේ (පාර්ලිමේන්තුවේ) ප්‍රධාන කාර්යය වන්නේ ''නීති සම්පාදනය කිරීම හෙවත් නීති සම්මත කිරීමයි''.<br>නීති ක්‍රියාවට නැංවීම විධායකය සතු වන අතර, නීති විවරණය කිරීම හා පසිඳලීම අධිකරණය සතු කාර්යයන් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
