INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f6d1ea59-3ba8-4210-8417-fb3f2cf49c53', '5022ba5b-557b-550f-b03d-4adfe7d8f2fd', 'නීති සම්මත කිරීම', 'නීති සම්මත කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aeb342e2-d25c-5f0e-8b05-236e783552ed', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 13, '<p>ගැටුම් නිරාකරණයේදී ''සාකච්ඡා ක්‍රමය'' භාවිත කිරීමෙන් දෙපාර්ශ්වයටම ලැබිය හැකි වාසියක් වන්නේ,</p>', '<p>ගැටුම් නිරාකරණයේදී ''සාකච්ඡා ක්‍රමය'' භාවිත කිරීමෙන් දෙපාර්ශ්වයටම ලැබිය හැකි වාසියක් වන්නේ,</p>', NULL, 'සාකච්ඡා ක්‍රමයේදී (Negotiation) බාහිර පාර්ශ්වයකගේ මැදිහත් වීමකින් තොරව ගැටුමට අදාළ පාර්ශ්ව දෙක පමණක් එක්ව සාකච්ඡා කර එකඟතාවකට පැමිණේ.<br>එබැවින් මෙහිදී ''ජය-ජය'' (Win-Win) විසඳුමක් දෙපාර්ශ්වයටම හිමි වේ.', 'සාකච්ඡා ක්‍රමයේදී (Negotiation) බාහිර පාර්ශ්වයකගේ මැදිහත් වීමකින් තොරව ගැටුමට අදාළ පාර්ශ්ව දෙක පමණක් එක්ව සාකච්ඡා කර එකඟතාවකට පැමිණේ.<br>එබැවින් මෙහිදී ''ජය-ජය'' (Win-Win) විසඳුමක් දෙපාර්ශ්වයටම හිමි වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
