INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('539744dd-4106-4e4f-8772-beaea184d516', '965b7d54-ec74-52c2-a774-f4178d566ac0', 'භූමිකම්පා නිතර ඇති වීම', 'භූමිකම්පා නිතර ඇති වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aa9777f6-b3a5-58c7-9c2b-e9c15a3b5825', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 19, '<p>සාප්පු හා කාර්යාල සේවක පනත මගින් ආරක්ෂාව සැපයෙන්නේ පහත සඳහන් කුමන කණ්ඩායමක අයිතිවාසිකම් සඳහා ද?</p>', '<p>සාප්පු හා කාර්යාල සේවක පනත මගින් ආරක්ෂාව සැපයෙන්නේ පහත සඳහන් කුමන කණ්ඩායමක අයිතිවාසිකම් සඳහා ද?</p>', NULL, '1954 අංක 19 දරන සාප්පු හා කාර්යාලීය සේවකයන් පිළිබඳ පනත මගින් එම ආයතනවල සේවය කරන සේවකයන්ගේ (කම්කරුවන්ගේ) සේවා කොන්දේසි, නිවාඩු, වැටුප් හා සේවා පරිසරය පිළිබඳ අයිතිවාසිකම් තහවුරු කරයි.', '1954 අංක 19 දරන සාප්පු හා කාර්යාලීය සේවකයන් පිළිබඳ පනත මගින් එම ආයතනවල සේවය කරන සේවකයන්ගේ (කම්කරුවන්ගේ) සේවා කොන්දේසි, නිවාඩු, වැටුප් හා සේවා පරිසරය පිළිබඳ අයිතිවාසිකම් තහවුරු කරයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
