INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0403b39c-370e-54d5-9f0f-9ca0c85c125c', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 23, '<p>ගෝලීයකරණය තුළ දක්නට ලැබෙන විශේෂ ලක්ෂණයක් වන්නේ,</p>', '<p>ගෝලීයකරණය තුළ දක්නට ලැබෙන විශේෂ ලක්ෂණයක් වන්නේ,</p>', NULL, 'ගෝලීයකරණය හේතුවෙන් තොරතුරු තාක්ෂණය හා ප්‍රවාහනය දියුණු වී ඇති අතර, ඒ හරහා ලෝකයේ ඕනෑම රටක සිට තවත් රටක රැකියා හා ව්‍යාපාරවල නිරත වීමට හැකිවීම නිසා ''වැඩ ලෝකය'' (World of Work) විශාල ලෙස පුළුල් වී ඇත.', 'ගෝලීයකරණය හේතුවෙන් තොරතුරු තාක්ෂණය හා ප්‍රවාහනය දියුණු වී ඇති අතර, ඒ හරහා ලෝකයේ ඕනෑම රටක සිට තවත් රටක රැකියා හා ව්‍යාපාරවල නිරත වීමට හැකිවීම නිසා ''වැඩ ලෝකය'' (World of Work) විශාල ලෙස පුළුල් වී ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d8817f63-ff41-4682-a308-efe0e342f383', '0403b39c-370e-54d5-9f0f-9ca0c85c125c', 'දේපළ අයිතිය පොදු වීමයි.', 'දේපළ අයිතිය පොදු වීමයි.', NULL, 'sanitized', 'v1', 0, 1);
