INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('35969195-2d4e-466f-b49e-16efa09be842', '0403b39c-370e-54d5-9f0f-9ca0c85c125c', 'ගෝලීය වෙළෙඳ පොළ පටු වීමයි.', 'ගෝලීය වෙළෙඳ පොළ පටු වීමයි.', NULL, 'sanitized', 'v1', 2, 0);
