INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5ee317e2-cfa9-48cb-9ed4-d92bba7b16e6', 'c7bdd556-338a-5a06-b2e1-813c9d3c29e5', 'ආගම, භාෂාව, ජලය, ඇදහිලි සහ විශ්වාස', 'ආගම, භාෂාව, ජලය, ඇදහිලි සහ විශ්වාස', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('db0049e9-5ff1-4def-a36a-470fd65d93ea', 'c7bdd556-338a-5a06-b2e1-813c9d3c29e5', 'ආගම, භාෂාව, කලාව, දේශගුණය සහ විශ්වාස', 'ආගම, භාෂාව, කලාව, දේශගුණය සහ විශ්වාස', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('89617d75-d6b4-5dd3-ae4b-c0effb87349c', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 25, '<p>නාවුක අධිකරණ බලය සතු අධිකරණ ආයතනය මින් කුමක්ද?</p>', '<p>නාවුක අධිකරණ බලය සතු අධිකරණ ආයතනය මින් කුමක්ද?</p>', NULL, 'ශ්‍රී ලංකාවේ ආණ්ඩුක්‍රම ව්‍යවස්ථාවට හා අධිකරණ සංවිධාන පනතට අනුව නාවුක හෙවත් අද්මිරාල්ති අධිකරණ බලය (Admiralty Jurisdiction) ක්‍රියාත්මක කිරීමේ මුල් අවස්ථා බලය පැවරී ඇත්තේ ''කොළඹ මහාධිකරණයට'' ය.', 'ශ්‍රී ලංකාවේ ආණ්ඩුක්‍රම ව්‍යවස්ථාවට හා අධිකරණ සංවිධාන පනතට අනුව නාවුක හෙවත් අද්මිරාල්ති අධිකරණ බලය (Admiralty Jurisdiction) ක්‍රියාත්මක කිරීමේ මුල් අවස්ථා බලය පැවරී ඇත්තේ ''කොළඹ මහාධිකරණයට'' ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
