INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ec278cbd-3b29-4710-a6e8-2924bd29a4d6', '89617d75-d6b4-5dd3-ae4b-c0effb87349c', 'දිසා අධිකරණය', 'දිසා අධිකරණය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d192acc3-d239-5625-a2aa-af22b120769b', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 26, '<p>රටක යහපාලනය ක්‍රියාත්මක වීමෙන් අත්වන වැදගත්ම ප්‍රතිලාභය වන්නේ,</p>', '<p>රටක යහපාලනය ක්‍රියාත්මක වීමෙන් අත්වන වැදගත්ම ප්‍රතිලාභය වන්නේ,</p>', NULL, 'යහපාලනයක මූලික ලක්ෂණ වන විනිවිදභාවය, වගවීම, නීතියේ ආධිපත්‍යය හා සාධාරණත්වය පැවතීම හරහා සමාජයේ ජීවත් වන විවිධ ජාතික, ආගමික හා සමාජ කණ්ඩායම් අතර අන්‍යෝන්‍ය විශ්වාසය සහ සංහිඳියාව තහවුරු වීම එහි ඉහළම ප්‍රතිලාභයයි.', 'යහපාලනයක මූලික ලක්ෂණ වන විනිවිදභාවය, වගවීම, නීතියේ ආධිපත්‍යය හා සාධාරණත්වය පැවතීම හරහා සමාජයේ ජීවත් වන විවිධ ජාතික, ආගමික හා සමාජ කණ්ඩායම් අතර අන්‍යෝන්‍ය විශ්වාසය සහ සංහිඳියාව තහවුරු වීම එහි ඉහළම ප්‍රතිලාභයයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('be21794a-51b5-43a8-bd8d-f206580aac52', 'd192acc3-d239-5625-a2aa-af22b120769b', 'නිදහස් හා සාධාරණ මැතිවරණ පැවැත්වීමය.', 'නිදහස් හා සාධාරණ මැතිවරණ පැවැත්වීමය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8dd5b8b3-9a2c-4879-a88a-09ada973023f', 'd192acc3-d239-5625-a2aa-af22b120769b', 'ආදායම් බෙදීයාමේ විෂමතාව අඩු වීම ය.', 'ආදායම් බෙදීයාමේ විෂමතාව අඩු වීම ය.', NULL, 'sanitized', 'v1', 1, 0);
