INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('663121d7-389c-4bae-b1d6-a4354aaedbef', 'd192acc3-d239-5625-a2aa-af22b120769b', 'ජන කණ්ඩායම් අතර විශ්වාසය තහවුරු වීම ය.', 'ජන කණ්ඩායම් අතර විශ්වාසය තහවුරු වීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3ff1f2f7-7594-505b-a0e0-dd8b7eaff57a', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 27, '<p>මධ්‍යම ආණ්ඩුව, පළාත් සභා හා පළාත් පාලන ආයතන සම්බන්ධව පුරවැසියාගෙන් ඉටු විය යුතු යුතුකමක් වන්නේ කුමක්ද?</p>', '<p>මධ්‍යම ආණ්ඩුව, පළාත් සභා හා පළාත් පාලන ආයතන සම්බන්ධව පුරවැසියාගෙන් ඉටු විය යුතු යුතුකමක් වන්නේ කුමක්ද?</p>', NULL, 'රජය මඟින් සහ පළාත් පාලන ආයතන මඟින් නඩත්තු කරන පොදු දේපළ සහ සංස්කෘතික උරුමයන් විනාශ නොකර ආරක්ෂා කිරීම පුරවැසියන් සතු නෛතික හා සදාචාරාත්මක යුතුකමකි.', 'රජය මඟින් සහ පළාත් පාලන ආයතන මඟින් නඩත්තු කරන පොදු දේපළ සහ සංස්කෘතික උරුමයන් විනාශ නොකර ආරක්ෂා කිරීම පුරවැසියන් සතු නෛතික හා සදාචාරාත්මක යුතුකමකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1e1ffd0b-9c94-4177-b0b7-62a6b5e21ea6', '3ff1f2f7-7594-505b-a0e0-dd8b7eaff57a', 'ඵලදායි ජීවන වෘත්තියක නිරත වීම', 'ඵලදායි ජීවන වෘත්තියක නිරත වීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('47583f32-03e4-4fcc-b2b4-0bdfeeaf467a', '3ff1f2f7-7594-505b-a0e0-dd8b7eaff57a', 'සමාජ සංහිඳියාව ඇති කිරීම', 'සමාජ සංහිඳියාව ඇති කිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2aa440fc-1b21-4a0d-96a7-00424c5f9556', '3ff1f2f7-7594-505b-a0e0-dd8b7eaff57a', 'සංස්කෘතික උරුම ආරක්ෂා කිරීම', 'සංස්කෘතික උරුම ආරක්ෂා කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('49b48be9-ece9-40bd-b954-686ee6636159', '3ff1f2f7-7594-505b-a0e0-dd8b7eaff57a', 'ජාතික අභිමානය ඉහළ නැංවීම', 'ජාතික අභිමානය ඉහළ නැංවීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('08e9f992-5eb1-5b1c-9a3a-3148eaec988f', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 28, '<p>පහත සඳහන් පිළිතුරු අතුරෙන් ආර්ථික, සමාජීය හා සංස්කෘතික අයිතිවාසිකම් යටතට අයත් වන අයිතිවාසිකමක් වන්නේ කුමක්ද?</p>', '<p>පහත සඳහන් පිළිතුරු අතුරෙන් ආර්ථික, සමාජීය හා සංස්කෘතික අයිතිවාසිකම් යටතට අයත් වන අයිතිවාසිකමක් වන්නේ කුමක්ද?</p>', NULL, 'මත ප්‍රකාශ කිරීම, ගමනාගමනය සහ පෞද්ගලික ආරක්ෂාව සිවිල් හා දේශපාලන අයිතීන් වේ.<br>පෞද්ගලික දේපළ දැරීම, රැකියා කිරීම සහ සාධාරණ වැටුප් ලැබීම ආර්ථික අයිතිවාසිකම් ගණයට අයත් වේ.', 'මත ප්‍රකාශ කිරීම, ගමනාගමනය සහ පෞද්ගලික ආරක්ෂාව සිවිල් හා දේශපාලන අයිතීන් වේ.<br>පෞද්ගලික දේපළ දැරීම, රැකියා කිරීම සහ සාධාරණ වැටුප් ලැබීම ආර්ථික අයිතිවාසිකම් ගණයට අයත් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
