INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1a8e732d-57c3-4459-968f-e2886553c39d', '4381052d-4f0c-5f69-be93-1b97dc9c47f0', 'භෞතික ජීවන තත්ත්ව දර්ශකය', 'භෞතික ජීවන තත්ත්ව දර්ශකය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8f491f3a-c131-4aeb-9520-fbde47861ed5', '4381052d-4f0c-5f69-be93-1b97dc9c47f0', 'මානව දරිද්‍රතා දර්ශකය', 'මානව දරිද්‍රතා දර්ශකය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3db624d9-d0df-5e55-9a02-5c2a949e3b44', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 31, '<p>දේශගුණික වෙනස්විම් නිසා පරිසරය තුළ සිදුවන අහිතකර ප්‍රතිඵලය දක්වා ඇති වරණය තෝරන්න.</p>', '<p>දේශගුණික වෙනස්විම් නිසා පරිසරය තුළ සිදුවන අහිතකර ප්‍රතිඵලය දක්වා ඇති වරණය තෝරන්න.</p>', NULL, 'ගෝලීය උණුසුම හා දේශගුණික වෙනස්වීම් හේතුවෙන් ධ්‍රැව ප්‍රදේශවල ග්ලැසියර හා අයිස් කඳු දියවීම වේගවත් වී ඇත.<br>මේ නිසා ලෝකයේ සාගර ජල මට්ටම ඉහළ යාමෙන් පහත් බිම් හා වෙරළබඩ කලාප ජලයෙන් යටවීමේ දැඩි අවදානමක් මතු වී තිබේ.', 'ගෝලීය උණුසුම හා දේශගුණික වෙනස්වීම් හේතුවෙන් ධ්‍රැව ප්‍රදේශවල ග්ලැසියර හා අයිස් කඳු දියවීම වේගවත් වී ඇත.<br>මේ නිසා ලෝකයේ සාගර ජල මට්ටම ඉහළ යාමෙන් පහත් බිම් හා වෙරළබඩ කලාප ජලයෙන් යටවීමේ දැඩි අවදානමක් මතු වී තිබේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
