INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cac14006-35a1-413c-9a75-1b2b9207fe38', '2bfab78f-7e3a-53da-b691-01078b7cea50', 'නීතිය හා සාමය ආරක්ෂා කිරීම', 'නීතිය හා සාමය ආරක්ෂා කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7c2b14c3-791d-437b-b851-898fde412524', '2bfab78f-7e3a-53da-b691-01078b7cea50', 'ආගම් අතර සංහිදියාව ඇති කිරීම', 'ආගම් අතර සංහිදියාව ඇති කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('32ac423e-54ec-5985-8013-294779c987b0', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 37, '<p>පළාත් සභාවක මහ ඇමති සහ අමාත්‍ය මණ්ඩලය සතු කාර්යයක් වන්නේ,</p>', '<p>පළාත් සභාවක මහ ඇමති සහ අමාත්‍ය මණ්ඩලය සතු කාර්යයක් වන්නේ,</p>', NULL, 'පළාත් සභාවේ විධායක බලය ක්‍රියාත්මක කරන මහ ඇමතිවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයේ ප්‍රධාන වගකීම වන්නේ, පළාත් සභා බලතල ලැයිස්තුවට අයත් විෂයයන්ට අදාළව තම පළාතේ ආර්ථික සංවර්ධන සැලසුම් සකස් කිරීම සහ පරිපාලන කටයුතු මෙහෙයවීමයි.', 'පළාත් සභාවේ විධායක බලය ක්‍රියාත්මක කරන මහ ඇමතිවරයා ප්‍රමුඛ අමාත්‍ය මණ්ඩලයේ ප්‍රධාන වගකීම වන්නේ, පළාත් සභා බලතල ලැයිස්තුවට අයත් විෂයයන්ට අදාළව තම පළාතේ ආර්ථික සංවර්ධන සැලසුම් සකස් කිරීම සහ පරිපාලන කටයුතු මෙහෙයවීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
