INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fbea7927-1119-46a9-bc75-4d15fedb32da', '32ac423e-54ec-5985-8013-294779c987b0', 'පළාතේ ආර්ථික සංවර්ධනය හා පරිපාලනය සැලසුම් කිරීමයි.', 'පළාතේ ආර්ථික සංවර්ධනය හා පරිපාලනය සැලසුම් කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7af30fd9-7a73-4680-aff1-cf7b9d6ebf8c', '32ac423e-54ec-5985-8013-294779c987b0', 'පළාතේ මාර්ග සංවර්ධනය වැඩි කර ගැනීමට කටයුතු කිරීමයි.', 'පළාතේ මාර්ග සංවර්ධනය වැඩි කර ගැනීමට කටයුතු කිරීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f4668f5a-aa26-5a1c-b80a-9a39017478b9', '75dfd4c7-68aa-5be9-928c-48f01ecb649b', 38, '<p>ජාතික පරිසර පනතට අනුව පරිසර සංරක්ෂණය පිළිබඳ වගකීම දරන ප්‍රධාන ආයතනය කුමක්ක්ද?</p>', '<p>ජාතික පරිසර පනතට අනුව පරිසර සංරක්ෂණය පිළිබඳ වගකීම දරන ප්‍රධාන ආයතනය කුමක්ක්ද?</p>', NULL, '1980 අංක 47 දරන ජාතික පාරිසරික පනත මගින් ශ්‍රී ලංකාවේ පරිසරය කළමනාකරණය, ආරක්ෂා කිරීම සහ දූෂණය පාලනය කිරීම සඳහා ප්‍රධාන නියාමන ආයතනය ලෙස ''මධ්‍යම පරිසර අධිකාරිය'' (CEA - Central Environmental Authority) ස්ථාපිත කරන ලදී.', '1980 අංක 47 දරන ජාතික පාරිසරික පනත මගින් ශ්‍රී ලංකාවේ පරිසරය කළමනාකරණය, ආරක්ෂා කිරීම සහ දූෂණය පාලනය කිරීම සඳහා ප්‍රධාන නියාමන ආයතනය ලෙස ''මධ්‍යම පරිසර අධිකාරිය'' (CEA - Central Environmental Authority) ස්ථාපිත කරන ලදී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
