INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('505eebd0-2e70-501e-a4be-24add701dade', '794b19f4-efb1-5270-a08f-0f92a17d9ff9', 1, '<p>පාසලකට පරිගණක උපකරණ පරිත්‍යාග කිරීමට සංගමයක් මනාපය පළකර ඇත. පාසල තම පුස්තකාල කළමනා කරණ පද්ධතිය ගොඩනැගීමට සැලසුම් කරයි නම්, පහත කුමන දෘඪාංග පාසල සංගමයෙන් ඉල්ලා සිටීම සුදුසු ද?</p>', '<p>පාසලකට පරිගණක උපකරණ පරිත්‍යාග කිරීමට සංගමයක් මනාපය පළකර ඇත. පාසල තම පුස්තකාල කළමනා කරණ පද්ධතිය ගොඩනැගීමට සැලසුම් කරයි නම්, පහත කුමන දෘඪාංග පාසල සංගමයෙන් ඉල්ලා සිටීම සුදුසු ද?</p>', NULL, 'පුස්තකාල පද්ධතියක් සඳහා පොත්වල තොරතුරු ඇතුළත් කිරීමට තීරු කේත කියවනයක් (Barcode reader) සහ දත්ත සැකසීමට මේස පරිගණකයක් (Desktop PC) වඩාත් යෝග්‍ය වේ.', 'පුස්තකාල පද්ධතියක් සඳහා පොත්වල තොරතුරු ඇතුළත් කිරීමට තීරු කේත කියවනයක් (Barcode reader) සහ දත්ත සැකසීමට මේස පරිගණකයක් (Desktop PC) වඩාත් යෝග්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4d25bdaa-7950-4855-9bec-b29b83907067', '505eebd0-2e70-501e-a4be-24add701dade', 'මේස (desktop) පරිගණකයක්, තීරු කේත කියවනයක් (barcode reader)', 'මේස (desktop) පරිගණකයක්, තීරු කේත කියවනයක් (barcode reader)', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bd3a2e60-0ec3-4a1b-9975-d2fb104c5373', '505eebd0-2e70-501e-a4be-24add701dade', 'මේස පරිගණකයක්, ලකුණු කරනයක් (plotter)', 'මේස පරිගණකයක්, ලකුණු කරනයක් (plotter)', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('22c68bb5-f46c-44c6-a7ce-93af8a59eef6', '505eebd0-2e70-501e-a4be-24add701dade', 'උකුළු පරිගණකයක් (laptop), මෙහෙයුම් යටියක් (joystick)', 'උකුළු පරිගණකයක් (laptop), මෙහෙයුම් යටියක් (joystick)', NULL, 'sanitized', 'v1', 2, 0);
