INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cc5f6e33-1a94-5ef1-b79c-ad7449cba07d', '794b19f4-efb1-5270-a08f-0f92a17d9ff9', 6, '<p>පහත ඒවායින් විශාලතම සංඛ්‍යාව කුමක්ද?</p>', '<p>පහත ඒවායින් විශාලතම සංඛ්‍යාව කුමක්ද?</p>', NULL, 'සියලුම අගයන් දශම (Base 10) සංඛ්‍යා බවට පරිවර්තනය කළ විට:<br>$10000100_2 = 132$<br>$15_8 = 13$<br>$85_{10} = 85$<br>$C2_{16} = (12 \times 16) + 2 = 194$<br>එබැවින් විශාලතම අගය වන්නේ $C2_{16}$ වේ.', 'සියලුම අගයන් දශම (Base 10) සංඛ්‍යා බවට පරිවර්තනය කළ විට:<br>$10000100_2 = 132$<br>$15_8 = 13$<br>$85_{10} = 85$<br>$C2_{16} = (12 \times 16) + 2 = 194$<br>එබැවින් විශාලතම අගය වන්නේ $C2_{16}$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
