INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8ca42151-cf37-5088-be32-a7e85acf5ae0', '794b19f4-efb1-5270-a08f-0f92a17d9ff9', 7, '<p>ද්විමය $1000 0101_2$ ට තුල්‍ය දශමය සංඛ්‍යාව කුමක්ද?</p>', '<p>ද්විමය $1000 0101_2$ ට තුල්‍ය දශමය සංඛ්‍යාව කුමක්ද?</p>', NULL, 'ද්විමය අගය දශමයට හැරවීම: $(1 \times 128) + (0 \times 64) + (0 \times 32) + (0 \times 16) + (0 \times 8) + (1 \times 4) + (0 \times 2) + (1 \times 1) = 128 + 4 + 1 = 133_{10}$.', 'ද්විමය අගය දශමයට හැරවීම: $(1 \times 128) + (0 \times 64) + (0 \times 32) + (0 \times 16) + (0 \times 8) + (1 \times 4) + (0 \times 2) + (1 \times 1) = 128 + 4 + 1 = 133_{10}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
