INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b4f7a677-5018-59f2-9e22-c8d6f20aa922', '794b19f4-efb1-5270-a08f-0f92a17d9ff9', 8, '<p>අෂ්ටක $1156_8$ ට තුල්‍ය ෂඩ් දශමය සංඛ්‍යාව කුමක්ද?</p>', '<p>අෂ්ටක $1156_8$ ට තුල්‍ය ෂඩ් දශමය සංඛ්‍යාව කුමක්ද?</p>', NULL, 'පළමුව අෂ්ටක අගය ද්විමයට පරිවර්තනය කරමු: $1 \rightarrow 001$, $1 \rightarrow 001$, $5 \rightarrow 101$, $6 \rightarrow 110$. ද්විමය අගය: $001001101110_2$.<br>ඉන්පසු බිටු 4 බැගින් කාණ්ඩ කරමු: $0010$ $(2)$, $0110$ $(6)$, $1110$ $(E)$. එබැවින් ෂඩ් දශම අගය $26E_{16}$ වේ.', 'පළමුව අෂ්ටක අගය ද්විමයට පරිවර්තනය කරමු: $1 \rightarrow 001$, $1 \rightarrow 001$, $5 \rightarrow 101$, $6 \rightarrow 110$. ද්විමය අගය: $001001101110_2$.<br>ඉන්පසු බිටු 4 බැගින් කාණ්ඩ කරමු: $0010$ $(2)$, $0110$ $(6)$, $1110$ $(E)$. එබැවින් ෂඩ් දශම අගය $26E_{16}$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
