INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d54422dd-a7be-5136-b664-bf98579d6fdd', '794b19f4-efb1-5270-a08f-0f92a17d9ff9', 10, '<p>ASCII වගුවෙන් ගෙන ඇති පහත දැක්වෙන අනුලක්ෂණය - අගය අනුරූපණ සලකන්න.<br>O - 79, / - 47, L - 76, o - 111, l - 108<br>O/L හි ASCII නිරූපණය ද්විමය ලෙස පහත කවරක දැක්වේ ද?</p>', '<p>ASCII වගුවෙන් ගෙන ඇති පහත දැක්වෙන අනුලක්ෂණය - අගය අනුරූපණ සලකන්න.<br>O - 79, / - 47, L - 76, o - 111, l - 108<br>O/L හි ASCII නිරූපණය ද්විමය ලෙස පහත කවරක දැක්වේ ද?</p>', NULL, '$79_{10} = 64+8+4+2+1 = 1001111_2$ (O)<br>$47_{10} = 32+8+4+2+1 = 0101111_2$ (/)<br>$76_{10} = 64+8+4 = 1001100_2$ (L)<br>එබැවින් නිවැරදි ද්විමය නිරූපණය 1001111 0101111 1001100 වේ.', '$79_{10} = 64+8+4+2+1 = 1001111_2$ (O)<br>$47_{10} = 32+8+4+2+1 = 0101111_2$ (/)<br>$76_{10} = 64+8+4 = 1001100_2$ (L)<br>එබැවින් නිවැරදි ද්විමය නිරූපණය 1001111 0101111 1001100 වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
