INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7eac8bba-1bb3-4f50-b07b-ec20cd19c36f', '087c25e3-e326-5b2e-ab2b-63cfc1ded50e', 'N=1? කොන්දේසිය N=0? ලෙස වෙනස් කිරීම', 'N=1? කොන්දේසිය N=0? ලෙස වෙනස් කිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6f34e417-88fd-4dc5-b1cf-e5ac678827e3', '087c25e3-e326-5b2e-ab2b-63cfc1ded50e', 'N=1? කොන්දේසිය N=-1? ලෙස වෙනස් කිරීම', 'N=1? කොන්දේසිය N=-1? ලෙස වෙනස් කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b7e169f2-d503-4b52-8aac-e3f8a52fc17c', '087c25e3-e326-5b2e-ab2b-63cfc1ded50e', 'N ආදානය කළ විගසම එය පරීක්ෂා කොට සෘණ නම් ගැලීම අවසන් කිරීම', 'N ආදානය කළ විගසම එය පරීක්ෂා කොට සෘණ නම් ගැලීම අවසන් කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d65048af-95fa-5cca-8509-d88f213135c1', '794b19f4-efb1-5270-a08f-0f92a17d9ff9', 28, '<p>පසුගිය වසරේ එක් එක් මාසයේ බිත්තරයක සාමාන්‍ය මිල A නම් වූ අරාවේ (array) අඩංගු වේ.<br>A : 20, 25, 50, 55, 70, 65, 50, 60, 65, 50, 55, 49<br>ඉහළම සාමාන්‍ය මිල කුමන අරා අවයවයේ අඩංගු වේද?</p>', '<p>පසුගිය වසරේ එක් එක් මාසයේ බිත්තරයක සාමාන්‍ය මිල A නම් වූ අරාවේ (array) අඩංගු වේ.<br>A : 20, 25, 50, 55, 70, 65, 50, 60, 65, 50, 55, 49<br>ඉහළම සාමාන්‍ය මිල කුමන අරා අවයවයේ අඩංගු වේද?</p>', NULL, 'අරාවේ වැඩිම අගය 70 වේ. අරාවක දර්ශක (Index) ආරම්භ වන්නේ 0 න් බැවින්, අගයන් පහත පරිදි වේ: A[0]=20, A[1]=25, A[2]=50, A[3]=55, A[4]=70. එබැවින් පිළිතුර A[4] වේ.', 'අරාවේ වැඩිම අගය 70 වේ. අරාවක දර්ශක (Index) ආරම්භ වන්නේ 0 න් බැවින්, අගයන් පහත පරිදි වේ: A[0]=20, A[1]=25, A[2]=50, A[3]=55, A[4]=70. එබැවින් පිළිතුර A[4] වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
