INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f33d0053-dffd-4530-9005-841ef6d68c4c', '64f06378-9ee8-5458-88b8-a3a6748fc383', 'ඒකක පරීක්ෂාව $\rightarrow$ සමස්ත පරීක්ෂාව $\rightarrow$ පද්ධති පරීක්ෂාව $\rightarrow$ පරිශීලකයන්ගේ ප්‍රතිග්‍රහණ පරීක්ෂාව', 'ඒකක පරීක්ෂාව $\rightarrow$ සමස්ත පරීක්ෂාව $\rightarrow$ පද්ධති පරීක්ෂාව $\rightarrow$ පරිශීලකයන්ගේ ප්‍රතිග්‍රහණ පරීක්ෂාව', NULL, 'sanitized', 'v1', 1, 0);
