INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6804ed16-c721-5880-83d2-7a7d250923b8', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 4, '<p>$O_2, H_2O, H_2O_2, OF_2$ හා $O_2F_2$ ($H_2O_2$ වලට සමාන ව්‍යුහයක් ඇත.) යන අණු, ඔක්සිජන්හි ($O$) ඔක්සිකරණ අවස්ථා අඩු වන පිළිවෙළට සැකසූ විට නිවැරදි පිළිතුර වනුයේ,</p>', '<p>$O_2, H_2O, H_2O_2, OF_2$ හා $O_2F_2$ ($H_2O_2$ වලට සමාන ව්‍යුහයක් ඇත.) යන අණු, ඔක්සිජන්හි ($O$) ඔක්සිකරණ අවස්ථා අඩු වන පිළිවෙළට සැකසූ විට නිවැරදි පිළිතුර වනුයේ,</p>', NULL, 'එක් එක් සංයෝගයේ ඔක්සිජන්හි ඔක්සිකරණ අවස්ථා ගණනය කිරීම:<br>$OF_2$ හි $O = +2$<br>$O_2F_2$ හි $O = +1$<br>$O_2$ හි $O = 0$<br>$H_2O_2$ හි $O = -1$<br>$H_2O$ හි $O = -2$<br>අඩු වන පිළිවෙළ: $+2 > +1 > 0 > -1 > -2$. එනම් $OF_2 > O_2F_2 > O_2 > H_2O_2 > H_2O$ වේ[cite: 1].', 'එක් එක් සංයෝගයේ ඔක්සිජන්හි ඔක්සිකරණ අවස්ථා ගණනය කිරීම:<br>$OF_2$ හි $O = +2$<br>$O_2F_2$ හි $O = +1$<br>$O_2$ හි $O = 0$<br>$H_2O_2$ හි $O = -1$<br>$H_2O$ හි $O = -2$<br>අඩු වන පිළිවෙළ: $+2 > +1 > 0 > -1 > -2$. එනම් $OF_2 > O_2F_2 > O_2 > H_2O_2 > H_2O$ වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
