INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('99924cdb-385d-443b-b887-f1b2366b1ea0', '6804ed16-c721-5880-83d2-7a7d250923b8', '$OF_2 > O_2F_2 > O_2 > H_2O_2 > H_2O$', '$OF_2 > O_2F_2 > O_2 > H_2O_2 > H_2O$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2bbd599c-b890-58e5-a7bf-71b762677109', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 5, '<p>තයෝසයනේට් අයනය $SCN^-$ සඳහා වඩාත්ම පිළිගත හැකි ලුවිස් ව්‍යුහය වනුයේ,</p>', '<p>තයෝසයනේට් අයනය $SCN^-$ සඳහා වඩාත්ම පිළිගත හැකි ලුවිස් ව්‍යුහය වනුයේ,</p>', NULL, '$SCN^-$ අයනය සඳහා සම්ප්‍රයුක්ත ව්‍යුහ කිහිපයක් ඇඳිය හැක. නයිට්‍රජන් ($N$), සල්ෆර් ($S$) ට වඩා විද්‍යුත් සෘණතාවයෙන් වැඩි බැවින් සෘණ ආරෝපණය නයිට්‍රජන් පරමාණුව මත පිහිටන $\ddot{S} = C = \ddot{N}^-$ ව්‍යුහය වඩාත්ම ස්ථායී වේ[cite: 1].', '$SCN^-$ අයනය සඳහා සම්ප්‍රයුක්ත ව්‍යුහ කිහිපයක් ඇඳිය හැක. නයිට්‍රජන් ($N$), සල්ෆර් ($S$) ට වඩා විද්‍යුත් සෘණතාවයෙන් වැඩි බැවින් සෘණ ආරෝපණය නයිට්‍රජන් පරමාණුව මත පිහිටන $\ddot{S} = C = \ddot{N}^-$ ව්‍යුහය වඩාත්ම ස්ථායී වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
