INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d0670281-b830-5b7d-a803-4a9ba64784c7', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 6, '<p>ඝනත්වය හා ස්කන්ධය අනුව $NaI$ $3\%$ වන $NaI$ $1.03~g~cm^{-3}$ ($Na=23, I=127$) ද්‍රාවණයක මවුලිකතාව ($mol~dm^{-3}$) වනුයේ,</p>', '<p>ඝනත්වය හා ස්කන්ධය අනුව $NaI$ $3\%$ වන $NaI$ $1.03~g~cm^{-3}$ ($Na=23, I=127$) ද්‍රාවණයක මවුලිකතාව ($mol~dm^{-3}$) වනුයේ,</p>', NULL, 'ද්‍රාවණයෙන් $1~dm^3$ ක ස්කන්ධය = $1.03~g~cm^{-3} \times 1000~cm^3 = 1030~g$<br>මෙහි ඇති $NaI$ ස්කන්ධය = $1030~g \times \frac{3}{100} = 30.9~g$<br>$NaI$ හි මවුලික ස්කන්ධය = $23 + 127 = 150~g~mol^{-1}$<br>$NaI$ මවුල ගණන = $\frac{30.9~g}{150~g~mol^{-1}} = 0.206~mol$<br>එබැවින් මවුලිකතාව $\approx 0.21~mol~dm^{-3}$ වේ[cite: 1].', 'ද්‍රාවණයෙන් $1~dm^3$ ක ස්කන්ධය = $1.03~g~cm^{-3} \times 1000~cm^3 = 1030~g$<br>මෙහි ඇති $NaI$ ස්කන්ධය = $1030~g \times \frac{3}{100} = 30.9~g$<br>$NaI$ හි මවුලික ස්කන්ධය = $23 + 127 = 150~g~mol^{-1}$<br>$NaI$ මවුල ගණන = $\frac{30.9~g}{150~g~mol^{-1}} = 0.206~mol$<br>එබැවින් මවුලිකතාව $\approx 0.21~mol~dm^{-3}$ වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7bfb76c4-6c0f-46b5-894a-a4249d345539', 'd0670281-b830-5b7d-a803-4a9ba64784c7', '0.21', '0.21', NULL, 'sanitized', 'v1', 0, 1);
