INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fef12c53-75d2-50ea-82a2-526982940e9f', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 7, '<p>$AgI$ හා $AgBr$ හි අවක්ෂේප ආස්‍රැත ජලය සුළු ප්‍රමාණයකට එකතු කරන ලදී. මෙම මිශ්‍රණය $25^\circ C$ හි දී සමතුලිතතාවයට එළඹීමට ඉඩ හරින ලදී. සමතුලිතතාවයේ දී ඝනයන් දෙකම පද්ධතියෙහි තිබෙන බව නිරීක්ෂණය කරන ලදී. පහත සඳහන් කුමන සම්බන්ධතාව මෙම ද්‍රාවණය සඳහා යෙදිය හැකි ද?<br><br>($25^\circ C$ හි දී $K_{sp(AgI)}=8.0\times10^{-17}~mol^2~dm^{-6}$, $K_{sp(AgBr)}=5.0\times10^{-13}~mol^2~dm^{-6}$)</p>', '<p>$AgI$ හා $AgBr$ හි අවක්ෂේප ආස්‍රැත ජලය සුළු ප්‍රමාණයකට එකතු කරන ලදී. මෙම මිශ්‍රණය $25^\circ C$ හි දී සමතුලිතතාවයට එළඹීමට ඉඩ හරින ලදී. සමතුලිතතාවයේ දී ඝනයන් දෙකම පද්ධතියෙහි තිබෙන බව නිරීක්ෂණය කරන ලදී. පහත සඳහන් කුමන සම්බන්ධතාව මෙම ද්‍රාවණය සඳහා යෙදිය හැකි ද?<br><br>($25^\circ C$ හි දී $K_{sp(AgI)}=8.0\times10^{-17}~mol^2~dm^{-6}$, $K_{sp(AgBr)}=5.0\times10^{-13}~mol^2~dm^{-6}$)</p>', NULL, 'සමතුලිතතාවයේදී පද්ධතියේ ඝනයන් දෙකම පවතින බැවින් ද්‍රාව්‍යතා ගුණිත ප්‍රකාශන දෙකම තෘප්ත කළ යුතුය.<br>$K_{sp(AgBr)} = [Ag^+][Br^-]$ සහ $K_{sp(AgI)} = [Ag^+][I^-]$<br>සමීකරණ දෙක බෙදීමෙන්:<br>$\frac{K_{sp(AgBr)}}{K_{sp(AgI)}} = \frac{[Br^-]}{[I^-]}$<br>$\frac{[Br^-]}{[I^-]} = \frac{5.0 \times 10^{-13}}{8.0 \times 10^{-17}} = \frac{5.0}{8.0} \times 10^4$ වේ[cite: 1].', 'සමතුලිතතාවයේදී පද්ධතියේ ඝනයන් දෙකම පවතින බැවින් ද්‍රාව්‍යතා ගුණිත ප්‍රකාශන දෙකම තෘප්ත කළ යුතුය.<br>$K_{sp(AgBr)} = [Ag^+][Br^-]$ සහ $K_{sp(AgI)} = [Ag^+][I^-]$<br>සමීකරණ දෙක බෙදීමෙන්:<br>$\frac{K_{sp(AgBr)}}{K_{sp(AgI)}} = \frac{[Br^-]}{[I^-]}$<br>$\frac{[Br^-]}{[I^-]} = \frac{5.0 \times 10^{-13}}{8.0 \times 10^{-17}} = \frac{5.0}{8.0} \times 10^4$ වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8e4a967a-d04a-4812-a7ad-a5b35ad4c8ea', 'fef12c53-75d2-50ea-82a2-526982940e9f', '$[Br^-]=\sqrt{5.0\times10^{-13}}~mol~dm^{-3}$, $[I^-]=\sqrt{8.0\times10^{-17}}~mol~dm^{-3}$', '$[Br^-]=\sqrt{5.0\times10^{-13}}~mol~dm^{-3}$, $[I^-]=\sqrt{8.0\times10^{-17}}~mol~dm^{-3}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f7dcae30-df6f-40fb-84df-614f19a0aba4', 'fef12c53-75d2-50ea-82a2-526982940e9f', '$[Br^-][I^-]=[Ag^+]^2$', '$[Br^-][I^-]=[Ag^+]^2$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('52321d15-011c-414f-b740-c3c0a44a01f5', 'fef12c53-75d2-50ea-82a2-526982940e9f', '$[Ag^+]=(\sqrt{5.0\times10^{-13}}+\sqrt{8.0\times10^{-17}})~mol~dm^{-3}$', '$[Ag^+]=(\sqrt{5.0\times10^{-13}}+\sqrt{8.0\times10^{-17}})~mol~dm^{-3}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ae19f057-2c8e-4721-bb32-d61609d26743', 'fef12c53-75d2-50ea-82a2-526982940e9f', '$\frac{[Br^-]}{[I^-]}=\frac{5.0}{8.0}\times10^4$', '$\frac{[Br^-]}{[I^-]}=\frac{5.0}{8.0}\times10^4$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a682bd59-26ea-42ba-9a41-749b94293135', 'fef12c53-75d2-50ea-82a2-526982940e9f', '$[Ag^+]=[Br^-]=[I^-]$', '$[Ag^+]=[Br^-]=[I^-]$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cff84657-6f2e-5211-95f5-fb110021b83a', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 8, '<p>පහත සඳහන් කුමන ප්‍රකාශය අසත්‍ය වේ ද?</p>', '<p>පහත සඳහන් කුමන ප්‍රකාශය අසත්‍ය වේ ද?</p>', NULL, 'දෙවන කාණ්ඩයේ (ක්ෂාරීය පාංශු ලෝහ) හයිඩ්‍රොක්සයිඩ වල ජලීය ද්‍රාව්‍යතාව කාණ්ඩය ඔස්සේ පහළට යනවිට වැඩි වේ. $Be(OH)_2$ සහ $Mg(OH)_2$ ජලයේ ඉතා අඩුවෙන් ද්‍රාව්‍ය වේ (පාහේ අද්‍රාව්‍ය වේ). එබැවින් සියලුම ලෝහවල හයිඩ්‍රොක්සයිඩ ජලයේ ද්‍රාව්‍ය වේ යන්න අසත්‍ය ප්‍රකාශයකි[cite: 1].', 'දෙවන කාණ්ඩයේ (ක්ෂාරීය පාංශු ලෝහ) හයිඩ්‍රොක්සයිඩ වල ජලීය ද්‍රාව්‍යතාව කාණ්ඩය ඔස්සේ පහළට යනවිට වැඩි වේ. $Be(OH)_2$ සහ $Mg(OH)_2$ ජලයේ ඉතා අඩුවෙන් ද්‍රාව්‍ය වේ (පාහේ අද්‍රාව්‍ය වේ). එබැවින් සියලුම ලෝහවල හයිඩ්‍රොක්සයිඩ ජලයේ ද්‍රාව්‍ය වේ යන්න අසත්‍ය ප්‍රකාශයකි[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8ccc0b2d-c4c0-4c70-bf1e-31bd6e2f57fa', 'cff84657-6f2e-5211-95f5-fb110021b83a', 'ආවර්තිතා වගුවේ දෙවන කාණ්ඩයේ සියලු ම ලෝහවල කාබනේට ජලයේ අද්‍රාව්‍ය වුව ද ඒවායේ බයිකාබනේට ද්‍රාව්‍ය වේ.', 'ආවර්තිතා වගුවේ දෙවන කාණ්ඩයේ සියලු ම ලෝහවල කාබනේට ජලයේ අද්‍රාව්‍ය වුව ද ඒවායේ බයිකාබනේට ද්‍රාව්‍ය වේ.', NULL, 'sanitized', 'v1', 0, 1);
