INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d4647f07-63d3-451b-915e-0200c4afbbd2', 'cff84657-6f2e-5211-95f5-fb110021b83a', 'Na සහ Mg වල ඔක්සයිඩ සහ හයිඩ්‍රොක්සයිඩ භාස්මික ගුණ පෙන්වන අතර Al හි ඔක්සයිඩය සහ හයිඩ්‍රොක්සයිඩය උභයගුණ ලක්ෂණ පෙන්නුම් කරයි.', 'Na සහ Mg වල ඔක්සයිඩ සහ හයිඩ්‍රොක්සයිඩ භාස්මික ගුණ පෙන්වන අතර Al හි ඔක්සයිඩය සහ හයිඩ්‍රොක්සයිඩය උභයගුණ ලක්ෂණ පෙන්නුම් කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('53825bfc-b9d4-47d9-9fa1-285c1bbe6359', 'cff84657-6f2e-5211-95f5-fb110021b83a', 'Si සහ S වල හයිඩ්‍රයිඩ දුර්වල ආම්ලික ගුණ පෙන්නුම් කරයි.', 'Si සහ S වල හයිඩ්‍රයිඩ දුර්වල ආම්ලික ගුණ පෙන්නුම් කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8ea75191-0b64-511d-a8d2-fb67646e6369', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 9, '<p>පරමාණුක අරයයන් වැඩි වන පිළිවෙලට මූල ද්‍රව්‍ය දී ඇත්තේ (වමේ සිට දකුණට) පහත කුමන ලැයිස්තුවෙහි ද?</p>', '<p>පරමාණුක අරයයන් වැඩි වන පිළිවෙලට මූල ද්‍රව්‍ය දී ඇත්තේ (වමේ සිට දකුණට) පහත කුමන ලැයිස්තුවෙහි ද?</p>', NULL, 'පරමාණුක අරය ආවර්තිතා වගුවේ කාණ්ඩයක් ඔස්සේ පහළට යනවිට වැඩි වන අතර, ආවර්තයක් ඔස්සේ දකුණට යනවිට අඩු වේ.<br>$B < Be$ (එකම ආවර්තයේ), $Be < Na$ (Na ඊළඟ ආවර්තයේ පිහිටයි), $Na < K$ (එකම කාණ්ඩයේ පහළට). එබැවින් $B, Be, Na, K$ යනු අරය වැඩි වන නිවැරදි පිළිවෙළයි[cite: 1].', 'පරමාණුක අරය ආවර්තිතා වගුවේ කාණ්ඩයක් ඔස්සේ පහළට යනවිට වැඩි වන අතර, ආවර්තයක් ඔස්සේ දකුණට යනවිට අඩු වේ.<br>$B < Be$ (එකම ආවර්තයේ), $Be < Na$ (Na ඊළඟ ආවර්තයේ පිහිටයි), $Na < K$ (එකම කාණ්ඩයේ පහළට). එබැවින් $B, Be, Na, K$ යනු අරය වැඩි වන නිවැරදි පිළිවෙළයි[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
