INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9a30c22a-be36-4d87-96eb-8cf2af1a2bcb', '238c0691-c16d-5767-80a0-9d09a7fb5982', '$He < CH_4 < CCl_4 < SiH_4 < CBr_4$', '$He < CH_4 < CCl_4 < SiH_4 < CBr_4$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1b01c6c6-cf41-5098-8154-a9eead534f5d', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 12, '<p>පහත දැක්වෙන ඒවායින් නිවැරදි ප්‍රකාශය හඳුනාගන්න.</p>', '<p>පහත දැක්වෙන ඒවායින් නිවැරදි ප්‍රකාශය හඳුනාගන්න.</p>', NULL, '($1$) වැරදියි. වැඩිම ශක්ති වෙනස ඇත්තේ $n=2 \rightarrow n=1$ අතරය ($\Delta E \propto \frac{1}{n_1^2} - \frac{1}{n_2^2}$).<br>($2$) වැරදියි. $OF_4$ සංයෝගය අස්ථායී වේ.<br>($3$) වැරදියි. අඩුම විද්‍යුත් සෘණතාව ඇත්තේ $Na$ වලටය.<br>($4$) නිවැරදියි. $Li^+$ යනු කුඩාම කැටායනයක් වන අතර $O^{2-}$ සාපේක්ෂව විශාල ඇනායනයකි. ඒවා අතර අරයෙහි වෙනස ඉතා ඉහළය.<br>($5$) වැරදියි. $CH_2Cl_2$ හි ලන්ඩන් අපකිරණ බල ද පවතී[cite: 1].', '($1$) වැරදියි. වැඩිම ශක්ති වෙනස ඇත්තේ $n=2 \rightarrow n=1$ අතරය ($\Delta E \propto \frac{1}{n_1^2} - \frac{1}{n_2^2}$).<br>($2$) වැරදියි. $OF_4$ සංයෝගය අස්ථායී වේ.<br>($3$) වැරදියි. අඩුම විද්‍යුත් සෘණතාව ඇත්තේ $Na$ වලටය.<br>($4$) නිවැරදියි. $Li^+$ යනු කුඩාම කැටායනයක් වන අතර $O^{2-}$ සාපේක්ෂව විශාල ඇනායනයකි. ඒවා අතර අරයෙහි වෙනස ඉතා ඉහළය.<br>($5$) වැරදියි. $CH_2Cl_2$ හි ලන්ඩන් අපකිරණ බල ද පවතී[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d08dc190-bb9e-4ee2-9900-351b92f2221d', '1b01c6c6-cf41-5098-8154-a9eead534f5d', 'හයිඩ්‍රජන් පරමාණුවක $n=2 \rightarrow n=1, n=3 \rightarrow n=2$ සහ $n=4 \rightarrow n=3$ ඉලෙක්ට්‍රෝන සංක්‍රමණ අතුරෙන් වැඩිම ශක්තියක් පිටකරනුයේ $n=3 \rightarrow n=2$ හි දී ය.', 'හයිඩ්‍රජන් පරමාණුවක $n=2 \rightarrow n=1, n=3 \rightarrow n=2$ සහ $n=4 \rightarrow n=3$ ඉලෙක්ට්‍රෝන සංක්‍රමණ අතුරෙන් වැඩිම ශක්තියක් පිටකරනුයේ $n=3 \rightarrow n=2$ හි දී ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('63088dfd-6215-481f-aba3-160153bba7d3', '1b01c6c6-cf41-5098-8154-a9eead534f5d', '$SF_4, OF_2$ සහ $OF_4$ විශේෂ අතුරෙන් අඩුවෙන්ම ස්ථායි වන්නේ $SF_4$ ය.', '$SF_4, OF_2$ සහ $OF_4$ විශේෂ අතුරෙන් අඩුවෙන්ම ස්ථායි වන්නේ $SF_4$ ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6fad6f76-8a61-4737-b7ea-1d9e89b8766b', '1b01c6c6-cf41-5098-8154-a9eead534f5d', '$Li, C, N, Na$ සහ $P$ මූලද්‍රව්‍ය අතුරෙන් විද්‍යුත් සෘණතාව අඩුම මූල ද්‍රව්‍යය $Li$ වේ.', '$Li, C, N, Na$ සහ $P$ මූලද්‍රව්‍ය අතුරෙන් විද්‍යුත් සෘණතාව අඩුම මූල ද්‍රව්‍යය $Li$ වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('452097c7-eba8-4acb-ad64-bd4139a08a6a', '1b01c6c6-cf41-5098-8154-a9eead534f5d', '($Li$ සහ $F$), ($Li^+$ සහ $F^-$), ($Li^+$ සහ $O^{2-}$) සහ ($O^{2-}$ සහ $F^-$) යුගල වල, අරයයන්හි වැඩිම වෙනස ඇත්තේ $Li^+$ සහ $O^{2-}$ අතරය.', '($Li$ සහ $F$), ($Li^+$ සහ $F^-$), ($Li^+$ සහ $O^{2-}$) සහ ($O^{2-}$ සහ $F^-$) යුගල වල, අරයයන්හි වැඩිම වෙනස ඇත්තේ $Li^+$ සහ $O^{2-}$ අතරය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9accf43-4f8b-4706-9d87-7feff15ca569', '1b01c6c6-cf41-5098-8154-a9eead534f5d', '$CH_2Cl_2$ හි ද්‍රව කලාපයෙහි පවතින එකම අන්තර් අණුක බල වර්ගය වන්නේ ද්විධ්‍රැව - ද්විධ්‍රැව බල වේ.', '$CH_2Cl_2$ හි ද්‍රව කලාපයෙහි පවතින එකම අන්තර් අණුක බල වර්ගය වන්නේ ද්විධ්‍රැව - ද්විධ්‍රැව බල වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fe3a98d4-8cfa-5b94-8d9b-93e846675894', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 13, '<p>$CH_4(g) \rightarrow CH_3(g) + H(g)$<br><br>ඉහත ප්‍රතික්‍රියාවේ සම්මත එන්තැල්පි වෙනස වනුයේ,</p>', '<p>$CH_4(g) \rightarrow CH_3(g) + H(g)$<br><br>ඉහත ප්‍රතික්‍රියාවේ සම්මත එන්තැල්පි වෙනස වනුයේ,</p>', NULL, 'ලබා දී ඇති සමීකරණය මගින් මීතේන් ($CH_4$) අණුවෙන් එක් හයිඩ්‍රජන් පරමාණුවක් ඉවත් වීම පෙන්වයි. මෙය පළමු $C-H$ බන්ධනයේ විඝටනය වේ. සම්මත බන්ධන විඝටන එන්තැල්පිය යනු සියලුම $C-H$ බන්ධන 4 ක විඝටන ශක්තීන්ගේ සාමාන්‍ය අගයයි. එබැවින් මෙය පළමු $C-H$ බන්ධනයෙහි විඝටනය සඳහා සම්මත එන්තැල්පි වෙනස වේ[cite: 1].', 'ලබා දී ඇති සමීකරණය මගින් මීතේන් ($CH_4$) අණුවෙන් එක් හයිඩ්‍රජන් පරමාණුවක් ඉවත් වීම පෙන්වයි. මෙය පළමු $C-H$ බන්ධනයේ විඝටනය වේ. සම්මත බන්ධන විඝටන එන්තැල්පිය යනු සියලුම $C-H$ බන්ධන 4 ක විඝටන ශක්තීන්ගේ සාමාන්‍ය අගයයි. එබැවින් මෙය පළමු $C-H$ බන්ධනයෙහි විඝටනය සඳහා සම්මත එන්තැල්පි වෙනස වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('57497ac9-2184-452c-932a-1ce067292437', 'fe3a98d4-8cfa-5b94-8d9b-93e846675894', 'මීතේන්හි පළමු $C-H$ බන්ධනයෙහි විඝටනය සඳහා සම්මත එන්තැල්පි වෙනසයි.', 'මීතේන්හි පළමු $C-H$ බන්ධනයෙහි විඝටනය සඳහා සම්මත එන්තැල්පි වෙනසයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('acd3bc98-7c99-46d1-af6f-0bb13abcf529', 'fe3a98d4-8cfa-5b94-8d9b-93e846675894', 'මීතේන්හි සම්මත පරමාණුකරණ එන්තැල්පි වෙනසයි.', 'මීතේන්හි සම්මත පරමාණුකරණ එන්තැල්පි වෙනසයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('02bc7c86-41fc-4b2c-b341-afd5cae055ef', 'fe3a98d4-8cfa-5b94-8d9b-93e846675894', 'මීතේන්හි සම්මත පළමු අයනීකරණ එන්තැල්පි වෙනසයි.', 'මීතේන්හි සම්මත පළමු අයනීකරණ එන්තැල්පි වෙනසයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b6badaf4-f491-4f05-97c3-dfe8026c5edf', 'fe3a98d4-8cfa-5b94-8d9b-93e846675894', 'මීතේන්හි සම්මත බන්ධන විඝටන එන්තැල්පි වෙනසයි.', 'මීතේන්හි සම්මත බන්ධන විඝටන එන්තැල්පි වෙනසයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e870c364-09ad-499c-ade5-1a958226f2b3', 'fe3a98d4-8cfa-5b94-8d9b-93e846675894', 'මීතේන්හි මුක්ත ඛණ්ඩක සෑදීමේ සම්මත එන්තැල්පි වෙනසයි.', 'මීතේන්හි මුක්ත ඛණ්ඩක සෑදීමේ සම්මත එන්තැල්පි වෙනසයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7a0b5def-0c0a-55c8-98a4-3ace1b71a50f', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 14, '<p>$2A(g) \rightarrow B(g)$ යන මූලික ප්‍රතික්‍රියාව සංවෘත දෘඪ බඳුනක් තුළ නියත උෂ්ණත්වයක දී සිදු වේ. බඳුනේ ආරම්භක පීඩනය $P_o$ සහ ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව ආරම්භක අගයෙන් $50\%$ වන විට පීඩනය $P_t$ වේ. පහත සඳහන් කුමක් මගින් $\frac{P_t}{P_o}$ සඳහා නිවැරදි අගය ලැබේද?</p>', '<p>$2A(g) \rightarrow B(g)$ යන මූලික ප්‍රතික්‍රියාව සංවෘත දෘඪ බඳුනක් තුළ නියත උෂ්ණත්වයක දී සිදු වේ. බඳුනේ ආරම්භක පීඩනය $P_o$ සහ ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව ආරම්භක අගයෙන් $50\%$ වන විට පීඩනය $P_t$ වේ. පහත සඳහන් කුමක් මගින් $\frac{P_t}{P_o}$ සඳහා නිවැරදි අගය ලැබේද?</p>', NULL, 'ප්‍රතික්‍රියාව මූලික බැවින්, ශීඝ්‍රතාව $R = k[A]^2$ වේ.<br>ආරම්භයේදී $R_o = k[A_o]^2$. ශීඝ්‍රතාව $50\%$ වනවිට $R_t = 0.5 R_o = k[A_t]^2$.<br>එබැවින් $[A_t]^2 = 0.5 [A_o]^2 \implies P_{A,t} = \frac{P_o}{\sqrt{2}}$.<br>ප්‍රතික්‍රියාවට අනුව 2 මවුල $A$ 1 මවුල $B$ බවට පත්වේ. $A$ හි පීඩන අඩුවීම $P_o - \frac{P_o}{\sqrt{2}}$.<br>සෑදෙන $B$ හි පීඩනය $P_B = \frac{1}{2} (P_o - \frac{P_o}{\sqrt{2}})$.<br>මුළු පීඩනය $P_t = P_{A,t} + P_B = \frac{P_o}{\sqrt{2}} + \frac{1}{2} P_o (1 - \frac{1}{\sqrt{2}}) = P_o (\frac{1}{2} + \frac{1}{2\sqrt{2}}) = P_o (\frac{\sqrt{2}+1}{2\sqrt{2}})$.<br>එබැවින් $\frac{P_t}{P_o} = \frac{1+\sqrt{2}}{2\sqrt{2}}$ වේ[cite: 1].', 'ප්‍රතික්‍රියාව මූලික බැවින්, ශීඝ්‍රතාව $R = k[A]^2$ වේ.<br>ආරම්භයේදී $R_o = k[A_o]^2$. ශීඝ්‍රතාව $50\%$ වනවිට $R_t = 0.5 R_o = k[A_t]^2$.<br>එබැවින් $[A_t]^2 = 0.5 [A_o]^2 \implies P_{A,t} = \frac{P_o}{\sqrt{2}}$.<br>ප්‍රතික්‍රියාවට අනුව 2 මවුල $A$ 1 මවුල $B$ බවට පත්වේ. $A$ හි පීඩන අඩුවීම $P_o - \frac{P_o}{\sqrt{2}}$.<br>සෑදෙන $B$ හි පීඩනය $P_B = \frac{1}{2} (P_o - \frac{P_o}{\sqrt{2}})$.<br>මුළු පීඩනය $P_t = P_{A,t} + P_B = \frac{P_o}{\sqrt{2}} + \frac{1}{2} P_o (1 - \frac{1}{\sqrt{2}}) = P_o (\frac{1}{2} + \frac{1}{2\sqrt{2}}) = P_o (\frac{\sqrt{2}+1}{2\sqrt{2}})$.<br>එබැවින් $\frac{P_t}{P_o} = \frac{1+\sqrt{2}}{2\sqrt{2}}$ වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03daaebd-83fa-4d44-9f02-fd39bebb8312', '7a0b5def-0c0a-55c8-98a4-3ace1b71a50f', '$\frac{P_t}{P_o} = \frac{1}{2}$', '$\frac{P_t}{P_o} = \frac{1}{2}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bb7c70d3-285d-4d07-a936-aa7f031ec17d', '7a0b5def-0c0a-55c8-98a4-3ace1b71a50f', '$\frac{P_t}{P_o} = \frac{1}{\sqrt{2}}$', '$\frac{P_t}{P_o} = \frac{1}{\sqrt{2}}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('768a4584-80b4-4a8c-bb11-d702fad81cef', '7a0b5def-0c0a-55c8-98a4-3ace1b71a50f', '$\frac{P_t}{P_o} = \frac{1+\sqrt{2}}{2\sqrt{2}}$', '$\frac{P_t}{P_o} = \frac{1+\sqrt{2}}{2\sqrt{2}}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b0f1886d-e116-4ad3-a2e6-e620999e2175', '7a0b5def-0c0a-55c8-98a4-3ace1b71a50f', '$\frac{P_t}{P_o} = \frac{\sqrt{2}}{1+\sqrt{2}}$', '$\frac{P_t}{P_o} = \frac{\sqrt{2}}{1+\sqrt{2}}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2618653f-9d64-4271-9530-4f14a1b81d1b', '7a0b5def-0c0a-55c8-98a4-3ace1b71a50f', '$\frac{P_t}{P_o} = \frac{\sqrt{2}-1}{1+\sqrt{2}}$', '$\frac{P_t}{P_o} = \frac{\sqrt{2}-1}{1+\sqrt{2}}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('afbd54dc-497f-5092-8b70-80cbeff285f2', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 15, '<p>$pK_a$ අගයයන් පිළිවෙළින් 4.7 හා 5.0 වන $HA$ හා $HB$ දුබල අම්ලවල සම්මවුලික ජලීය ද්‍රාවණයක් (එක් එක් අම්ලයෙන් $1.0~mol~dm^{-3}$ වන) සමතුලිතතාවයේ ඇත. $\log(\frac{[A^-]}{[B^-]})$ හි අගය ආසන්න වශයෙන් සමාන වනුයේ,</p>', '<p>$pK_a$ අගයයන් පිළිවෙළින් 4.7 හා 5.0 වන $HA$ හා $HB$ දුබල අම්ලවල සම්මවුලික ජලීය ද්‍රාවණයක් (එක් එක් අම්ලයෙන් $1.0~mol~dm^{-3}$ වන) සමතුලිතතාවයේ ඇත. $\log(\frac{[A^-]}{[B^-]})$ හි අගය ආසන්න වශයෙන් සමාන වනුයේ,</p>', NULL, '$K_{a,HA} = \frac{[H^+][A^-]}{[HA]}$ සහ $K_{a,HB} = \frac{[H^+][B^-]}{[HB]}$.<br>ද්‍රාවණය සම්මවුලික බැවින් දළ වශයෙන් $[HA] \approx [HB]$ ලෙස ගත හැක.<br>එබැවින් $\frac{K_{a,HA}}{K_{a,HB}} = \frac{[A^-]}{[B^-]}$.<br>$\log(\frac{[A^-]}{[B^-]}) = \log(K_{a,HA}) - \log(K_{a,HB}) = pK_{a,HB} - pK_{a,HA}$.<br>$= 5.0 - 4.7 = 0.3$[cite: 1].', '$K_{a,HA} = \frac{[H^+][A^-]}{[HA]}$ සහ $K_{a,HB} = \frac{[H^+][B^-]}{[HB]}$.<br>ද්‍රාවණය සම්මවුලික බැවින් දළ වශයෙන් $[HA] \approx [HB]$ ලෙස ගත හැක.<br>එබැවින් $\frac{K_{a,HA}}{K_{a,HB}} = \frac{[A^-]}{[B^-]}$.<br>$\log(\frac{[A^-]}{[B^-]}) = \log(K_{a,HA}) - \log(K_{a,HB}) = pK_{a,HB} - pK_{a,HA}$.<br>$= 5.0 - 4.7 = 0.3$[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
