INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('952c673a-b6fb-50c7-b8c2-7233c0f71900', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 16, '<p>පහත සඳහන් කුමන වගන්තිය $C_6H_5OH$ පිළිබඳව අසත්‍ය වේද?</p>', '<p>පහත සඳහන් කුමන වගන්තිය $C_6H_5OH$ පිළිබඳව අසත්‍ය වේද?</p>', NULL, 'ෆීනෝල් ($C_6H_5OH$) දුර්වල අම්ලයක් වන නමුත්, එය කාබොක්සිලික් අම්ල තරම් ප්‍රබල නොවේ. එබැවින් ෆීනෝල් $NaHCO_3$ වැනි දුර්වල භෂ්ම සමග ප්‍රතික්‍රියා කර $CO_2$ වායුව පිට නොකරයි. $CO_2$ නිදහස් කිරීම කාබොක්සිලික් අම්ල සඳහා වන ලක්ෂණාත්මක පරීක්ෂාවකි[cite: 1].', 'ෆීනෝල් ($C_6H_5OH$) දුර්වල අම්ලයක් වන නමුත්, එය කාබොක්සිලික් අම්ල තරම් ප්‍රබල නොවේ. එබැවින් ෆීනෝල් $NaHCO_3$ වැනි දුර්වල භෂ්ම සමග ප්‍රතික්‍රියා කර $CO_2$ වායුව පිට නොකරයි. $CO_2$ නිදහස් කිරීම කාබොක්සිලික් අම්ල සඳහා වන ලක්ෂණාත්මක පරීක්ෂාවකි[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4bdf1597-0183-4961-bd83-770cffe159f3', '952c673a-b6fb-50c7-b8c2-7233c0f71900', '$CH_3COCl$ සමග ප්‍රතික්‍රියා කර ෆීනයිල් එස්ටරයක් සාදයි.', '$CH_3COCl$ සමග ප්‍රතික්‍රියා කර ෆීනයිල් එස්ටරයක් සාදයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dc3a83f2-1626-46cc-8438-4874ce7fff76', '952c673a-b6fb-50c7-b8c2-7233c0f71900', 'බ්‍රෝමින් දියර සමග ප්‍රතික්‍රියා කර සුදු පැහැති අවක්ෂේපයක් ලබා දේ.', 'බ්‍රෝමින් දියර සමග ප්‍රතික්‍රියා කර සුදු පැහැති අවක්ෂේපයක් ලබා දේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b56f9302-04a8-4714-8fdf-e9f47f3cbf28', '952c673a-b6fb-50c7-b8c2-7233c0f71900', '$NaHCO_3$ සමග පිරියම් කළ විට $CO_2$ වායුව පිට කරයි.', '$NaHCO_3$ සමග පිරියම් කළ විට $CO_2$ වායුව පිට කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f43b1e0-45c2-418c-8da1-357d1da736ed', '952c673a-b6fb-50c7-b8c2-7233c0f71900', '$NaOH$ හමුවේ $C_6H_5N_2^+Cl^-$ සමග පිරියම් කළ විට වර්ණවත් සංයෝගයක් ලබා දේ.', '$NaOH$ හමුවේ $C_6H_5N_2^+Cl^-$ සමග පිරියම් කළ විට වර්ණවත් සංයෝගයක් ලබා දේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e2e2738d-b218-48cf-a50c-ff7814093084', '952c673a-b6fb-50c7-b8c2-7233c0f71900', 'උදාසීන $FeCl_3$ සමග පිරියම් කළ විට වර්ණවත් (දම් පැහැයට හුරු) ද්‍රාවණයක් ලබා දේ.', 'උදාසීන $FeCl_3$ සමග පිරියම් කළ විට වර්ණවත් (දම් පැහැයට හුරු) ද්‍රාවණයක් ලබා දේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3c358ba1-aa13-5221-9a56-4c396841c056', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 17, '<p>ප්‍රතික්‍රියාවක අර්ධ ආයු කාලය,</p>', '<p>ප්‍රතික්‍රියාවක අර්ධ ආයු කාලය,</p>', NULL, 'ඕනෑම පෙළක ප්‍රතික්‍රියාවක් සඳහා අර්ධ ආයු කාලය ($t_{1/2}$) ප්‍රතික්‍රියාවේ ශීඝ්‍රතා නියතය ($k$) මත රඳා පවතී (උදා: පළමු පෙළ සඳහා $t_{1/2} = \frac{\ln 2}{k}$, ශුන්‍ය පෙළ සඳහා $t_{1/2} = \frac{[A_0]}{2k}$). එය ආරම්භක සාන්ද්‍රණයෙන් ස්වායත්ත වන්නේ පළමු පෙළ ප්‍රතික්‍රියා සඳහා පමණි. උෂ්ණත්වය වෙනස් වන විට $k$ වෙනස් වන බැවින් උෂ්ණත්වයෙන් ද ස්වායත්ත නොවේ[cite: 1].', 'ඕනෑම පෙළක ප්‍රතික්‍රියාවක් සඳහා අර්ධ ආයු කාලය ($t_{1/2}$) ප්‍රතික්‍රියාවේ ශීඝ්‍රතා නියතය ($k$) මත රඳා පවතී (උදා: පළමු පෙළ සඳහා $t_{1/2} = \frac{\ln 2}{k}$, ශුන්‍ය පෙළ සඳහා $t_{1/2} = \frac{[A_0]}{2k}$). එය ආරම්භක සාන්ද්‍රණයෙන් ස්වායත්ත වන්නේ පළමු පෙළ ප්‍රතික්‍රියා සඳහා පමණි. උෂ්ණත්වය වෙනස් වන විට $k$ වෙනස් වන බැවින් උෂ්ණත්වයෙන් ද ස්වායත්ත නොවේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42024719-2bc0-42fe-b950-2579d7950a6b', '3c358ba1-aa13-5221-9a56-4c396841c056', 'සැමවිටම ප්‍රතික්‍රියක වල ආරම්භක සාන්ද්‍රණයෙන් ස්වායත්ත වේ.', 'සැමවිටම ප්‍රතික්‍රියක වල ආරම්භක සාන්ද්‍රණයෙන් ස්වායත්ත වේ.', NULL, 'sanitized', 'v1', 0, 1);
