INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cde1e06a-ca88-4d61-8442-7883f11a80f2', '3c358ba1-aa13-5221-9a56-4c396841c056', 'සැමවිටම ප්‍රතික්‍රියාවෙහි පෙළින් ස්වායත්ත වේ.', 'සැමවිටම ප්‍රතික්‍රියාවෙහි පෙළින් ස්වායත්ත වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8379ae16-11da-4948-a2af-490e3d3e5dd5', '3c358ba1-aa13-5221-9a56-4c396841c056', 'සැමවිටම උෂ්ණත්වයෙන් ස්වායත්ත වේ.', 'සැමවිටම උෂ්ණත්වයෙන් ස්වායත්ත වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8725b497-3cf6-4e47-bc9d-8b952271362d', '3c358ba1-aa13-5221-9a56-4c396841c056', 'මුළු ප්‍රතික්‍රියා කාලය මෙන් දෙගුණයකට සමාන වේ.', 'මුළු ප්‍රතික්‍රියා කාලය මෙන් දෙගුණයකට සමාන වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9236ffec-06eb-596f-8dd1-5346ef3243dc', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 18, '<p>විද්‍යුත් රසායනික කෝෂයක විද්‍යුත්ගාමක බලය රඳා නොපවතින්නේ,</p>', '<p>විද්‍යුත් රසායනික කෝෂයක විද්‍යුත්ගාමක බලය රඳා නොපවතින්නේ,</p>', NULL, 'කෝෂයක විද්‍යුත්ගාමක බලය (EMF) නර්න්ස්ට් (Nernst) සමීකරණය මගින් විස්තර කෙරෙන අතර, එය උෂ්ණත්වය, සාන්ද්‍රණය, හා ඉලෙක්ට්‍රෝඩ / විද්‍යුත් විච්ඡේද්‍ය වල ස්වභාවය මත රඳා පවතී. නමුත් ඉලෙක්ට්‍රෝඩ වල පෘෂ්ඨික ක්ෂේත්‍රඵලය මගින් කෝෂයේ විභව වෙනස (EMF) වෙනස් නොකරයි, එය බලපාන්නේ ධාරාව ලබාදීමේ හැකියාවට (current capacity) පමණි[cite: 1].', 'කෝෂයක විද්‍යුත්ගාමක බලය (EMF) නර්න්ස්ට් (Nernst) සමීකරණය මගින් විස්තර කෙරෙන අතර, එය උෂ්ණත්වය, සාන්ද්‍රණය, හා ඉලෙක්ට්‍රෝඩ / විද්‍යුත් විච්ඡේද්‍ය වල ස්වභාවය මත රඳා පවතී. නමුත් ඉලෙක්ට්‍රෝඩ වල පෘෂ්ඨික ක්ෂේත්‍රඵලය මගින් කෝෂයේ විභව වෙනස (EMF) වෙනස් නොකරයි, එය බලපාන්නේ ධාරාව ලබාදීමේ හැකියාවට (current capacity) පමණි[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
