INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5fc969d2-4461-4775-ad4f-f7c95f911c4e', '9236ffec-06eb-596f-8dd1-5346ef3243dc', 'විද්‍යුත් විච්ඡේද්‍ය වල සාන්ද්‍රණ මතය.', 'විද්‍යුත් විච්ඡේද්‍ය වල සාන්ද්‍රණ මතය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ed1e15b-8a1f-4141-a567-b8ce551a51fb', '9236ffec-06eb-596f-8dd1-5346ef3243dc', 'ඉලෙක්ට්‍රෝඩ වල පෘෂ්ඨික ක්ෂේත්‍ර ඵල මතය.', 'ඉලෙක්ට්‍රෝඩ වල පෘෂ්ඨික ක්ෂේත්‍ර ඵල මතය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9de0bee-345a-4e10-93af-06f8d71d2f01', '9236ffec-06eb-596f-8dd1-5346ef3243dc', 'ඉලෙක්ට්‍රෝඩ සාදන ලෝහ වර්ග මතය.', 'ඉලෙක්ට්‍රෝඩ සාදන ලෝහ වර්ග මතය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9226c32f-8014-52b6-aa78-3d0ce0f63a28', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 19, '<p>ආම්ලික මාධ්‍යයේ දී $IO_3^-$ (අයඩේට් අයනය), $SO_3^{2-}$ අයනය $SO_4^{2-}$ බවට ඔක්සිකරණය කරයි. $Na_2SO_3$ ($0.50~mol~dm^{-3}$) ද්‍රාවණයක $25.0~cm^3$ හි අඩංගු $Na_2SO_3$ ප්‍රමාණය සම්පුර්ණයෙන් $Na_2SO_4$ බවට ඔක්සිකරණය කිරීමට අවශ්‍ය වන $KIO_3$ ස්කන්ධය $1.07~g$ වේ. ($O=16, K=39, I=127$)<br><br>ප්‍රතික්‍රියාව සම්පුර්ණ වූ පසු අයඩීන්හි අවසාන ඔක්සිකරණ අවස්ථාව වනුයේ,</p>', '<p>ආම්ලික මාධ්‍යයේ දී $IO_3^-$ (අයඩේට් අයනය), $SO_3^{2-}$ අයනය $SO_4^{2-}$ බවට ඔක්සිකරණය කරයි. $Na_2SO_3$ ($0.50~mol~dm^{-3}$) ද්‍රාවණයක $25.0~cm^3$ හි අඩංගු $Na_2SO_3$ ප්‍රමාණය සම්පුර්ණයෙන් $Na_2SO_4$ බවට ඔක්සිකරණය කිරීමට අවශ්‍ය වන $KIO_3$ ස්කන්ධය $1.07~g$ වේ. ($O=16, K=39, I=127$)<br><br>ප්‍රතික්‍රියාව සම්පුර්ණ වූ පසු අයඩීන්හි අවසාන ඔක්සිකරණ අවස්ථාව වනුයේ,</p>', NULL, '$Na_2SO_3$ මවුල ගණන = $0.50 \times 25.0 \times 10^{-3} = 0.0125~mol$.<br>$SO_3^{2-} \rightarrow SO_4^{2-}$ හිදී $S$ හි ඔක්සිකරණ අංකය $+4 \rightarrow +6$ වේ. එබැවින් හුවමාරු වන ඉලෙක්ට්‍රෝන මවුල ගණන = $0.0125 \times 2 = 0.025~mol$.<br>$KIO_3$ මවුලික ස්කන්ධය = $39 + 127 + 48 = 214~g~mol^{-1}$.<br>භාවිතා කළ $KIO_3$ මවුල ගණන = $\frac{1.07}{214} = 0.005~mol$.<br>$IO_3^-$ මවුල 1 කින් ලබාගන්නා ඉලෙක්ට්‍රෝන ගණන = $\frac{0.025}{0.005} = 5$.<br>$IO_3^-$ හි අයඩීන් වල ඔක්සිකරණ අංකය $+5$ වේ. එය ඉලෙක්ට්‍රෝන 5 ක් ලබා ගත් විට අවසාන ඔක්සිකරණ අංකය $+5 - 5 = 0$ වේ (එනම් $I_2$ බවට පත්වේ)[cite: 1].', '$Na_2SO_3$ මවුල ගණන = $0.50 \times 25.0 \times 10^{-3} = 0.0125~mol$.<br>$SO_3^{2-} \rightarrow SO_4^{2-}$ හිදී $S$ හි ඔක්සිකරණ අංකය $+4 \rightarrow +6$ වේ. එබැවින් හුවමාරු වන ඉලෙක්ට්‍රෝන මවුල ගණන = $0.0125 \times 2 = 0.025~mol$.<br>$KIO_3$ මවුලික ස්කන්ධය = $39 + 127 + 48 = 214~g~mol^{-1}$.<br>භාවිතා කළ $KIO_3$ මවුල ගණන = $\frac{1.07}{214} = 0.005~mol$.<br>$IO_3^-$ මවුල 1 කින් ලබාගන්නා ඉලෙක්ට්‍රෝන ගණන = $\frac{0.025}{0.005} = 5$.<br>$IO_3^-$ හි අයඩීන් වල ඔක්සිකරණ අංකය $+5$ වේ. එය ඉලෙක්ට්‍රෝන 5 ක් ලබා ගත් විට අවසාන ඔක්සිකරණ අංකය $+5 - 5 = 0$ වේ (එනම් $I_2$ බවට පත්වේ)[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
