INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d79807ff-37f1-57db-a4d3-39d2fd08c316', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 20, '<p>ආවර්තිතා වගුවේ s - ගොනුවේ මූල ද්‍රව්‍ය පිළිබඳව පහත කුමන වගන්තිය අසත්‍ය වන්නේද?</p>', '<p>ආවර්තිතා වගුවේ s - ගොනුවේ මූල ද්‍රව්‍ය පිළිබඳව පහත කුමන වගන්තිය අසත්‍ය වන්නේද?</p>', NULL, 'I කාණ්ඩයේ (ක්ෂාර ලෝහ) මූලද්‍රව්‍ය අතරින් වායුගෝලීය නයිට්‍රජන් ($N_2$) සමඟ ඍජුවම ප්‍රතික්‍රියා කර නයිට්‍රයිඩ (උදා: $Li_3N$) සාදන්නේ ලිතියම් (Li) පමණි. අනෙකුත් ක්ෂාර ලෝහ $N_2$ සමඟ ඍජුවම ප්‍රතික්‍රියා නොකරයි. එබැවින් 2 වැනි ප්‍රකාශය අසත්‍ය වේ[cite: 1].', 'I කාණ්ඩයේ (ක්ෂාර ලෝහ) මූලද්‍රව්‍ය අතරින් වායුගෝලීය නයිට්‍රජන් ($N_2$) සමඟ ඍජුවම ප්‍රතික්‍රියා කර නයිට්‍රයිඩ (උදා: $Li_3N$) සාදන්නේ ලිතියම් (Li) පමණි. අනෙකුත් ක්ෂාර ලෝහ $N_2$ සමඟ ඍජුවම ප්‍රතික්‍රියා නොකරයි. එබැවින් 2 වැනි ප්‍රකාශය අසත්‍ය වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('08a49d9e-5acb-41c6-8330-23c175fd9ba5', 'd79807ff-37f1-57db-a4d3-39d2fd08c316', 'I කාණ්ඩයේ සියලුම මූල ද්‍රව්‍ය ජලය සමග ප්‍රතික්‍රියා කර $H_2$ වායුව නිදහස් කරයි.', 'I කාණ්ඩයේ සියලුම මූල ද්‍රව්‍ය ජලය සමග ප්‍රතික්‍රියා කර $H_2$ වායුව නිදහස් කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29c082d3-e2d5-476d-a537-bc0100db792c', 'd79807ff-37f1-57db-a4d3-39d2fd08c316', 'Li හැර I කාණ්ඩයේ අනිකුත් සියලු ම මූල ද්‍රව්‍ය $N_2$ වායුව සමග ප්‍රතික්‍රියා කරයි.', 'Li හැර I කාණ්ඩයේ අනිකුත් සියලු ම මූල ද්‍රව්‍ය $N_2$ වායුව සමග ප්‍රතික්‍රියා කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42ff5e1b-f965-4f32-8ddb-f34d4600fd35', 'd79807ff-37f1-57db-a4d3-39d2fd08c316', 'II කාණ්ඩයේ සියලුම මූල ද්‍රව්‍ය $N_2$ වායුව සමග ප්‍රතික්‍රියා කරයි.', 'II කාණ්ඩයේ සියලුම මූල ද්‍රව්‍ය $N_2$ වායුව සමග ප්‍රතික්‍රියා කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('23b997d7-65d4-4a01-bf53-9e65da08ea1d', 'd79807ff-37f1-57db-a4d3-39d2fd08c316', 'වැඩිපුර $O_2$ සමග Na ප්‍රතික්‍රියා කර $Na_2O_2$ ලබා දෙන අතර K, $KO_2$ ලබා දෙයි.', 'වැඩිපුර $O_2$ සමග Na ප්‍රතික්‍රියා කර $Na_2O_2$ ලබා දෙන අතර K, $KO_2$ ලබා දෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0e256194-d984-493a-8978-4ac37de678ab', 'd79807ff-37f1-57db-a4d3-39d2fd08c316', 's-ගොනුවේ සියලු ම මුල ද්‍රව්‍ය හොඳ ඔක්සිහාරක වේ.', 's-ගොනුවේ සියලු ම මුල ද්‍රව්‍ය හොඳ ඔක්සිහාරක වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8634c7ba-ff45-5dc5-91ea-64ff913129d1', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 21, '<p>පරිපූර්ණ වායුවක් අඩංගු දෘඪ බඳුන් දෙකකින් සමන්විත පද්ධතියක් රූපසටහනෙහි දක්වා ඇත. කපාටය විවෘත කිරීමෙන් බඳුන් එකිනෙක හා සම්බන්ධ කළ හැකි වේ. කපාටය විවෘත කළ විට පද්ධතිය A සැකසුමේ සිට B සැකසුම දක්වා වෙනස් වේ. සාමාන්‍යයෙන් n, P, V සහ T මගින් පිළිවෙළින් මවුල සංඛ්‍යාව, පීඩනය, පරිමාව හා උෂ්ණත්වය නිරූපණය කෙරේ.<br><br>[Diagram]<br><br>මෙම පද්ධතිය පිළිබඳ ව පහත දැක්වෙන කුමන සම්බන්ධය නිවැරදි වේද?</p>', '<p>පරිපූර්ණ වායුවක් අඩංගු දෘඪ බඳුන් දෙකකින් සමන්විත පද්ධතියක් රූපසටහනෙහි දක්වා ඇත. කපාටය විවෘත කිරීමෙන් බඳුන් එකිනෙක හා සම්බන්ධ කළ හැකි වේ. කපාටය විවෘත කළ විට පද්ධතිය A සැකසුමේ සිට B සැකසුම දක්වා වෙනස් වේ. සාමාන්‍යයෙන් n, P, V සහ T මගින් පිළිවෙළින් මවුල සංඛ්‍යාව, පීඩනය, පරිමාව හා උෂ්ණත්වය නිරූපණය කෙරේ.<br><br>[Diagram]<br><br>මෙම පද්ධතිය පිළිබඳ ව පහත දැක්වෙන කුමන සම්බන්ධය නිවැරදි වේද?</p>', NULL, 'ආරම්භක අවස්ථාවේදී (A සැකසුම) බඳුන් දෙකෙහිම මවුල $n$ බැගින් පවතින බව රූපයෙන් පෙනේ (එනම් $n_1 = n_2 = n$).<br>පරිපූර්ණ වායු සමීකරණයට අනුව, $V_1 = \frac{nRT_1}{P_1}$ සහ $V_2 = \frac{nRT_2}{P_2}$ වේ.<br>කපාටය විවෘත කළ පසු (B සැකසුම), මුළු මවුල ගණන $= 2n$ වේ.<br>මුළු පරිමාව $V_1 + V_2$ වන අතර අවසන් පීඩනය $P_3$ ද උෂ්ණත්වය $T_3$ ද වේ.<br>එබැවින් $P_3(V_1 + V_2) = (2n)RT_3$ වේ.<br>$V_1$ හා $V_2$ ආදේශ කිරීමෙන්:<br>$P_3(\frac{nRT_1}{P_1} + \frac{nRT_2}{P_2}) = 2nRT_3$<br>$nR$ මගින් බෙදූ විට, $\frac{P_3T_1}{P_1} + \frac{P_3T_2}{P_2} = 2T_3$ ලැබේ[cite: 1].', 'ආරම්භක අවස්ථාවේදී (A සැකසුම) බඳුන් දෙකෙහිම මවුල $n$ බැගින් පවතින බව රූපයෙන් පෙනේ (එනම් $n_1 = n_2 = n$).<br>පරිපූර්ණ වායු සමීකරණයට අනුව, $V_1 = \frac{nRT_1}{P_1}$ සහ $V_2 = \frac{nRT_2}{P_2}$ වේ.<br>කපාටය විවෘත කළ පසු (B සැකසුම), මුළු මවුල ගණන $= 2n$ වේ.<br>මුළු පරිමාව $V_1 + V_2$ වන අතර අවසන් පීඩනය $P_3$ ද උෂ්ණත්වය $T_3$ ද වේ.<br>එබැවින් $P_3(V_1 + V_2) = (2n)RT_3$ වේ.<br>$V_1$ හා $V_2$ ආදේශ කිරීමෙන්:<br>$P_3(\frac{nRT_1}{P_1} + \frac{nRT_2}{P_2}) = 2nRT_3$<br>$nR$ මගින් බෙදූ විට, $\frac{P_3T_1}{P_1} + \frac{P_3T_2}{P_2} = 2T_3$ ලැබේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e7ada05f-ff71-4d86-a31d-cd3f0f698437', '8634c7ba-ff45-5dc5-91ea-64ff913129d1', '$P_1V_1=P_2V_2$', '$P_1V_1=P_2V_2$', NULL, 'sanitized', 'v1', 0, 1);
