INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cb7bd391-1612-487e-95e0-50506dcd7d69', '8634c7ba-ff45-5dc5-91ea-64ff913129d1', '$P_1V_1+P_2V_2=P_3(V_1+V_2)$', '$P_1V_1+P_2V_2=P_3(V_1+V_2)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6ac681cb-cf4d-5dc3-a36a-4cbe05f947f9', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 22, '<p>ආවර්තිතා වගුවේ 3d - මුල ද්‍රව්‍ය පිළිබඳව පහත කුමන වගන්තිය අසත්‍ය වන්නේ ද?</p>', '<p>ආවර්තිතා වගුවේ 3d - මුල ද්‍රව්‍ය පිළිබඳව පහත කුමන වගන්තිය අසත්‍ය වන්නේ ද?</p>', NULL, 'ආවර්තයක් ඔස්සේ වමේ සිට දකුණට යන විට න්‍යෂ්ටික ආරෝපණය වැඩි වීම නිසා ඉලෙක්ට්‍රෝන වඩාත් දැඩිව ආකර්ෂණය වේ. එබැවින් 3d ගොනුවේ (ආන්තරික ලෝහ) මූලද්‍රව්‍යවල පළමු අයනීකරණ ශක්තිය, ඊට වම් පසින් පිහිටන එම ආවර්තයේම s-ගොනුවේ මූලද්‍රව්‍යවල (උදා: K, Ca) පළමු අයනීකරණ ශක්තියට වඩා සාමාන්‍යයෙන් වැඩි වේ. එබැවින් 4 වන ප්‍රකාශය අසත්‍යයකි[cite: 1].', 'ආවර්තයක් ඔස්සේ වමේ සිට දකුණට යන විට න්‍යෂ්ටික ආරෝපණය වැඩි වීම නිසා ඉලෙක්ට්‍රෝන වඩාත් දැඩිව ආකර්ෂණය වේ. එබැවින් 3d ගොනුවේ (ආන්තරික ලෝහ) මූලද්‍රව්‍යවල පළමු අයනීකරණ ශක්තිය, ඊට වම් පසින් පිහිටන එම ආවර්තයේම s-ගොනුවේ මූලද්‍රව්‍යවල (උදා: K, Ca) පළමු අයනීකරණ ශක්තියට වඩා සාමාන්‍යයෙන් වැඩි වේ. එබැවින් 4 වන ප්‍රකාශය අසත්‍යයකි[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('68145da9-f07f-4104-9a28-77acd33adeea', '6ac681cb-cf4d-5dc3-a36a-4cbe05f947f9', 'පරමාණුක අරයයන්, එම ආවර්තයේ ඇති s - ගොනුවේ මූල ද්‍රව්‍යයන්හි පරමාණුක අරයයන්ට වඩා කුඩා වේ.', 'පරමාණුක අරයයන්, එම ආවර්තයේ ඇති s - ගොනුවේ මූල ද්‍රව්‍යයන්හි පරමාණුක අරයයන්ට වඩා කුඩා වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('813beb15-8ac1-4f4d-97c6-601745b413d3', '6ac681cb-cf4d-5dc3-a36a-4cbe05f947f9', 'ඝනත්වය, එම ආවර්තයේ ඇති s - ගොනුවේ මූල ද්‍රව්‍යයන්හි ඝනත්වයට වඩා වැඩි වේ.', 'ඝනත්වය, එම ආවර්තයේ ඇති s - ගොනුවේ මූල ද්‍රව්‍යයන්හි ඝනත්වයට වඩා වැඩි වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eb762dc8-ad2f-451c-b394-198a15806e97', '6ac681cb-cf4d-5dc3-a36a-4cbe05f947f9', '$V_2O_5$, $CrO_3$ හා $Mn_2O_7$ ආම්ලික ඔක්සයිඩ වේ.', '$V_2O_5$, $CrO_3$ හා $Mn_2O_7$ ආම්ලික ඔක්සයිඩ වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c15fa772-cda2-4ee1-8bf2-f16682c51e17', '6ac681cb-cf4d-5dc3-a36a-4cbe05f947f9', 'පළමු අයනීකරණ ශක්ති, එම ආවර්තයේ ඇති s-ගොනුවේ මූලද්‍රව්‍යයන්හි පළමු අයනීකරණ ශක්ති වලට වඩා අඩු වේ.', 'පළමු අයනීකරණ ශක්ති, එම ආවර්තයේ ඇති s-ගොනුවේ මූලද්‍රව්‍යයන්හි පළමු අයනීකරණ ශක්ති වලට වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bcad871b-0f2b-4d8c-9ce9-b085589dda33', '6ac681cb-cf4d-5dc3-a36a-4cbe05f947f9', 'කොබෝල්ට් සංයෝගවල කොබෝල්ට් හි වඩාත්ම සුලභ ඔක්සිකරණ අවස්ථා වනුයේ +2 හා +3 ය.', 'කොබෝල්ට් සංයෝගවල කොබෝල්ට් හි වඩාත්ම සුලභ ඔක්සිකරණ අවස්ථා වනුයේ +2 හා +3 ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1281874a-79bd-56de-afd1-9ee865c8d996', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 23, '<p>එකිනෙකට වෙනස් උෂ්ණත්ව දෙකක දී $MO(s) \rightarrow M(s) + \frac{1}{2}O_2(g)$ ප්‍රතික්‍රියාව සඳහා සම්මත ගිබ්ස් ශක්ති වෙනස පහත දී ඇත.<br><br>T = 1000 K හිදී $\Delta G^\circ = -100.2~kJ~mol^{-1}$<br>T = 2000 K හිදී $\Delta G^\circ = -148.6~kJ~mol^{-1}$<br><br>ප්‍රතික්‍රියාවෙහි සම්මත එන්ට්‍රොපි වෙනස වනුයේ,</p>', '<p>එකිනෙකට වෙනස් උෂ්ණත්ව දෙකක දී $MO(s) \rightarrow M(s) + \frac{1}{2}O_2(g)$ ප්‍රතික්‍රියාව සඳහා සම්මත ගිබ්ස් ශක්ති වෙනස පහත දී ඇත.<br><br>T = 1000 K හිදී $\Delta G^\circ = -100.2~kJ~mol^{-1}$<br>T = 2000 K හිදී $\Delta G^\circ = -148.6~kJ~mol^{-1}$<br><br>ප්‍රතික්‍රියාවෙහි සම්මත එන්ට්‍රොපි වෙනස වනුයේ,</p>', NULL, 'ගිබ්ස් ශක්ති සමීකරණය: $\Delta G^\circ = \Delta H^\circ - T\Delta S^\circ$<br>1000 K හිදී: $-100.2 = \Delta H^\circ - 1000\Delta S^\circ$ --- (1)<br>2000 K හිදී: $-148.6 = \Delta H^\circ - 2000\Delta S^\circ$ --- (2)<br>(1) න් (2) අඩු කිරීමෙන්:<br>$-100.2 - (-148.6) = -1000\Delta S^\circ - (-2000\Delta S^\circ)$<br>$48.4 = 1000\Delta S^\circ$<br>$\Delta S^\circ = 0.0484~kJ~K^{-1}mol^{-1} = 48.4~J~K^{-1}mol^{-1}$ වේ[cite: 1].', 'ගිබ්ස් ශක්ති සමීකරණය: $\Delta G^\circ = \Delta H^\circ - T\Delta S^\circ$<br>1000 K හිදී: $-100.2 = \Delta H^\circ - 1000\Delta S^\circ$ --- (1)<br>2000 K හිදී: $-148.6 = \Delta H^\circ - 2000\Delta S^\circ$ --- (2)<br>(1) න් (2) අඩු කිරීමෙන්:<br>$-100.2 - (-148.6) = -1000\Delta S^\circ - (-2000\Delta S^\circ)$<br>$48.4 = 1000\Delta S^\circ$<br>$\Delta S^\circ = 0.0484~kJ~K^{-1}mol^{-1} = 48.4~J~K^{-1}mol^{-1}$ වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
