INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('120f0dd5-72bb-4afe-b98c-d157585497b3', '9601bd7d-c3fc-5fb1-b59f-ab9501d958ff', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8627334b-6b21-5cbc-a70c-07d8729246f6', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 41, '<p>පළමු ප්‍රකාශය: $MgCO_3$ වලට වඩා $BaCO_3$ තාපස්ථායි වේ.<br><br>දෙවන ප්‍රකාශය: දෙවන කාණ්ඩයේ කැටායනවල ධ්‍රැවීකරණ බලය කාණ්ඩයේ පහළට යන විට අඩු වේ.</p>', '<p>පළමු ප්‍රකාශය: $MgCO_3$ වලට වඩා $BaCO_3$ තාපස්ථායි වේ.<br><br>දෙවන ප්‍රකාශය: දෙවන කාණ්ඩයේ කැටායනවල ධ්‍රැවීකරණ බලය කාණ්ඩයේ පහළට යන විට අඩු වේ.</p>', NULL, 'දෙවන කාණ්ඩයේ පහළට යන විට කැටායනයේ අරය වැඩි වීම නිසා එහි ධ්‍රැවීකරණ බලය (polarizing power) අඩු වේ. මේ හේතුවෙන් කාබනේට අයනයේ ඉලෙක්ට්‍රෝන වලාකුළ විකෘති වීම අඩුවන බැවින් කාබනේටවල තාප ස්ථායීතාවය වැඩි වේ. එබැවින් ප්‍රකාශ දෙකම සත්‍ය වන අතර දෙවන ප්‍රකාශයෙන් පළමු ප්‍රකාශය මනාව පැහැදිලි කරයි[cite: 1].', 'දෙවන කාණ්ඩයේ පහළට යන විට කැටායනයේ අරය වැඩි වීම නිසා එහි ධ්‍රැවීකරණ බලය (polarizing power) අඩු වේ. මේ හේතුවෙන් කාබනේට අයනයේ ඉලෙක්ට්‍රෝන වලාකුළ විකෘති වීම අඩුවන බැවින් කාබනේටවල තාප ස්ථායීතාවය වැඩි වේ. එබැවින් ප්‍රකාශ දෙකම සත්‍ය වන අතර දෙවන ප්‍රකාශයෙන් පළමු ප්‍රකාශය මනාව පැහැදිලි කරයි[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('61f2263c-6a8a-4875-a124-870b72da7a92', '8627334b-6b21-5cbc-a70c-07d8729246f6', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
