INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('405626aa-bda0-5002-a216-f6dc7dd227a7', '79d87f2d-dc1e-59d2-9f04-9081fbb3bdba', 50, '<p>පළමු ප්‍රකාශය: සූර්යාලෝකය ඇති විට හරිත ශාක තුළ $CO_2$ තිර වේ.<br><br>දෙවන ප්‍රකාශය: වායුගෝලයේ $CO_2$ මට්ටම ඉහළ යාම හරිත ශාක මගින් පාලනය කළ නොහැක.</p>', '<p>පළමු ප්‍රකාශය: සූර්යාලෝකය ඇති විට හරිත ශාක තුළ $CO_2$ තිර වේ.<br><br>දෙවන ප්‍රකාශය: වායුගෝලයේ $CO_2$ මට්ටම ඉහළ යාම හරිත ශාක මගින් පාලනය කළ නොහැක.</p>', NULL, 'ප්‍රභාසංශ්ලේෂණය මගින් හරිත ශාක සූර්යාලෝකය ඇති විට $CO_2$ අවශෝෂණය කර කාබනික ද්‍රව්‍ය (කාබෝහයිඩ්‍රේට) බවට පත් කරයි (පළමු ප්‍රකාශය සත්‍ය වේ). හරිත ශාක මගින් වායුගෝලයේ ඇති $CO_2$ ප්‍රමාණය සැලකිය යුතු ලෙස පාලනය කෙරේ (කාබන් සින්ක් ලෙස ක්‍රියා කරයි). එබැවින් දෙවන ප්‍රකාශය අසත්‍ය වේ[cite: 1].', 'ප්‍රභාසංශ්ලේෂණය මගින් හරිත ශාක සූර්යාලෝකය ඇති විට $CO_2$ අවශෝෂණය කර කාබනික ද්‍රව්‍ය (කාබෝහයිඩ්‍රේට) බවට පත් කරයි (පළමු ප්‍රකාශය සත්‍ය වේ). හරිත ශාක මගින් වායුගෝලයේ ඇති $CO_2$ ප්‍රමාණය සැලකිය යුතු ලෙස පාලනය කෙරේ (කාබන් සින්ක් ලෙස ක්‍රියා කරයි). එබැවින් දෙවන ප්‍රකාශය අසත්‍ය වේ[cite: 1].', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d28f1540-1a21-47dc-99b2-f682025b5ad8', '405626aa-bda0-5002-a216-f6dc7dd227a7', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('57bac9a1-dd3d-4a33-a903-a9a34369ae95', '405626aa-bda0-5002-a216-f6dc7dd227a7', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', NULL, 'sanitized', 'v1', 1, 0);
