INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bf86e877-ad46-4ab9-bd01-0e990caf5525', '405626aa-bda0-5002-a216-f6dc7dd227a7', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e11d1814-56ef-5b64-bfa3-b0806b43fb2a', '825892d9-e9ee-54d1-9466-7d8032b8511f', 1, '<p>ලිපිඩ පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ලිපිඩ පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ලිපිඩවල $H:O$ අනුපාතය කාබෝහයිඩ්‍රේටවල මෙන් $2:1$ නොවන අතර එය ඊට වඩා විශාල අගයක් ගනී. අනෙක් ප්‍රකාශ වැරදි වේ. (ලිපිඩ මහා අණු නොවේ, සන්තෘප්ත මේද ද්විත්ව බන්ධන නොදරයි, එස්ටර බන්ධන මගින් සම්බන්ධ වේ, පොස්පොලිපිඩවල ඇත්තේ එක් පොස්ෆේට් කාණ්ඩයක් පමණි).', 'ලිපිඩවල $H:O$ අනුපාතය කාබෝහයිඩ්‍රේටවල මෙන් $2:1$ නොවන අතර එය ඊට වඩා විශාල අගයක් ගනී. අනෙක් ප්‍රකාශ වැරදි වේ. (ලිපිඩ මහා අණු නොවේ, සන්තෘප්ත මේද ද්විත්ව බන්ධන නොදරයි, එස්ටර බන්ධන මගින් සම්බන්ධ වේ, පොස්පොලිපිඩවල ඇත්තේ එක් පොස්ෆේට් කාණ්ඩයක් පමණි).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3dd30462-ab79-4ec4-9933-039b165f783c', 'e11d1814-56ef-5b64-bfa3-b0806b43fb2a', 'ලිපිඩ යනු C, H සහ O වලින් සමන්විත මහා අණුය.', 'ලිපිඩ යනු C, H සහ O වලින් සමන්විත මහා අණුය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('60b037f8-7c14-40d5-a0ac-715161889a14', 'e11d1814-56ef-5b64-bfa3-b0806b43fb2a', 'සන්තෘප්ත මේදවල එක් එක් හයිඩ්‍රොකාබන් දාමය ද්විත්ව බන්ධනයක් බැගින් දරයි.', 'සන්තෘප්ත මේදවල එක් එක් හයිඩ්‍රොකාබන් දාමය ද්විත්ව බන්ධනයක් බැගින් දරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('12e8c415-f820-41bb-8963-7df731b5da7a', 'e11d1814-56ef-5b64-bfa3-b0806b43fb2a', 'මේද තැනීමේදී ග්ලිසරෝල් සහ මේද අම්ල හයිඩ්‍රජන් බන්ධන මගින් සම්බන්ධ වේ.', 'මේද තැනීමේදී ග්ලිසරෝල් සහ මේද අම්ල හයිඩ්‍රජන් බන්ධන මගින් සම්බන්ධ වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6d89b342-17c6-4d7a-809b-d774e5be3d37', 'e11d1814-56ef-5b64-bfa3-b0806b43fb2a', 'ලිපිඩවල H:O අනුපාතය 2:1 ට වඩා වැඩි ය.', 'ලිපිඩවල H:O අනුපාතය 2:1 ට වඩා වැඩි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('775b8b1c-c50a-48c5-9946-c907d568eaf9', 'e11d1814-56ef-5b64-bfa3-b0806b43fb2a', 'පොස්පොලිපිඩ අණුවක පොස්ෆේට් කාණ්ඩ දෙකක් ඇත.', 'පොස්පොලිපිඩ අණුවක පොස්ෆේට් කාණ්ඩ දෙකක් ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a3c441f1-02ff-5a58-a986-b0b6f986a222', '825892d9-e9ee-54d1-9466-7d8032b8511f', 2, '<p>සංයුක්ත ආලෝක අන්වීක්ෂයක</p>', '<p>සංයුක්ත ආලෝක අන්වීක්ෂයක</p>', NULL, 'සංයුක්ත ආලෝක අන්වීක්ෂයක විභේදන බලය ආලෝකයේ තරංග ආයාමයට ප්‍රතිලෝමව සමානුපාතික වේ. මෙහි විභේදන බලය $0.2 \mu m$ පමණ වන අතර උපරිම විශාලනය නියම තරම මෙන් 1000 ගුණයක් පමණ වේ.', 'සංයුක්ත ආලෝක අන්වීක්ෂයක විභේදන බලය ආලෝකයේ තරංග ආයාමයට ප්‍රතිලෝමව සමානුපාතික වේ. මෙහි විභේදන බලය $0.2 \mu m$ පමණ වන අතර උපරිම විශාලනය නියම තරම මෙන් 1000 ගුණයක් පමණ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8abd7296-a7a3-4c9b-a4b6-b8da54c6e92b', 'a3c441f1-02ff-5a58-a986-b0b6f986a222', 'නිරීක්ෂණය කරනු ලබන නිදර්ශකයේ ප්‍රතිබිම්බය විශාල කිරීම සඳහා කාච මගින් ආලෝකය පරාවර්තනය කරනු ලැබේ.', 'නිරීක්ෂණය කරනු ලබන නිදර්ශකයේ ප්‍රතිබිම්බය විශාල කිරීම සඳහා කාච මගින් ආලෝකය පරාවර්තනය කරනු ලැබේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3abee37a-ff38-4eef-95aa-dfb3cfc78845', 'a3c441f1-02ff-5a58-a986-b0b6f986a222', 'විභේදන බලය ආලෝකයේ තරංග ආයාමයට ප්‍රතිලෝම ව සමානුපාතික වේ.', 'විභේදන බලය ආලෝකයේ තරංග ආයාමයට ප්‍රතිලෝම ව සමානුපාතික වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('94eb8e5f-f842-40c1-8f1d-70ba8ed2224f', 'a3c441f1-02ff-5a58-a986-b0b6f986a222', 'උපනෙත් කාචය මගින් ඇති කරනු ලබන ප්‍රතිබිම්බය අවනෙත් කාචය මගින් විශාල කරනු ලැබේ.', 'උපනෙත් කාචය මගින් ඇති කරනු ලබන ප්‍රතිබිම්බය අවනෙත් කාචය මගින් විශාල කරනු ලැබේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a6ee518f-85ba-4b60-8f1e-fa7225689b36', 'a3c441f1-02ff-5a58-a986-b0b6f986a222', 'උපරිම විශාලනය සාමාන්‍යයෙන් නිදර්ශකයේ නියම තරම මෙන් 600 ගුණයක් වේ.', 'උපරිම විශාලනය සාමාන්‍යයෙන් නිදර්ශකයේ නියම තරම මෙන් 600 ගුණයක් වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6f929347-a3b6-4426-b36c-c20e42c621c1', 'a3c441f1-02ff-5a58-a986-b0b6f986a222', 'විභේදන බලය 0.2 mm වේ.', 'විභේදන බලය 0.2 mm වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1c73c1ca-1d96-598d-9b94-b98749b44f9e', '825892d9-e9ee-54d1-9466-7d8032b8511f', 3, '<p>රළු අන්තඃප්ලාස්මීය ජාලිකාව සහ සිනිඳු අන්තඃප්ලාස්මීය ජාලිකාව යන දෙකටම පොදු කෘත්‍යයක් වන්නේ</p>', '<p>රළු අන්තඃප්ලාස්මීය ජාලිකාව සහ සිනිඳු අන්තඃප්ලාස්මීය ජාලිකාව යන දෙකටම පොදු කෘත්‍යයක් වන්නේ</p>', NULL, 'ලකුණු දීමේ පටිපාටියට අනුව දෙවන සහ සිව්වන පිළිතුරු දෙකම නිවැරදි ලෙස සලකා ඇත. රළු සහ සිනිඳු අන්තඃප්ලාස්මීය ජාලිකා දෙකම මගින් පොස්පොලිපිඩ සංශ්ලේෂණය කරන අතර පරිවහන ආශයිකා නිපදවීම ද සිදු කරයි. මෙහිදී 4 වන පිළිතුර (දර්ශකය 3) ලබා දී ඇත.', 'ලකුණු දීමේ පටිපාටියට අනුව දෙවන සහ සිව්වන පිළිතුරු දෙකම නිවැරදි ලෙස සලකා ඇත. රළු සහ සිනිඳු අන්තඃප්ලාස්මීය ජාලිකා දෙකම මගින් පොස්පොලිපිඩ සංශ්ලේෂණය කරන අතර පරිවහන ආශයිකා නිපදවීම ද සිදු කරයි. මෙහිදී 4 වන පිළිතුර (දර්ශකය 3) ලබා දී ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
