INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('60d2dbf7-4450-44d6-897c-19b26a73aa9a', 'f1f94ccb-7169-52de-b870-4ceacaf4578c', 'ගොල්ගි උපකරණය සෙලියුලෝස් නිපදවයි.', 'ගොල්ගි උපකරණය සෙලියුලෝස් නිපදවයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('07ba63c0-e6bc-4f0f-a919-16908d6f530e', 'f1f94ccb-7169-52de-b870-4ceacaf4578c', 'ප්‍රෝටීන වලින් තැනී ඇති න්‍යෂ්ටික තලාවේ ක්‍රොමැටින් ගිලී ඇත.', 'ප්‍රෝටීන වලින් තැනී ඇති න්‍යෂ්ටික තලාවේ ක්‍රොමැටින් ගිලී ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('55fe5990-e7f0-57d3-9c8c-06c4d91b835d', '825892d9-e9ee-54d1-9466-7d8032b8511f', 5, '<p>එන්සයිම පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>එන්සයිම පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ප්‍රශස්ත උෂ්ණත්වයට වඩා උෂ්ණත්වය වැඩි වන විට එන්සයිම විවෘතිකරණයට ලක් වන අතර, එමඟින් ඒවායේ සක්‍රිය ස්ථානයේ ත්‍රිමාන හැඩය වෙනස් වී එන්සයිම-උපස්තර සංකීර්ණය සෑදීම වළක්වයි.', 'ප්‍රශස්ත උෂ්ණත්වයට වඩා උෂ්ණත්වය වැඩි වන විට එන්සයිම විවෘතිකරණයට ලක් වන අතර, එමඟින් ඒවායේ සක්‍රිය ස්ථානයේ ත්‍රිමාන හැඩය වෙනස් වී එන්සයිම-උපස්තර සංකීර්ණය සෑදීම වළක්වයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54418f4f-aa28-481f-840f-485fa374caa4', '55fe5990-e7f0-57d3-9c8c-06c4d91b835d', 'සක්‍රියක, සහසංයුජ බන්ධන මගින් සක්‍රිය ස්ථානවලට බැඳීමෙන් එන්සයිමවල කෘත්‍යයට බලපෑම් ඇති කරයි.', 'සක්‍රියක, සහසංයුජ බන්ධන මගින් සක්‍රිය ස්ථානවලට බැඳීමෙන් එන්සයිමවල කෘත්‍යයට බලපෑම් ඇති කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('07247d1b-c119-4599-8deb-c2a659b053f3', '55fe5990-e7f0-57d3-9c8c-06c4d91b835d', 'ප්‍රශස්ත මට්ටමට වඩා වැඩි උෂ්ණත්වයන් මගින් එන්සයිමවල සක්‍රිය ස්ථාන වල හැඩය වෙනස් වේ.', 'ප්‍රශස්ත මට්ටමට වඩා වැඩි උෂ්ණත්වයන් මගින් එන්සයිමවල සක්‍රිය ස්ථාන වල හැඩය වෙනස් වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a69f583-5bf3-490e-8bc5-deee5d3c8ae8', '55fe5990-e7f0-57d3-9c8c-06c4d91b835d', 'බොහෝ තරගකාරී නිෂේධක, එන්සයිමවල සක්‍රිය ස්ථාන සමග අප්‍රතිවර්ත්‍ය ලෙස බැඳී ඒවායේ හැඩය වෙනස් කරයි.', 'බොහෝ තරගකාරී නිෂේධක, එන්සයිමවල සක්‍රිය ස්ථාන සමග අප්‍රතිවර්ත්‍ය ලෙස බැඳී ඒවායේ හැඩය වෙනස් කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('898f1112-012b-469c-b966-af8e0f0c2f97', '55fe5990-e7f0-57d3-9c8c-06c4d91b835d', 'විෂ ද්‍රව්‍ය සහ සංයුජ බන්ධන මගින් එන්සයිමවලට ප්‍රතිවර්ත්‍ය ලෙස බැඳේ.', 'විෂ ද්‍රව්‍ය සහ සංයුජ බන්ධන මගින් එන්සයිමවලට ප්‍රතිවර්ත්‍ය ලෙස බැඳේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fa1586f3-0759-4d29-bf16-b1a98db814cc', '55fe5990-e7f0-57d3-9c8c-06c4d91b835d', 'සහ එන්සයිම යනු එන්සයිමවලට ස්ථිර හෝ තාවකාලික හෝ ලෙස බැඳී ඇති ප්‍රෝටීනමය සංඝටක වේ.', 'සහ එන්සයිම යනු එන්සයිමවලට ස්ථිර හෝ තාවකාලික හෝ ලෙස බැඳී ඇති ප්‍රෝටීනමය සංඝටක වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4d6e6ecb-80f6-5eca-ad2a-e2a59a998845', '825892d9-e9ee-54d1-9466-7d8032b8511f', 6, '<p>ඉලෙක්ට්‍රෝන පරිවහන දාමය</p>', '<p>ඉලෙක්ට්‍රෝන පරිවහන දාමය</p>', NULL, 'ඉලෙක්ට්‍රෝන පරිවහන දාමය ප්‍රධාන වශයෙන් ප්‍රෝටීන සංකීර්ණ සහ යුබිකුයිනෝන් වැනි ප්‍රෝටීන නොවන අණු (සංඝටක) වලින් සමන්විත වේ.', 'ඉලෙක්ට්‍රෝන පරිවහන දාමය ප්‍රධාන වශයෙන් ප්‍රෝටීන සංකීර්ණ සහ යුබිකුයිනෝන් වැනි ප්‍රෝටීන නොවන අණු (සංඝටක) වලින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
