INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('38d05172-7f34-4a04-b8e4-b5020245f44f', '4d6e6ecb-80f6-5eca-ad2a-e2a59a998845', 'එක් NADH අණුවක් ඔක්සිකරණය කිරීම මගින් සාමාන්‍යය වශයෙන් ATP අණු දෙකක් ජනනය කරයි.', 'එක් NADH අණුවක් ඔක්සිකරණය කිරීම මගින් සාමාන්‍යය වශයෙන් ATP අණු දෙකක් ජනනය කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30e40ee6-7171-4f77-8ecb-c0010cdf0b5e', '4d6e6ecb-80f6-5eca-ad2a-e2a59a998845', 'ප්‍රථම ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහකයා ලෙස අණුක ඔක්සිජන් යොදා ගනී.', 'ප්‍රථම ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහකයා ලෙස අණුක ඔක්සිජන් යොදා ගනී.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('019006c7-a01b-43e9-8261-c9558ee51a47', '4d6e6ecb-80f6-5eca-ad2a-e2a59a998845', 'එක් $FADH_2$ අණුවක් ඔක්සිකරණය කිරීම මගින් සාමාන්‍යය වශයෙන් ATP අණුවක් ජනනය කරයි.', 'එක් $FADH_2$ අණුවක් ඔක්සිකරණය කිරීම මගින් සාමාන්‍යය වශයෙන් ATP අණුවක් ජනනය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('668e9d8c-19da-4a13-8e85-85a6b841ef1d', '4d6e6ecb-80f6-5eca-ad2a-e2a59a998845', 'ප්‍රෝටීන සහ ප්‍රෝටීන නොවන අණු වලින් සමන්විත වේ.', 'ප්‍රෝටීන සහ ප්‍රෝටීන නොවන අණු වලින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aef48933-daa6-57b1-9d33-a4b8e2c50d9b', '825892d9-e9ee-54d1-9466-7d8032b8511f', 7, '<p>ග්ලූකෝස් අණුවක ස්වායු ශ්වසනයේ සිදු වීම් හතරක් පහත දැක් වේ.<br><br>A - කාබොක්සිල්හරණයෙන් $CO_2$ අණු දෙකක් පිටවීම<br>B - NADH සහ $FADH_2$ ඔක්සිකරණය වීම<br>C - ඔක්සිකාරක පොස්පොරයිලීකරණය<br>D - උපස්තර මට්ටමේ පොස්පොරයිලීකරණය<br><br>ඉහත සිදුවීම් වල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', '<p>ග්ලූකෝස් අණුවක ස්වායු ශ්වසනයේ සිදු වීම් හතරක් පහත දැක් වේ.<br><br>A - කාබොක්සිල්හරණයෙන් $CO_2$ අණු දෙකක් පිටවීම<br>B - NADH සහ $FADH_2$ ඔක්සිකරණය වීම<br>C - ඔක්සිකාරක පොස්පොරයිලීකරණය<br>D - උපස්තර මට්ටමේ පොස්පොරයිලීකරණය<br><br>ඉහත සිදුවීම් වල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', NULL, 'පයිරුවේට් ඔක්සිකරණයේදී කාබොක්සිල්හරණය (A) සිදුවේ. ඉන්පසු ක්‍රෙබ්ස් චක්‍රයේදී උපස්තර මට්ටමේ පොස්පොරයිලීකරණය (D) සිදුවේ. අවසාන අදියරේදී ඉලෙක්ට්‍රෝන පරිවහන දාමයට NADH සහ $FADH_2$ ඔක්සිකරණය (B) වීමෙන් පසු ඔක්සිකාරක පොස්පොරයිලීකරණය (C) සිදුවේ. එබැවින් නිවැරදි අනුපිළිවෙල A, D, B, C වේ.', 'පයිරුවේට් ඔක්සිකරණයේදී කාබොක්සිල්හරණය (A) සිදුවේ. ඉන්පසු ක්‍රෙබ්ස් චක්‍රයේදී උපස්තර මට්ටමේ පොස්පොරයිලීකරණය (D) සිදුවේ. අවසාන අදියරේදී ඉලෙක්ට්‍රෝන පරිවහන දාමයට NADH සහ $FADH_2$ ඔක්සිකරණය (B) වීමෙන් පසු ඔක්සිකාරක පොස්පොරයිලීකරණය (C) සිදුවේ. එබැවින් නිවැරදි අනුපිළිවෙල A, D, B, C වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
