INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('154e53df-62c9-4fd3-aa46-ebc7886adbba', '28974ed0-8eee-54ad-bd13-419d3950ce39', 'මුලාග්‍රස්ථයේ සහ ප්‍රරෝහ අග්‍රස්ථයේ පමණක් දැකිය හැකි ය.', 'මුලාග්‍රස්ථයේ සහ ප්‍රරෝහ අග්‍රස්ථයේ පමණක් දැකිය හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('693f66a9-d9db-481c-ae7c-b52529dfdd10', '28974ed0-8eee-54ad-bd13-419d3950ce39', 'විශාල මධ්‍ය රික්තකයක් තිබීම නිසා පැත්තකට විස්ථාපනය වූ න්‍යෂ්ටියක් දරයි.', 'විශාල මධ්‍ය රික්තකයක් තිබීම නිසා පැත්තකට විස්ථාපනය වූ න්‍යෂ්ටියක් දරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('59fd6840-0b25-585a-b5be-0393584faa51', '825892d9-e9ee-54d1-9466-7d8032b8511f', 14, '<p>පහත සඳහන් ඒවා අතුරෙන් පුටිකා විවෘත වීම සඳහා දායක වන්නේ මොනවාද?<br><br>A - පාලක සෛලවල ශූනතාව වැඩි වීම<br>B - ඇබ්සිසික් අම්ලය නිපදවීම<br>C - පාලක සෛලවල සිට අධඃපූටිකා කුටීරය තුළට ජලය ගලා ඒම<br>D - පාලක සෛල තුළ $K^+$ එක්රැස් වීම</p>', '<p>පහත සඳහන් ඒවා අතුරෙන් පුටිකා විවෘත වීම සඳහා දායක වන්නේ මොනවාද?<br><br>A - පාලක සෛලවල ශූනතාව වැඩි වීම<br>B - ඇබ්සිසික් අම්ලය නිපදවීම<br>C - පාලක සෛලවල සිට අධඃපූටිකා කුටීරය තුළට ජලය ගලා ඒම<br>D - පාලක සෛල තුළ $K^+$ එක්රැස් වීම</p>', NULL, 'පූටිකා විවෘත වීමේදී පාලක සෛල තුළට $K^+$ අයන සක්‍රියව ඇතුළු වීම (D) නිසා ආස්‍රැති විභවය අඩුවී, ජලය ඇතුළු වීමෙන් ශූනතාව වැඩි වේ (A). ඇබ්සිසික් අම්ලය පූටිකා වැසීමට දායක වේ.', 'පූටිකා විවෘත වීමේදී පාලක සෛල තුළට $K^+$ අයන සක්‍රියව ඇතුළු වීම (D) නිසා ආස්‍රැති විභවය අඩුවී, ජලය ඇතුළු වීමෙන් ශූනතාව වැඩි වේ (A). ඇබ්සිසික් අම්ලය පූටිකා වැසීමට දායක වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
