INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('690b2b9f-2691-4e64-b4a1-3cc8662bd7e0', 'ba0ccacc-cea9-5946-a8cd-049ba438402e', 'රුධිරයේ සිටින විශිෂ්ට ව්‍යාධිජනකයන් කෙළින් ම විනාශ කිරීමට ඒවාට පුළුවන.', 'රුධිරයේ සිටින විශිෂ්ට ව්‍යාධිජනකයන් කෙළින් ම විනාශ කිරීමට ඒවාට පුළුවන.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c9201f3a-af28-410b-86cb-09f183a0814e', 'ba0ccacc-cea9-5946-a8cd-049ba438402e', 'ඒවා විශිෂ්ට ප්‍රතිදේහජනක සමග බැඳී අනුපූරක පද්ධතිය සක්‍රිය කරයි.', 'ඒවා විශිෂ්ට ප්‍රතිදේහජනක සමග බැඳී අනුපූරක පද්ධතිය සක්‍රිය කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('faa6a3b3-4bb0-546e-8ced-fc6068208679', '825892d9-e9ee-54d1-9466-7d8032b8511f', 24, '<p>මිනිස් මොළයේ හෘත්සනාල පාලන මධ්‍යස්ථානය පිහිටා ඇත්තේ</p>', '<p>මිනිස් මොළයේ හෘත්සනාල පාලන මධ්‍යස්ථානය පිහිටා ඇත්තේ</p>', NULL, 'මිනිස් මොළයේ හෘත්සනාල පාලන මධ්‍යස්ථානය (Cardiovascular control center) පිහිටා ඇත්තේ සුෂුම්නා ශීර්ෂකය (Medulla oblongata) තුළය.', 'මිනිස් මොළයේ හෘත්සනාල පාලන මධ්‍යස්ථානය (Cardiovascular control center) පිහිටා ඇත්තේ සුෂුම්නා ශීර්ෂකය (Medulla oblongata) තුළය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
