INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cdba7e34-e4b4-5135-8098-6bb00625db45', '825892d9-e9ee-54d1-9466-7d8032b8511f', 26, '<p>මිනිසාගේ සංවේදක ප්‍රතිග්‍රාහක පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිසාගේ සංවේදක ප්‍රතිග්‍රාහක පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ආඝ්‍රාණ ප්‍රතිග්‍රාහක (Olfactory receptors) නිරන්තර උත්තේජනයකදී සංවේදන අනුවර්තනය (Sensory adaptation) දක්වයි.', 'ආඝ්‍රාණ ප්‍රතිග්‍රාහක (Olfactory receptors) නිරන්තර උත්තේජනයකදී සංවේදන අනුවර්තනය (Sensory adaptation) දක්වයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
