INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1183af66-aaa9-4873-bd2c-c5c8e2a98fb9', 'cdba7e34-e4b4-5135-8098-6bb00625db45', 'ආඝ්‍රාණ ප්‍රතිග්‍රාහක සංවේදන අනුවර්තනය දක්වයි.', 'ආඝ්‍රාණ ප්‍රතිග්‍රාහක සංවේදන අනුවර්තනය දක්වයි.', NULL, 'sanitized', 'v1', 1, 0);
