INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('df354a27-0335-4769-8414-62f649976e0c', 'cdba7e34-e4b4-5135-8098-6bb00625db45', 'කනේ ආලින්දයේ ඇති රෝම සෛල මගින් කෝණික චලන හඳුනා ගැනේ.', 'කනේ ආලින්දයේ ඇති රෝම සෛල මගින් කෝණික චලන හඳුනා ගැනේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4a5e88f5-0b62-522d-9fae-22f783ef70e4', '825892d9-e9ee-54d1-9466-7d8032b8511f', 27, '<p>පූර්ව පිටියුටරිය මගින් ස්‍රාවය කරනු ලබන පෝෂී බලපෑම් ඇති නොකරන හෝමෝනයක් වන්නේ</p>', '<p>පූර්ව පිටියුටරිය මගින් ස්‍රාවය කරනු ලබන පෝෂී බලපෑම් ඇති නොකරන හෝමෝනයක් වන්නේ</p>', NULL, 'ප්‍රොලැක්ටින් යනු පූර්ව පිටියුටරියෙන් ස්‍රාවය වන අතර එය කෙළින්ම ක්ෂීර ග්‍රන්ථි මත ක්‍රියා කරන හෝමෝනයකි. ඔක්සිටොසින් සහ ADH ස්‍රාවය කරන්නේ පසු පිටියුටරිය මගිනි.', 'ප්‍රොලැක්ටින් යනු පූර්ව පිටියුටරියෙන් ස්‍රාවය වන අතර එය කෙළින්ම ක්ෂීර ග්‍රන්ථි මත ක්‍රියා කරන හෝමෝනයකි. ඔක්සිටොසින් සහ ADH ස්‍රාවය කරන්නේ පසු පිටියුටරිය මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
