INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1a9c1620-8500-59ac-a7fe-4b537511f34c', '825892d9-e9ee-54d1-9466-7d8032b8511f', 32, '<p>මානව ලිංග ප්‍රතිබද්ධ ආවේණියේදී</p>', '<p>මානව ලිංග ප්‍රතිබද්ධ ආවේණියේදී</p>', NULL, 'පිරිමින්ට ඇත්තේ එක් X වර්ණදේහයක් පමණක් බැවින්, X-ප්‍රතිබද්ධ නිලීන ජානයක් (උදා: වර්ණාන්ධතාව) ඇති විට එය පිරිමින් තුළ ප්‍රකාශ වේ. ස්ත්‍රීන්ට X වර්ණදේහ දෙකක් ඇති බැවින් නිලීන ලක්ෂණයක් ප්‍රකාශ වීමට ඔවුන් සමයුග්මක විය යුතුය.', 'පිරිමින්ට ඇත්තේ එක් X වර්ණදේහයක් පමණක් බැවින්, X-ප්‍රතිබද්ධ නිලීන ජානයක් (උදා: වර්ණාන්ධතාව) ඇති විට එය පිරිමින් තුළ ප්‍රකාශ වේ. ස්ත්‍රීන්ට X වර්ණදේහ දෙකක් ඇති බැවින් නිලීන ලක්ෂණයක් ප්‍රකාශ වීමට ඔවුන් සමයුග්මක විය යුතුය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ce564a3-fe17-4b4f-b9ad-b84db5510ed5', '1a9c1620-8500-59ac-a7fe-4b537511f34c', 'X - ප්‍රතිබද්ධ බොහෝ නිලීන ආබාධ ස්ත්‍රීන්ගේ විෂම යුග්මක ප්‍රවේණිදර්ශය මගින් ප්‍රකාශ කෙරේ.', 'X - ප්‍රතිබද්ධ බොහෝ නිලීන ආබාධ ස්ත්‍රීන්ගේ විෂම යුග්මක ප්‍රවේණිදර්ශය මගින් ප්‍රකාශ කෙරේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('298a7e66-beae-49bc-8468-8fc2f512a2c0', '1a9c1620-8500-59ac-a7fe-4b537511f34c', 'X - ප්‍රතිබද්ධ බොහෝ නිලීන ආබාධ පිරිමින්ගේ ප්‍රකාශ කෙරේ.', 'X - ප්‍රතිබද්ධ බොහෝ නිලීන ආබාධ පිරිමින්ගේ ප්‍රකාශ කෙරේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9cfb5cb5-0429-4785-9211-425e1cc53111', '1a9c1620-8500-59ac-a7fe-4b537511f34c', 'X - ප්‍රතිබද්ධ ලක්ෂණ මව විසින් සම්ප්‍රේෂණය කරනුයේ තම දියණියන්ට පමණි.', 'X - ප්‍රතිබද්ධ ලක්ෂණ මව විසින් සම්ප්‍රේෂණය කරනුයේ තම දියණියන්ට පමණි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fa8f42c3-6373-48d2-9587-3a57530a8b99', '1a9c1620-8500-59ac-a7fe-4b537511f34c', 'X - ප්‍රතිබද්ධ ලක්ෂණ පියා විසින් සම්ප්‍රේෂණය කරනුයේ තම පුතුන්ට පමණි.', 'X - ප්‍රතිබද්ධ ලක්ෂණ පියා විසින් සම්ප්‍රේෂණය කරනුයේ තම පුතුන්ට පමණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d3927052-8ec4-4946-b8d1-9a7cc7afc7d5', '1a9c1620-8500-59ac-a7fe-4b537511f34c', 'පිරිමින් X - ප්‍රතිබද්ධ ප්‍රමුඛ ආබාධ පමණක් ප්‍රකාශ කරයි.', 'පිරිමින් X - ප්‍රතිබද්ධ ප්‍රමුඛ ආබාධ පමණක් ප්‍රකාශ කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('56b3ce68-3e00-5531-91ac-31b3173a5626', '825892d9-e9ee-54d1-9466-7d8032b8511f', 33, '<p>ඒකාංග මුහුමක $F_2$ පරම්පරාවේ රූපාණු දර්ශ සහ ප්‍රවේණි දර්ශ යන දෙකම 1:2:1 අනුපාතය දක්වයි නම් එම ප්‍රවේණි ආකාරය</p>', '<p>ඒකාංග මුහුමක $F_2$ පරම්පරාවේ රූපාණු දර්ශ සහ ප්‍රවේණි දර්ශ යන දෙකම 1:2:1 අනුපාතය දක්වයි නම් එම ප්‍රවේණි ආකාරය</p>', NULL, 'සම්මත මෙන්ඩලීය ප්‍රමුඛතාවයේදී රූපාණුදර්ශ අනුපාතය 3:1 වේ. නමුත් අසම්පූර්ණ ප්‍රමුඛතාවයේදී (Incomplete dominance) සහ සහප්‍රමුඛතාවයේදී (Codominance) ප්‍රවේණිදර්ශ අනුපාතයට (1:2:1) සමානව රූපාණුදර්ශ අනුපාතය ද 1:2:1 බවට පත් වේ.', 'සම්මත මෙන්ඩලීය ප්‍රමුඛතාවයේදී රූපාණුදර්ශ අනුපාතය 3:1 වේ. නමුත් අසම්පූර්ණ ප්‍රමුඛතාවයේදී (Incomplete dominance) සහ සහප්‍රමුඛතාවයේදී (Codominance) ප්‍රවේණිදර්ශ අනුපාතයට (1:2:1) සමානව රූපාණුදර්ශ අනුපාතය ද 1:2:1 බවට පත් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
