INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('594093d5-3a1f-4770-bde1-248c2a1c2d3a', '39208446-6aa6-5fbf-9720-064a6680c3dc', 'විෂම ගුණකතාවට තුඩු දිය හැකි ය.', 'විෂම ගුණකතාවට තුඩු දිය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('68237ec5-bc95-5b84-88df-27e75a4a1274', '825892d9-e9ee-54d1-9466-7d8032b8511f', 35, '<p>ප්‍රතිසංයෝජිත DNA තාක්ෂණයේ ඵල පමණක් අඩංගු පිළිතුර තෝරන්න.</p>', '<p>ප්‍රතිසංයෝජිත DNA තාක්ෂණයේ ඵල පමණක් අඩංගු පිළිතුර තෝරන්න.</p>', NULL, '''RoundUp Ready'' සෝයා බෝංචි, බැක්ටීරියා මගින් නිපදවන මානව ඉන්සියුලින්, සහ Flavr Savr වැනි ඵල ඉදීම ප්‍රමාද කළ තක්කාලි යනු ප්‍රතිසංයෝජිත DNA තාක්ෂණයෙන් නිපදවන ලද ජාන විකරිත (GM) ඵල වේ.', '''RoundUp Ready'' සෝයා බෝංචි, බැක්ටීරියා මගින් නිපදවන මානව ඉන්සියුලින්, සහ Flavr Savr වැනි ඵල ඉදීම ප්‍රමාද කළ තක්කාලි යනු ප්‍රතිසංයෝජිත DNA තාක්ෂණයෙන් නිපදවන ලද ජාන විකරිත (GM) ඵල වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
