INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9992748b-e805-4eb0-8848-4dc1c3522b4f', '68237ec5-bc95-5b84-88df-27e75a4a1274', 'ඇට රහිත මිදි, නියඟට ප්‍රතිරෝධී සෝයා බෝංචි, චීස් සෑදීම සඳහා ගන්නා කයි මොසීන්', 'ඇට රහිත මිදි, නියඟට ප්‍රතිරෝධී සෝයා බෝංචි, චීස් සෑදීම සඳහා ගන්නා කයි මොසීන්', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('96ff414b-9bbe-4713-b66c-6189f8471a64', '68237ec5-bc95-5b84-88df-27e75a4a1274', '''RoundUp Ready'' සෝයා බෝංචි, මානව ඉන්සියුලින්, ඵල ඉදීම ප්‍රමාද කළ තක්කාලි', '''RoundUp Ready'' සෝයා බෝංචි, මානව ඉන්සියුලින්, ඵල ඉදීම ප්‍රමාද කළ තක්කාලි', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9feefc49-42a7-57e7-b7b7-e62f4e427ba7', '825892d9-e9ee-54d1-9466-7d8032b8511f', 36, '<p>භෞමික පරිසර පද්ධතියක ආහාර ජාලය පහත දැක්වේ.<br><br>ඉහත පරිසර පද්ධතියේ සිටින ද්විතීයික සහ තෘතීයික පරිභෝජකයන් සංඛ්‍යාව පිළිවෙළින්</p>', '<p>භෞමික පරිසර පද්ධතියක ආහාර ජාලය පහත දැක්වේ.<br><br>ඉහත පරිසර පද්ධතියේ සිටින ද්විතීයික සහ තෘතීයික පරිභෝජකයන් සංඛ්‍යාව පිළිවෙළින්</p>', NULL, 'ප්‍රාථමික පරිභෝජකයන් (තණකොළ පෙත්තා, මීයා, හාවා, මුවා) ආහාරයට ගන්නා ද්විතීයික පරිභෝජකයන්: කටුස්සා, නයා, උකුස්සා, නරියා, දිවියා යන පස් දෙනාම වේ. ද්විතීයික පරිභෝජකයන් ආහාරයට ගන්නා තෘතීයික පරිභෝජකයන්: නයා (කටුස්සා කෑමෙන්), උකුස්සා (නයා කෑමෙන්), දිවියා (නරියා කෑමෙන්) යන තුන් දෙනා වේ.', 'ප්‍රාථමික පරිභෝජකයන් (තණකොළ පෙත්තා, මීයා, හාවා, මුවා) ආහාරයට ගන්නා ද්විතීයික පරිභෝජකයන්: කටුස්සා, නයා, උකුස්සා, නරියා, දිවියා යන පස් දෙනාම වේ. ද්විතීයික පරිභෝජකයන් ආහාරයට ගන්නා තෘතීයික පරිභෝජකයන්: නයා (කටුස්සා කෑමෙන්), උකුස්සා (නයා කෑමෙන්), දිවියා (නරියා කෑමෙන්) යන තුන් දෙනා වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
