INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fed0c8a6-71b1-46fa-944e-6ed47db079a6', '31364e98-96e4-5ec3-af40-63eb8aeac12a', 'ගණාවාසී සූත්‍රි කාමය නොවන සයනොබැක්ටීරියා සහ බැක්ටීරියාවලය.', 'ගණාවාසී සූත්‍රි කාමය නොවන සයනොබැක්ටීරියා සහ බැක්ටීරියාවලය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('194df3e6-8b71-5850-9b36-1f12ea17185f', '825892d9-e9ee-54d1-9466-7d8032b8511f', 39, '<p>Escherichia coli</p>', '<p>Escherichia coli</p>', NULL, 'E. coli යනු මිනිස් අන්ත්‍රයේ ජීවත් වන සාමාන්‍ය සහජීවී බැක්ටීරියාවක් වන අතර, එය මහා අන්ත්‍රයේදී විටමින් K සහ සමහර B විටමින් සංශ්ලේෂණය කරයි. එය මුත්‍රා මාර්ගයේ හෝ පෙනහැලි වැනි වෙනත් ස්ථාන වලට ගියහොත් අවස්ථාවාදී ව්‍යාධිජනකයෙකු (opportunistic pathogen) ලෙස ක්‍රියා කර ආසාදන ඇති කළ හැක.', 'E. coli යනු මිනිස් අන්ත්‍රයේ ජීවත් වන සාමාන්‍ය සහජීවී බැක්ටීරියාවක් වන අතර, එය මහා අන්ත්‍රයේදී විටමින් K සහ සමහර B විටමින් සංශ්ලේෂණය කරයි. එය මුත්‍රා මාර්ගයේ හෝ පෙනහැලි වැනි වෙනත් ස්ථාන වලට ගියහොත් අවස්ථාවාදී ව්‍යාධිජනකයෙකු (opportunistic pathogen) ලෙස ක්‍රියා කර ආසාදන ඇති කළ හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
