INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c6a6f920-ce7f-4a7e-9a58-27d140829b90', '194df3e6-8b71-5850-9b36-1f12ea17185f', 'අලුත උපන් ළදරුවෙකුගේ අන්ත්‍රයට ඇතුළු වන ප්‍රථම ක්ෂුද්‍රජීවියා ය.', 'අලුත උපන් ළදරුවෙකුගේ අන්ත්‍රයට ඇතුළු වන ප්‍රථම ක්ෂුද්‍රජීවියා ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a1743bd5-3510-43fd-8f1e-7990b1d6069c', '194df3e6-8b71-5850-9b36-1f12ea17185f', 'පෙනහැලි ආසාදනය කළ හැකි අවස්ථාවාදී ව්‍යාධිජනකයෙකි.', 'පෙනහැලි ආසාදනය කළ හැකි අවස්ථාවාදී ව්‍යාධිජනකයෙකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('def43a83-c050-41e2-ba42-f6631f473f72', '194df3e6-8b71-5850-9b36-1f12ea17185f', 'ප්‍රතිජීවක චිකිත්සාවේදී ප්‍රෝබයොටික් ලෙස අධිග්‍රහණය කෙරේ.', 'ප්‍රතිජීවක චිකිත්සාවේදී ප්‍රෝබයොටික් ලෙස අධිග්‍රහණය කෙරේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('15b849f0-ec98-5cdd-9df3-08573a8e8c78', '825892d9-e9ee-54d1-9466-7d8032b8511f', 40, '<p>මල් වගා කර්මාන්තයේදී භාවිත වන ශාක සමහරක් සහ ඒවායේ වර්ධක ප්‍රචාරණ ක්‍රම පහත දැක්වේ.<br><br>(A) වද - අතු බැඳීම<br>(B) Snake plant - පත්‍ර කැබලි භාවිත කිරීම<br>(C) ගෝනුසු ශාකය - බද්ධ කිරීම<br>(D) බිගෝනියා - වෙන් කිරීම<br><br>ඉහත සඳහන් සංකලන අතුරෙන් නිවැරදි වන්නේ මොනවාද?</p>', '<p>මල් වගා කර්මාන්තයේදී භාවිත වන ශාක සමහරක් සහ ඒවායේ වර්ධක ප්‍රචාරණ ක්‍රම පහත දැක්වේ.<br><br>(A) වද - අතු බැඳීම<br>(B) Snake plant - පත්‍ර කැබලි භාවිත කිරීම<br>(C) ගෝනුසු ශාකය - බද්ධ කිරීම<br>(D) බිගෝනියා - වෙන් කිරීම<br><br>ඉහත සඳහන් සංකලන අතුරෙන් නිවැරදි වන්නේ මොනවාද?</p>', NULL, 'වද ශාකය (Hibiscus) අතු බැඳීමෙන් ද, Snake plant (Sansevieria) පත්‍ර කැබලි මගින් ද ප්‍රචාරණය කළ හැක. (C සහ D වල දක්වා ඇති ක්‍රම එම ශාක සඳහා බහුලව යොදා නොගනී).', 'වද ශාකය (Hibiscus) අතු බැඳීමෙන් ද, Snake plant (Sansevieria) පත්‍ර කැබලි මගින් ද ප්‍රචාරණය කළ හැක. (C සහ D වල දක්වා ඇති ක්‍රම එම ශාක සඳහා බහුලව යොදා නොගනී).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
