INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7327307c-35eb-4ef8-8614-5bf6781de37f', '3030e159-3e19-5fcc-90e7-7cc33f637580', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදිය.', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදිය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fefeb2ca-bbd3-58f3-adb3-0c2a3559cff1', '825892d9-e9ee-54d1-9466-7d8032b8511f', 49, '<p>ජලය සහ ආහාර යන දෙකම මගින් බෝවන රෝග ඇති කරනුයේ පහත සඳහන් කුමන බැක්ටීරියා විශේෂයද?/ විශේෂ ද?<br><br>(A) Salmonella sp.<br>(B) Staphylococcus sp.<br>(C) Vibrio sp.<br>(D) Shigella sp.<br>(E) Clostridium sp.</p>', '<p>ජලය සහ ආහාර යන දෙකම මගින් බෝවන රෝග ඇති කරනුයේ පහත සඳහන් කුමන බැක්ටීරියා විශේෂයද?/ විශේෂ ද?<br><br>(A) Salmonella sp.<br>(B) Staphylococcus sp.<br>(C) Vibrio sp.<br>(D) Shigella sp.<br>(E) Clostridium sp.</p>', NULL, 'Salmonella (ටයිපොයිඩ්/ආහාර විෂවීම), Vibrio (කොලරාව), සහ Shigella (අතීසාරය) යන බැක්ටීරියා ආහාර මෙන්ම අපිරිසිදු ජලය මගින් ද බෝවිය හැක.', 'Salmonella (ටයිපොයිඩ්/ආහාර විෂවීම), Vibrio (කොලරාව), සහ Shigella (අතීසාරය) යන බැක්ටීරියා ආහාර මෙන්ම අපිරිසිදු ජලය මගින් ද බෝවිය හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
