INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d36601f5-e157-5dc7-a2a2-b4ad0a3c0afb', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 6, '<p>ක්‍රමලේඛයක් වේගයෙන්ම ක්‍රියාත්මක වන්නේ එයට අවශ්‍ය දත්ත,</p>', '<p>ක්‍රමලේඛයක් වේගයෙන්ම ක්‍රියාත්මක වන්නේ එයට අවශ්‍ය දත්ත,</p>', NULL, 'දත්ත පිවිසුම් වේගය (Access speed) අනුව, L1 Cache යනු සකසනයට (CPU) සමීපතම සහ වේගවත්ම මතකය වේ.', 'දත්ත පිවිසුම් වේගය (Access speed) අනුව, L1 Cache යනු සකසනයට (CPU) සමීපතම සහ වේගවත්ම මතකය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
