INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c3df8226-5683-45bb-bbc4-a49d8d77dedb', 'd36601f5-e157-5dc7-a2a2-b4ad0a3c0afb', 'L2 නිහිත මතකයේ තිබෙන විට ය.', 'L2 නිහිත මතකයේ තිබෙන විට ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b2750dc7-637e-4c8b-bfb9-280cff8b66fa', 'd36601f5-e157-5dc7-a2a2-b4ad0a3c0afb', 'චුම්භක පටියේ (magnetic tape) තිබෙන විට ය.', 'චුම්භක පටියේ (magnetic tape) තිබෙන විට ය.', NULL, 'sanitized', 'v1', 3, 0);
