INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('26377be1-cb2a-500e-9f43-01c5b460daf9', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 7, '<p>දශමය $13.125_{10}$ ට තුල්‍ය වන නිවැරදි ද්විමය සංඛ්‍යාව කුමක්ද?</p>', '<p>දශමය $13.125_{10}$ ට තුල්‍ය වන නිවැරදි ද්විමය සංඛ්‍යාව කුමක්ද?</p>', NULL, 'පූර්ණ සංඛ්‍යා කොටස: $13_{10} = 1101_2$.<br>දශම කොටස: $0.125 \times 2 = 0.25 (0)$, $0.25 \times 2 = 0.5 (0)$, $0.5 \times 2 = 1.0 (1)$. එබැවින් $0.125_{10} = 0.001_2$.<br>සම්පූර්ණ අගය: $1101.001_2$.', 'පූර්ණ සංඛ්‍යා කොටස: $13_{10} = 1101_2$.<br>දශම කොටස: $0.125 \times 2 = 0.25 (0)$, $0.25 \times 2 = 0.5 (0)$, $0.5 \times 2 = 1.0 (1)$. එබැවින් $0.125_{10} = 0.001_2$.<br>සම්පූර්ණ අගය: $1101.001_2$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
