INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5d1b342c-eef3-56fd-a7ed-69a18fce5f7c', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 8, '<p>පහත කවරක් අෂ්ඨමය $674_8$ ට තුල්‍ය වේද?<br><br>A - $110 111 100_2$<br>B - $444_{10}$<br>C - $2BC_{16}$</p>', '<p>පහත කවරක් අෂ්ඨමය $674_8$ ට තුල්‍ය වේද?<br><br>A - $110 111 100_2$<br>B - $444_{10}$<br>C - $2BC_{16}$</p>', NULL, 'A: $674_8$ හි අෂ්ඨමය ඉලක්කම් ද්විමයට හැරවූ විට $6=110$, $7=111$, $4=100$ වේ. එබැවින් $110111100_2$ (සත්‍යය).<br>B: දශමයට හැරවූ විට, $6 \times 8^2 + 7 \times 8^1 + 4 \times 8^0 = 384 + 56 + 4 = 444_{10}$ (සත්‍යය).<br>C: ෂඩ්දශමයට හැරවූ විට, ද්විමය අගය බිටු 4 කාණ්ඩ කළහොත් $0001\ 1011\ 1100_2 = 1BC_{16}$ වේ, $2BC_{16}$ නොවේ. එබැවින් A සහ B පමණි.', 'A: $674_8$ හි අෂ්ඨමය ඉලක්කම් ද්විමයට හැරවූ විට $6=110$, $7=111$, $4=100$ වේ. එබැවින් $110111100_2$ (සත්‍යය).<br>B: දශමයට හැරවූ විට, $6 \times 8^2 + 7 \times 8^1 + 4 \times 8^0 = 384 + 56 + 4 = 444_{10}$ (සත්‍යය).<br>C: ෂඩ්දශමයට හැරවූ විට, ද්විමය අගය බිටු 4 කාණ්ඩ කළහොත් $0001\ 1011\ 1100_2 = 1BC_{16}$ වේ, $2BC_{16}$ නොවේ. එබැවින් A සහ B පමණි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
