INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2ef0ccba-205b-5fa7-ab98-d0ca2c756c87', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 9, '<p>උපදෙසක යොමුව (address) ෂඩ්දශමය $5A1_{16}$ ලෙස දැක්විණි. එම යොමුව දශමය ආකාරයට කුමක් වේද?</p>', '<p>උපදෙසක යොමුව (address) ෂඩ්දශමය $5A1_{16}$ ලෙස දැක්විණි. එම යොමුව දශමය ආකාරයට කුමක් වේද?</p>', NULL, '$5A1_{16} = 5 \times 16^2 + 10 \times 16^1 + 1 \times 16^0$<br>$= 5 \times 256 + 10 \times 16 + 1$<br>$= 1280 + 160 + 1$<br>$= 1441_{10}$.', '$5A1_{16} = 5 \times 16^2 + 10 \times 16^1 + 1 \times 16^0$<br>$= 5 \times 256 + 10 \times 16 + 1$<br>$= 1280 + 160 + 1$<br>$= 1441_{10}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
