INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fc1cbc0a-216e-5b9f-ac9a-01c008ff4a08', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 13, '<p>$X(\overline{X}+Y)$ බූලිය ප්‍රකාශයේ සරල ආකාරය පහත කුමක්ද?</p>', '<p>$X(\overline{X}+Y)$ බූලිය ප්‍රකාශයේ සරල ආකාරය පහත කුමක්ද?</p>', NULL, 'බූලීය වීජ ගණිතයේ ව්‍යාප්ති නියමය අනුව: $X(\overline{X}+Y) = X\overline{X} + XY$.<br>නමුත් $X\overline{X} = 0$ වේ. එබැවින් $0 + XY = XY$.', 'බූලීය වීජ ගණිතයේ ව්‍යාප්ති නියමය අනුව: $X(\overline{X}+Y) = X\overline{X} + XY$.<br>නමුත් $X\overline{X} = 0$ වේ. එබැවින් $0 + XY = XY$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
