INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('64898775-e5fb-4f3f-b179-a197015b85ca', 'c5bea0ea-d136-5841-b025-938b9748fa33', 'ජනප්‍රිය වෙබ් අතරික්සු හරහා ඉ-වාණිජ්‍යය වෙබ් අඩවියට ප්‍රවේශවීමේ හැකියාව', 'ජනප්‍රිය වෙබ් අතරික්සු හරහා ඉ-වාණිජ්‍යය වෙබ් අඩවියට ප්‍රවේශවීමේ හැකියාව', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5e68f05c-716f-5b44-9a07-cdc34946648f', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 26, '<p>යෙදුමක සංවර්ධකයින් විසින් එය ස්ථාපනය කිරීමට බලාපොරොත්තුවන දෘඪාංග, මෘදුකාංග සහ ජාල වින්‍යාස පරිසරයට වඩාත් සමීප පරිසරයක සිදු කරන පරීක්ෂාව පහත කවරක් ද?</p>', '<p>යෙදුමක සංවර්ධකයින් විසින් එය ස්ථාපනය කිරීමට බලාපොරොත්තුවන දෘඪාංග, මෘදුකාංග සහ ජාල වින්‍යාස පරිසරයට වඩාත් සමීප පරිසරයක සිදු කරන පරීක්ෂාව පහත කවරක් ද?</p>', NULL, 'සම්පූර්ණ පද්ධතියේ ක්‍රියාකාරිත්වය සැබෑ පරිසරයට සමාන පරිසරයක (Production-like environment) පරීක්ෂා කිරීම පද්ධති පරීක්ෂාව (System testing) ලෙස හැඳින්වේ.', 'සම්පූර්ණ පද්ධතියේ ක්‍රියාකාරිත්වය සැබෑ පරිසරයට සමාන පරිසරයක (Production-like environment) පරීක්ෂා කිරීම පද්ධති පරීක්ෂාව (System testing) ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
