INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4fcd6219-f4e8-5722-a548-96b7d005cdb9', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 29, '<p>මෘදුකාංග ගොඩනැගීමට අදාළ දිය ඇලි (waterfall) ආකෘතිය සම්බන්ධයෙන් අසත්‍ය වන්නේ පහත කවරක් ද?</p>', '<p>මෘදුකාංග ගොඩනැගීමට අදාළ දිය ඇලි (waterfall) ආකෘතිය සම්බන්ධයෙන් අසත්‍ය වන්නේ පහත කවරක් ද?</p>', NULL, 'දිය ඇලි (Waterfall) ආකෘතියේ අවශ්‍යතා එකතු කිරීම සම්පූර්ණයෙන්ම ව්‍යාපෘතියේ ආරම්භක අදියරේදීම සිදු කර අවසන් කෙරේ. ව්‍යාපෘතිය පුරාම අවශ්‍යතා වෙනස් කිරීමට හෝ එකතු කිරීමට මෙම ආකෘතිය ඉඩ නොදෙයි.', 'දිය ඇලි (Waterfall) ආකෘතියේ අවශ්‍යතා එකතු කිරීම සම්පූර්ණයෙන්ම ව්‍යාපෘතියේ ආරම්භක අදියරේදීම සිදු කර අවසන් කෙරේ. ව්‍යාපෘතිය පුරාම අවශ්‍යතා වෙනස් කිරීමට හෝ එකතු කිරීමට මෙම ආකෘතිය ඉඩ නොදෙයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('898ed900-36a3-45f9-b045-cc846c4e8832', '4fcd6219-f4e8-5722-a548-96b7d005cdb9', 'සංවර්ධකයන්ට ව්‍යාපෘතිය පුරාවටම අවශ්‍යතා එකතු කිරීමටත්, ක්‍රියාත්මක කිරීමටත් එය ඉඩ දෙයි.', 'සංවර්ධකයන්ට ව්‍යාපෘතිය පුරාවටම අවශ්‍යතා එකතු කිරීමටත්, ක්‍රියාත්මක කිරීමටත් එය ඉඩ දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3bdb001f-4ce6-4664-917b-74609023b3c5', '4fcd6219-f4e8-5722-a548-96b7d005cdb9', 'එය පුනරාවර්ති (iterative) ආකෘතියක් නොවේ.', 'එය පුනරාවර්ති (iterative) ආකෘතියක් නොවේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ef721866-bc8d-419f-b67d-bf53456b8836', '4fcd6219-f4e8-5722-a548-96b7d005cdb9', 'මනාව නිර්ණය කරන ලද අවශ්‍යතා සහිත මෘදුකාංග සඳහා එය සුදුසු වේ.', 'මනාව නිර්ණය කරන ලද අවශ්‍යතා සහිත මෘදුකාංග සඳහා එය සුදුසු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f14ddd4-460c-4428-b03b-ece55487eeb4', '4fcd6219-f4e8-5722-a548-96b7d005cdb9', 'ව්‍යාපෘතියක් සඳහා අවශ්‍ය සම්පත් ඇස්තමේන්තු කිරීම පහසු ය.', 'ව්‍යාපෘතියක් සඳහා අවශ්‍ය සම්පත් ඇස්තමේන්තු කිරීම පහසු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67ab415e-5e4f-4d89-a94b-edc4f78bb2ac', '4fcd6219-f4e8-5722-a548-96b7d005cdb9', 'ව්‍යාපෘතියේ අවසන් අවධි වන තෙක්, වැඩකරන නිෂ්පාදිතයක් (working product) ලබාගත නොහැක.', 'ව්‍යාපෘතියේ අවසන් අවධි වන තෙක්, වැඩකරන නිෂ්පාදිතයක් (working product) ලබාගත නොහැක.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('36120948-d7fd-54d2-9f63-5f6d378f5c07', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 30, '<p>රජයේ ආයතනයක්, දිවයින පුරා ක්‍රියාත්මක කිරීම සඳහා වාණිජ පෙර නිමි පැකේජයක් (COTS) තෝරාගැනීමේදී, අවශ්‍ය විශේෂාංග වලට (features) අමතරව පහත කවරක් සැලකිය යුතු ද?<br><br>A - ස්ථාපනය (deploy) කිරිම, නඩත්තු කිරීම, උශ්‍රේණි (upgrade) කිරීම සහ විකරණය (modify) කිරීම සඳහා වන වියදම<br>B - දැනට පවතින පද්ධති සමග ඒකාබද්ධ (integrate) කිරීමේ පහසුව<br>C - විකුණුම්කරුගේ, මිලදී ගැනීමෙන් පසු සේවය</p>', '<p>රජයේ ආයතනයක්, දිවයින පුරා ක්‍රියාත්මක කිරීම සඳහා වාණිජ පෙර නිමි පැකේජයක් (COTS) තෝරාගැනීමේදී, අවශ්‍ය විශේෂාංග වලට (features) අමතරව පහත කවරක් සැලකිය යුතු ද?<br><br>A - ස්ථාපනය (deploy) කිරිම, නඩත්තු කිරීම, උශ්‍රේණි (upgrade) කිරීම සහ විකරණය (modify) කිරීම සඳහා වන වියදම<br>B - දැනට පවතින පද්ධති සමග ඒකාබද්ධ (integrate) කිරීමේ පහසුව<br>C - විකුණුම්කරුගේ, මිලදී ගැනීමෙන් පසු සේවය</p>', NULL, 'පෙර නිමි මෘදුකාංග (COTS) තෝරාගැනීමේදී එහි දිගුකාලීන නඩත්තු වියදම (A), පවතින පද්ධති සමග ගැලපීම (B) සහ පසු-විකුණුම් සේවාව (C) යන සියලු කරුණු අත්‍යවශ්‍යයෙන්ම සලකා බැලිය යුතුය.', 'පෙර නිමි මෘදුකාංග (COTS) තෝරාගැනීමේදී එහි දිගුකාලීන නඩත්තු වියදම (A), පවතින පද්ධති සමග ගැලපීම (B) සහ පසු-විකුණුම් සේවාව (C) යන සියලු කරුණු අත්‍යවශ්‍යයෙන්ම සලකා බැලිය යුතුය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
