INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7ffaa610-aa5a-506f-bc98-4fa8ec0b0e29', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 39, '<p>$a=10$, $b=4$ සහ $c=7$ වන විට පහත පයිතන් කේතයේ ප්‍රතිදානය කුමක් වේද?<br><br>ans = a % b + c // (a-b)<br>print(ans)</p>', '<p>$a=10$, $b=4$ සහ $c=7$ වන විට පහත පයිතන් කේතයේ ප්‍රතිදානය කුමක් වේද?<br><br>ans = a % b + c // (a-b)<br>print(ans)</p>', NULL, '$ans = 10 \% 4 + 7 \ /\/\ (10-4)$<br>$ans = 2 + 7 \ /\/\ 6$<br>$ans = 2 + 1 = 3$', '$ans = 10 \% 4 + 7 \ /\/\ (10-4)$<br>$ans = 2 + 7 \ /\/\ 6$<br>$ans = 2 + 1 = 3$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
