INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fb017d8f-a30d-513c-a720-89c637d37666', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 40, '<p>පහත පයිතන් කේතය ක්‍රියාත්මක කළ පසු ''result'' විචල්‍යයේ අගය කුමක් වේද?<br><br>def func1(a,b):<br>  return a+b<br>def func2(a,b):<br>  return a*b<br>result = func1(3, func2(2,4))</p>', '<p>පහත පයිතන් කේතය ක්‍රියාත්මක කළ පසු ''result'' විචල්‍යයේ අගය කුමක් වේද?<br><br>def func1(a,b):<br>  return a+b<br>def func2(a,b):<br>  return a*b<br>result = func1(3, func2(2,4))</p>', NULL, 'මුලින්ම ඇතුළත ශ්‍රිතය ක්‍රියාත්මක වේ: $func2(2,4) = 2 \times 4 = 8$.<br>පසුව පිටත ශ්‍රිතය ක්‍රියාත්මක වේ: $func1(3, 8) = 3 + 8 = 11$.', 'මුලින්ම ඇතුළත ශ්‍රිතය ක්‍රියාත්මක වේ: $func2(2,4) = 2 \times 4 = 8$.<br>පසුව පිටත ශ්‍රිතය ක්‍රියාත්මක වේ: $func1(3, 8) = 3 + 8 = 11$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
