INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e0bdcdc7-a4f6-543f-9a2b-e618d9d468cd', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 41, '<p>පහත පයිතන් කේතය ක්‍රියාත්මක කළ විට ප්‍රතිදානය කුමක් වේද?<br><br>def modify_string(input_string):<br>  input_string += " World"<br>text = "Hello"<br>modify_string(text)<br>print(text)</p>', '<p>පහත පයිතන් කේතය ක්‍රියාත්මක කළ විට ප්‍රතිදානය කුමක් වේද?<br><br>def modify_string(input_string):<br>  input_string += " World"<br>text = "Hello"<br>modify_string(text)<br>print(text)</p>', NULL, 'පයිතන් හි String යනු වෙනස් කළ නොහැකි (immutable) දත්ත වර්ගයකි. ශ්‍රිතය ඇතුළතදී අලුත් String අගයක් නිර්මාණය වුවද, එය global `text` විචල්‍යය වෙනස් නොකරයි.', 'පයිතන් හි String යනු වෙනස් කළ නොහැකි (immutable) දත්ත වර්ගයකි. ශ්‍රිතය ඇතුළතදී අලුත් String අගයක් නිර්මාණය වුවද, එය global `text` විචල්‍යය වෙනස් නොකරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
