INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a167e7d3-bf44-5077-953a-a0562aac0a27', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 43, '<p>පහත ක්‍රමලේඛය, ''*'' කොපමණ ප්‍රමාණයක් ප්‍රතිදානය කරයි ද?<br><br>$i=7$<br>while i>0:<br>  $i-=3$<br>  print(''*'')<br>  if $i<=2$:<br>    break<br>  else:<br>    print(''*'')</p>', '<p>පහත ක්‍රමලේඛය, ''*'' කොපමණ ප්‍රමාණයක් ප්‍රතිදානය කරයි ද?<br><br>$i=7$<br>while i>0:<br>  $i-=3$<br>  print(''*'')<br>  if $i<=2$:<br>    break<br>  else:<br>    print(''*'')</p>', NULL, 'පළමු වටය: $i=4$, පළමු ''*'' මුද්‍රණය කරයි. $i<=2$ අසත්‍ය බැවින් else කොටස මගින් දෙවන ''*'' මුද්‍රණය කරයි.<br>දෙවන වටය: $i=1$, තුන්වන ''*'' මුද්‍රණය කරයි. $i<=2$ සත්‍ය බැවින් break වේ. මුළු තරු ගණන 3කි.', 'පළමු වටය: $i=4$, පළමු ''*'' මුද්‍රණය කරයි. $i<=2$ අසත්‍ය බැවින් else කොටස මගින් දෙවන ''*'' මුද්‍රණය කරයි.<br>දෙවන වටය: $i=1$, තුන්වන ''*'' මුද්‍රණය කරයි. $i<=2$ සත්‍ය බැවින් break වේ. මුළු තරු ගණන 3කි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
