INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8dc6f106-646c-574b-909c-3b86325ac8a7', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 45, '<p>පහත පයිතන් කේතයේ ප්‍රතිදානය කුමක් වේද?<br><br>for i in range(1, 4):<br>  for j in range (1, i + 1):<br>    print(j*i, end='' '')<br>  print()</p>', '<p>පහත පයිතන් කේතයේ ප්‍රතිදානය කුමක් වේද?<br><br>for i in range(1, 4):<br>  for j in range (1, i + 1):<br>    print(j*i, end='' '')<br>  print()</p>', NULL, '$i=1$ විට $j=1$ -> 1 මුද්‍රණය වේ.<br>$i=2$ විට $j=1,2$ -> 2, 4 මුද්‍රණය වේ.<br>$i=3$ විට $j=1,2,3$ -> 3, 6, 9 මුද්‍රණය වේ.', '$i=1$ විට $j=1$ -> 1 මුද්‍රණය වේ.<br>$i=2$ විට $j=1,2$ -> 2, 4 මුද්‍රණය වේ.<br>$i=3$ විට $j=1,2,3$ -> 3, 6, 9 මුද්‍රණය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
