INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1c6d5577-4790-5e54-8977-52b73f6d8d1f', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 48, '<p>පෝරමයකට (form) අදාළ පහත HTML කේත පේළිය සලකන්න.<br><br>&lt;form method="post" action="process.php"&gt;<br><br>එහි ''action'' ගුණාංගය,</p>', '<p>පෝරමයකට (form) අදාළ පහත HTML කේත පේළිය සලකන්න.<br><br>&lt;form method="post" action="process.php"&gt;<br><br>එහි ''action'' ගුණාංගය,</p>', NULL, 'HTML පෝරමයක `action` ගුණාංගයෙන් දැක්වෙන්නේ පෝරමයේ දත්ත (form data) ලබාගෙන සැකසීම සිදු කරන සේවාදායකයේ (Server) පිහිටි ගොනුවයි.', 'HTML පෝරමයක `action` ගුණාංගයෙන් දැක්වෙන්නේ පෝරමයේ දත්ත (form data) ලබාගෙන සැකසීම සිදු කරන සේවාදායකයේ (Server) පිහිටි ගොනුවයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
