INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('99168a3f-c9a0-4742-9cbd-522d791be8b4', '1c6d5577-4790-5e54-8977-52b73f6d8d1f', 'වෙබ් පිටුව මත පෝරමයේ එකෙල්ල (alignment) කිරීම පාලනය කරයි.', 'වෙබ් පිටුව මත පෝරමයේ එකෙල්ල (alignment) කිරීම පාලනය කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('36bb5848-b748-4daa-b61f-53d8dd094905', '1c6d5577-4790-5e54-8977-52b73f6d8d1f', 'පෝරමය PHP උපදේශාවලියක් (script) ලෙස ප්‍රකාශ කරයි.', 'පෝරමය PHP උපදේශාවලියක් (script) ලෙස ප්‍රකාශ කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6e27e8d0-87cd-48e9-b351-e80eb524c60c', '1c6d5577-4790-5e54-8977-52b73f6d8d1f', 'process.php ගොනුව තිරයේ පෙන්වයි.', 'process.php ගොනුව තිරයේ පෙන්වයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6b205f9a-b9ea-5106-8bbd-fb671b418f4d', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 49, '<p>සමන්ගේ පියා වඩු කාර්මිකයෙකි. වෙබ් අඩවියක, තම පියාගේ නිර්මාණ ප්‍රදර්ශනය කිරීමට සමන් අදහස් කරයි.<br>තමන්ට දැරිය හැකි අඩු වියදමකින් එය කර ගැනීමට සමන් තම වෙබ් අඩවිය පහත කවර ආකාරයට ප්‍රසිද්ධ (host) කළ යුතුද?</p>', '<p>සමන්ගේ පියා වඩු කාර්මිකයෙකි. වෙබ් අඩවියක, තම පියාගේ නිර්මාණ ප්‍රදර්ශනය කිරීමට සමන් අදහස් කරයි.<br>තමන්ට දැරිය හැකි අඩු වියදමකින් එය කර ගැනීමට සමන් තම වෙබ් අඩවිය පහත කවර ආකාරයට ප්‍රසිද්ධ (host) කළ යුතුද?</p>', NULL, 'කුඩා ප්‍රමාණයේ, අඩු වියදම් වෙබ් අඩවියක් සඳහා වඩාත්ම ලාභදායී සහ ගැලපෙන සත්කාරක සේවාව (hosting) වන්නේ Shared Hosting වේ.', 'කුඩා ප්‍රමාණයේ, අඩු වියදම් වෙබ් අඩවියක් සඳහා වඩාත්ම ලාභදායී සහ ගැලපෙන සත්කාරක සේවාව (hosting) වන්නේ Shared Hosting වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('071b33bd-b4ea-4e56-b33d-8eed90a4c606', '6b205f9a-b9ea-5106-8bbd-fb671b418f4d', 'වෙනත් වෙබ් අඩවිද ඉදිරිපත් කෙරෙන සේවාදායකයක (server) හවුලේ ප්‍රසිද්ධ කිරීම (shared hosting)', 'වෙනත් වෙබ් අඩවිද ඉදිරිපත් කෙරෙන සේවාදායකයක (server) හවුලේ ප්‍රසිද්ධ කිරීම (shared hosting)', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8102f114-55cc-455e-bc15-82deaf51078e', '6b205f9a-b9ea-5106-8bbd-fb671b418f4d', 'අතථ්‍ය පෞද්ගලික සේවාදායකයක (virtual private server) ප්‍රසිද්ධ කිරීම', 'අතථ්‍ය පෞද්ගලික සේවාදායකයක (virtual private server) ප්‍රසිද්ධ කිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4c811d7e-7813-4b45-8252-0cb08d31c585', '6b205f9a-b9ea-5106-8bbd-fb671b418f4d', 'සමන්ටම වෙන් වූ සේවාදායකයක ප්‍රසිද්ධ කිරිම (dedicated hosting)', 'සමන්ටම වෙන් වූ සේවාදායකයක ප්‍රසිද්ධ කිරිම (dedicated hosting)', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6393d556-a3b2-459a-aa3e-77015f24c5f7', '6b205f9a-b9ea-5106-8bbd-fb671b418f4d', 'ඉ-වාණිජ්‍යය වෙබ් අඩවියක් භාවිත කිරිම', 'ඉ-වාණිජ්‍යය වෙබ් අඩවියක් භාවිත කිරිම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42068ff4-804c-4727-a091-0bc8e7b13092', '6b205f9a-b9ea-5106-8bbd-fb671b418f4d', 'ප්‍රචලිත වළාකුළු සේවාදායක (cloud service) සැපයුම්කරුවකුගේ සේවා භාවිත කිරීම', 'ප්‍රචලිත වළාකුළු සේවාදායක (cloud service) සැපයුම්කරුවකුගේ සේවා භාවිත කිරීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d297f41-a655-596e-b63e-1a81d76f43bc', '82f66fc8-4a99-55b7-bfbd-a29edd23df45', 50, '<p>සබැඳි ද්‍රව්‍ය අන්තර්ජාල (IoT) සංවේදකයක (sensor) මූලික කාර්ය කුමක් ද?</p>', '<p>සබැඳි ද්‍රව්‍ය අන්තර්ජාල (IoT) සංවේදකයක (sensor) මූලික කාර්ය කුමක් ද?</p>', NULL, 'IoT පද්ධතියක සංවේදකයක් (Sensor) මගින් සිදු කරන්නේ භෞතික පරිසරයේ සිදුවන උෂ්ණත්වය, ආලෝකය, චලනය වැනි තත්ත්ව වෙනස්වීම් හඳුනාගෙන ඒවා දත්ත බවට පත් කිරීමයි.', 'IoT පද්ධතියක සංවේදකයක් (Sensor) මගින් සිදු කරන්නේ භෞතික පරිසරයේ සිදුවන උෂ්ණත්වය, ආලෝකය, චලනය වැනි තත්ත්ව වෙනස්වීම් හඳුනාගෙන ඒවා දත්ත බවට පත් කිරීමයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('32cba21a-218b-456f-b68d-6187f8647eb4', '1d297f41-a655-596e-b63e-1a81d76f43bc', 'ප්‍රතිදාන ලබා දී පරිසරයේ තත්වයක් (state) වෙනස් කිරීම', 'ප්‍රතිදාන ලබා දී පරිසරයේ තත්වයක් (state) වෙනස් කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a586866-33c1-4b81-a08a-31ee496b93b7', '1d297f41-a655-596e-b63e-1a81d76f43bc', 'උපාංගවල අන්‍යෝන්‍ය ක්‍රියාකාරිත්වය සහතික කිරිම', 'උපාංගවල අන්‍යෝන්‍ය ක්‍රියාකාරිත්වය සහතික කිරිම', NULL, 'sanitized', 'v1', 1, 0);
