INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ac35813f-7ae7-47bd-bd38-257c3c4e07e3', '1d297f41-a655-596e-b63e-1a81d76f43bc', 'පරිශීලක අතුරු මුහුණත සඳහා චිත්‍රක (graphics) ගොඩනැගිම', 'පරිශීලක අතුරු මුහුණත සඳහා චිත්‍රක (graphics) ගොඩනැගිම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('321a2ede-3759-5f28-b396-fd3e766382f9', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 1, '<p>පෘථිවිය මත මුලින්ම ඇති වූ ජීවීන් ලෙස සැලකෙන්නේ</p>', '<p>පෘථිවිය මත මුලින්ම ඇති වූ ජීවීන් ලෙස සැලකෙන්නේ</p>', NULL, 'මාර්කින් ස්කීම් එකට අනුව නිවැරදි පිළිතුර වන්නේ විෂමපෝෂී, නිර්වායු ප්‍රාග්න්‍යෂ්ටිකයන්ය යන්නයි. ආදි පෘථිවියේ ඔක්සිජන් නොතිබූ බැවින් (නිර්වායු) සහ කාබනික ද්‍රව්‍ය සාගරයේ බහුලව තිබූ බැවින් ප්‍රථම ජීවීන් විෂමපෝෂී, නිර්වායු ප්‍රාග්න්‍යෂ්ටිකයන් (heterotrophic anaerobic prokaryotes) විය.', 'මාර්කින් ස්කීම් එකට අනුව නිවැරදි පිළිතුර වන්නේ විෂමපෝෂී, නිර්වායු ප්‍රාග්න්‍යෂ්ටිකයන්ය යන්නයි. ආදි පෘථිවියේ ඔක්සිජන් නොතිබූ බැවින් (නිර්වායු) සහ කාබනික ද්‍රව්‍ය සාගරයේ බහුලව තිබූ බැවින් ප්‍රථම ජීවීන් විෂමපෝෂී, නිර්වායු ප්‍රාග්න්‍යෂ්ටිකයන් (heterotrophic anaerobic prokaryotes) විය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
