INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7bd6cd6c-847b-4fcc-8994-848545be9fce', '31692865-888c-5cbf-a0d8-0dd40c0155c2', 'ක්ෂාලක නිසා දුස්වභාවීකරණය නොවේ.', 'ක්ෂාලක නිසා දුස්වභාවීකරණය නොවේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4b5a17f6-b9fb-4944-a800-7775ef07c7de', '31692865-888c-5cbf-a0d8-0dd40c0155c2', 'ද්‍රව්‍ය පරිවහනයට දායක වේ.', 'ද්‍රව්‍ය පරිවහනයට දායක වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b275c35e-71a8-50ee-bc1a-75ca68aea6c7', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 3, '<p>වීදුරු කදාවක් මත නැංවූ ළූණු සිවියක් සංයුක්ත ආලෝක අණ්වීක්ෂයක වේදිකාව මත තබා නිරීක්ෂණය කිරීමේ<br>පියවර පහත දැක් වේ.<br><br>A - දර්පණය සකස් කිරීම<br>B - සියුම් සීරුමාරුව භාවිත කිරීම<br>C - දළ සීරුමාරුව භාවිත කිරීම<br><br>ඉහත පියවරවල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', '<p>වීදුරු කදාවක් මත නැංවූ ළූණු සිවියක් සංයුක්ත ආලෝක අණ්වීක්ෂයක වේදිකාව මත තබා නිරීක්ෂණය කිරීමේ<br>පියවර පහත දැක් වේ.<br><br>A - දර්පණය සකස් කිරීම<br>B - සියුම් සීරුමාරුව භාවිත කිරීම<br>C - දළ සීරුමාරුව භාවිත කිරීම<br><br>ඉහත පියවරවල නිවැරදි අනුපිළිවෙළ වන්නේ</p>', NULL, 'නිවැරදි පිළිතුර 2 වන විකල්පය වේ. අන්වීක්ෂයක් භාවිතයේදී පළමුව ආලෝකය ලබා ගැනීමට දර්පණය සකස් කළ යුතුය (A). ඉන්පසු දළ සීරුමාරුව (C) මගින් දර්ශනයක් ලබාගෙන, අවසානයේ සියුම් සීරුමාරුව (B) මගින් රූපය වඩාත් පැහැදිලි කරගත යුතුය.', 'නිවැරදි පිළිතුර 2 වන විකල්පය වේ. අන්වීක්ෂයක් භාවිතයේදී පළමුව ආලෝකය ලබා ගැනීමට දර්පණය සකස් කළ යුතුය (A). ඉන්පසු දළ සීරුමාරුව (C) මගින් දර්ශනයක් ලබාගෙන, අවසානයේ සියුම් සීරුමාරුව (B) මගින් රූපය වඩාත් පැහැදිලි කරගත යුතුය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
