INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bb8c8e46-36c5-59f0-a629-67d48bbea1d6', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 5, '<p>සුන්‍යෂ්ටික සෛල චක්‍රය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>සුන්‍යෂ්ටික සෛල චක්‍රය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'නිවැරදි පිළිතුර වන්නේ 5 වන විකල්පයයි. සුන්‍යෂ්ටික සෛල විභාජනයේ ප්‍රාක් කලාවේදී (prophase) අනූනන තර්කුව (mitotic spindle) තැනීම ආරම්භ වේ. අවතරණය සිදුවන්නේ ඌනනය I හි ප්‍රාක් කලාවේදීය. DNA ප්‍රතිවලිත වන්නේ S කලාවේදීය මිස $G_2$ කලාවේදී නොවේ.', 'නිවැරදි පිළිතුර වන්නේ 5 වන විකල්පයයි. සුන්‍යෂ්ටික සෛල විභාජනයේ ප්‍රාක් කලාවේදී (prophase) අනූනන තර්කුව (mitotic spindle) තැනීම ආරම්භ වේ. අවතරණය සිදුවන්නේ ඌනනය I හි ප්‍රාක් කලාවේදීය. DNA ප්‍රතිවලිත වන්නේ S කලාවේදීය මිස $G_2$ කලාවේදී නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67d74001-8e8e-43c6-86d8-587752c41a1b', 'bb8c8e46-36c5-59f0-a629-67d48bbea1d6', 'අවතරණය සිදු වන්නේ ඌනනය Iහි යෝග කලාවේදී ය.', 'අවතරණය සිදු වන්නේ ඌනනය Iහි යෝග කලාවේදී ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('23a01a43-7542-460e-96af-b9ada0939d42', 'bb8c8e46-36c5-59f0-a629-67d48bbea1d6', 'ක්‍රොමැටින් තැනෙනුයේ $G_1$ කලාවේදී ය.', 'ක්‍රොමැටින් තැනෙනුයේ $G_1$ කලාවේදී ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3be669a3-769e-42a3-a203-3a443ddd9fe8', 'bb8c8e46-36c5-59f0-a629-67d48bbea1d6', 'DNA ප්‍රතිවලිත වීම සිදු වන්නේ $G_2$ කලාවේදී ය.', 'DNA ප්‍රතිවලිත වීම සිදු වන්නේ $G_2$ කලාවේදී ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('07ec7350-f82f-473b-a3ec-f702cfb2839e', 'bb8c8e46-36c5-59f0-a629-67d48bbea1d6', 'න්‍යෂ්ටික ආවරණය නැවත තැනෙනුයේ සෛල ප්ලාස්ම විභාජනය සිදු වන විටදීය.', 'න්‍යෂ්ටික ආවරණය නැවත තැනෙනුයේ සෛල ප්ලාස්ම විභාජනය සිදු වන විටදීය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('edbfec83-11fd-45da-bd79-fa24fa92c0c1', 'bb8c8e46-36c5-59f0-a629-67d48bbea1d6', 'අනූතන තර්කුව තැනීම ආරම්භ වන්නේ ප්‍රාක් කලාවේදී ය.', 'අනූතන තර්කුව තැනීම ආරම්භ වන්නේ ප්‍රාක් කලාවේදී ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('59a24e4d-c43c-5379-a773-0a4121020dca', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 6, '<p>ATP</p>', '<p>ATP</p>', NULL, 'නිවැරදි පිළිතුර 3 වේ. ATP අණුවක් ජල විච්ඡේදනය වී ADP සහ අකාබනික පොස්ෆේට් බවට පත්වීමේදී $30.5~kJ/mol$ ශක්තියක් මුදා හරී. එය නියුක්ලියොසයිඩයක් නොව නියුක්ලියොටයිඩයකි. එහි ඇත්තේ රයිබෝස් සීනි මිස ඩිඔක්සිරයිබෝස් නොවේ.', 'නිවැරදි පිළිතුර 3 වේ. ATP අණුවක් ජල විච්ඡේදනය වී ADP සහ අකාබනික පොස්ෆේට් බවට පත්වීමේදී $30.5~kJ/mol$ ශක්තියක් මුදා හරී. එය නියුක්ලියොසයිඩයක් නොව නියුක්ලියොටයිඩයකි. එහි ඇත්තේ රයිබෝස් සීනි මිස ඩිඔක්සිරයිබෝස් නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('009f482d-7171-4992-9581-ea8121701f32', '59a24e4d-c43c-5379-a773-0a4121020dca', 'පෙන්ටෝස් සීනි, ඇඩිනීන් සහ පොස්ෆේට් කාණ්ඩවලින් සමන්විත නියුක්ලියොසයිඩයකි.', 'පෙන්ටෝස් සීනි, ඇඩිනීන් සහ පොස්ෆේට් කාණ්ඩවලින් සමන්විත නියුක්ලියොසයිඩයකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e3133ed0-3b1b-445c-a758-ff3e585596f3', '59a24e4d-c43c-5379-a773-0a4121020dca', 'සූර්ය ශක්තිය භාවිත කර ඔක්සිකාරක පොස්ෆොරයිලීකරණය මගින් නිපදවිය හැකි ය.', 'සූර්ය ශක්තිය භාවිත කර ඔක්සිකාරක පොස්ෆොරයිලීකරණය මගින් නිපදවිය හැකි ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cfb91819-ce94-4a4d-9675-84dede1c875c', '59a24e4d-c43c-5379-a773-0a4121020dca', '$30.5~kJ/mol$ ශක්ති ප්‍රමාණයක් නිදහස් කරමින් ADP බවට ජලවිච්ඡේදනය වේ.', '$30.5~kJ/mol$ ශක්ති ප්‍රමාණයක් නිදහස් කරමින් ADP බවට ජලවිච්ඡේදනය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d05b5704-def3-4b5a-81fc-f345baacae33', '59a24e4d-c43c-5379-a773-0a4121020dca', 'උපස්තර මට්ටමේ පොස්ෆොරයිලීකරණය හරහා පයිරුවේට් ඔක්සිකරණයේදී නිපද වේ.', 'උපස්තර මට්ටමේ පොස්ෆොරයිලීකරණය හරහා පයිරුවේට් ඔක්සිකරණයේදී නිපද වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('775e1a9e-df3c-447b-8140-9662c16b0020', '59a24e4d-c43c-5379-a773-0a4121020dca', 'ඩිඔක්සිරයිබෝස් දරයි.', 'ඩිඔක්සිරයිබෝස් දරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c9ea62a7-06cc-525c-a21b-4293f1eaac62', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 7, '<p>පහත සඳහන් ඒවා අතුරෙන් එන්සයිමවල ලක්ෂණයක් වන්නේ කුමක් ද?</p>', '<p>පහත සඳහන් ඒවා අතුරෙන් එන්සයිමවල ලක්ෂණයක් වන්නේ කුමක් ද?</p>', NULL, 'නිවැරදි පිළිතුර 1 වේ. එන්සයිම මගින් ප්‍රතික්‍රියාවක් වේගවත් කරන නමුත් ප්‍රතික්‍රියාවේ අවසාන ඵලවල ස්වභාවය වෙනස් නොකරයි. ඒවා සක්‍රියන ශක්තිය අඩු කරයි, උපස්තර සඳහා විශිෂ්ට වේ, ප්‍රතික්‍රියාවේදී වැය නොවේ, එමෙන්ම ප්‍රතික්‍රියාව උත්ප්‍රේරණය කරන්නේ සක්‍රිය ප්‍රදේශය (active site) මගිනි.', 'නිවැරදි පිළිතුර 1 වේ. එන්සයිම මගින් ප්‍රතික්‍රියාවක් වේගවත් කරන නමුත් ප්‍රතික්‍රියාවේ අවසාන ඵලවල ස්වභාවය වෙනස් නොකරයි. ඒවා සක්‍රියන ශක්තිය අඩු කරයි, උපස්තර සඳහා විශිෂ්ට වේ, ප්‍රතික්‍රියාවේදී වැය නොවේ, එමෙන්ම ප්‍රතික්‍රියාව උත්ප්‍රේරණය කරන්නේ සක්‍රිය ප්‍රදේශය (active site) මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
