INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('90ed70de-6ed7-4e3a-9288-55115b8d1632', 'c9ea62a7-06cc-525c-a21b-4293f1eaac62', 'ඒවා ප්‍රතික්‍රියාවක සක්‍රියන ශක්තිය වැඩි කරයි.', 'ඒවා ප්‍රතික්‍රියාවක සක්‍රියන ශක්තිය වැඩි කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0fc7bab7-42ed-4a60-bbed-dbffe8e5a998', 'c9ea62a7-06cc-525c-a21b-4293f1eaac62', 'ඒවා උපස්තර වලට විශිෂ්ට නොවේ.', 'ඒවා උපස්තර වලට විශිෂ්ට නොවේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c7f5458f-a2e5-430e-a138-302e38a93b88', 'c9ea62a7-06cc-525c-a21b-4293f1eaac62', 'ප්‍රතික්‍රියාවේදී එන්සයිම සුළු ප්‍රමාණයක් වැය වේ.', 'ප්‍රතික්‍රියාවේදී එන්සයිම සුළු ප්‍රමාණයක් වැය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('562452c3-2d7f-4672-93fc-2af2d17875aa', 'c9ea62a7-06cc-525c-a21b-4293f1eaac62', 'එන්සයිම අණුවක ඕනෑම කොටසකට ප්‍රතික්‍රියාවක් උත්ප්‍රේරණය කළ හැකි ය.', 'එන්සයිම අණුවක ඕනෑම කොටසකට ප්‍රතික්‍රියාවක් උත්ප්‍රේරණය කළ හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8aee61f3-22b5-5319-817c-16edddd5bd38', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 8, '<p>ජෛව රසායනික පරිණාමය පිළිබඳ ප්‍රකාශ කිහිපයක් පහත දී ඇත.<br><br>P - ඇමයිනෝ අම්ල සහ නයිට්‍රජනීය භෂ්ම වැනි කුඩා කාබනික අණු ප්‍රථමයෙන් ආදී සාගර වල ඇති විය.<br>Q - කුඩා කාබනික අණු, කාබනික මහා අණු තැනීම සඳහා බහුඅවයවීකරණය විය.<br>R - ප්‍රාක්සෛල තුළ පටල වලින් වට වු න්‍යෂ්ටික අම්ල තිබුණි.<br><br>ඉහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද ?/ කුමන ඒවා ද ?</p>', '<p>ජෛව රසායනික පරිණාමය පිළිබඳ ප්‍රකාශ කිහිපයක් පහත දී ඇත.<br><br>P - ඇමයිනෝ අම්ල සහ නයිට්‍රජනීය භෂ්ම වැනි කුඩා කාබනික අණු ප්‍රථමයෙන් ආදී සාගර වල ඇති විය.<br>Q - කුඩා කාබනික අණු, කාබනික මහා අණු තැනීම සඳහා බහුඅවයවීකරණය විය.<br>R - ප්‍රාක්සෛල තුළ පටල වලින් වට වු න්‍යෂ්ටික අම්ල තිබුණි.<br><br>ඉහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද ?/ කුමන ඒවා ද ?</p>', NULL, 'නිවැරදි පිළිතුර 2 වන විකල්පයයි. ජෛව රසායනික පරිණාමය පිළිබඳ පිළිගත් මතය අනුව කුඩා කාබනික අණු බහුඅවයවීකරණය වී මහා අණු සෑදුණි (Q නිවැරදිය). ප්‍රාක්සෛල තුළ පටල වලින් වට වූ න්‍යෂ්ටික අම්ල නොතිබුණි; පටල වලින් වට වූයේ මුළු ප්‍රාක්සෛලයයි. කුඩා කාබනික අණු ප්‍රථමයෙන් ඇති වූයේ ආදී වායුගෝලයේ යැයි සැලකේ. එබැවින් නිවැරදි වන්නේ Q පමණි.', 'නිවැරදි පිළිතුර 2 වන විකල්පයයි. ජෛව රසායනික පරිණාමය පිළිබඳ පිළිගත් මතය අනුව කුඩා කාබනික අණු බහුඅවයවීකරණය වී මහා අණු සෑදුණි (Q නිවැරදිය). ප්‍රාක්සෛල තුළ පටල වලින් වට වූ න්‍යෂ්ටික අම්ල නොතිබුණි; පටල වලින් වට වූයේ මුළු ප්‍රාක්සෛලයයි. කුඩා කාබනික අණු ප්‍රථමයෙන් ඇති වූයේ ආදී වායුගෝලයේ යැයි සැලකේ. එබැවින් නිවැරදි වන්නේ Q පමණි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_