INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('17d215f7-fd9e-41c4-a443-f893288f2f43', '905e3264-dcf3-55f5-8301-fa1305b1671a', 'මුහුදු කැකිරි, ගොළුබෙල්ලා සහ Obelia වේ.', 'මුහුදු කැකිරි, ගොළුබෙල්ලා සහ Obelia වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4ccf9038-2278-54fd-bb80-16b34a2e6fb7', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 11, '<p>ගදා පාසිවලට වඩා ශුකි පාසි බීජ ශාකවලට සමාන ලෙස සැලකිය හැක්කේ, ශුකි පාසි</p>', '<p>ගදා පාසිවලට වඩා ශුකි පාසි බීජ ශාකවලට සමාන ලෙස සැලකිය හැක්කේ, ශුකි පාසි</p>', NULL, 'ශුකි පාසි (Lycopodium, Selaginella වැනි Lycophyta වලට අයත් ශාක) අතරින් Selaginella විෂම බීජාණුකතාව (heterospory) දක්වයි. සියලුම බීජ ශාක ද විෂම බීජාණුකතාව පෙන්වන බැවින්, සමබීජාණුක ගදා පාසි (mosses) වලට වඩා ශුකි පාසි බීජ ශාක වලට සමානකමක් දක්වයි.', 'ශුකි පාසි (Lycopodium, Selaginella වැනි Lycophyta වලට අයත් ශාක) අතරින් Selaginella විෂම බීජාණුකතාව (heterospory) දක්වයි. සියලුම බීජ ශාක ද විෂම බීජාණුකතාව පෙන්වන බැවින්, සමබීජාණුක ගදා පාසි (mosses) වලට වඩා ශුකි පාසි බීජ ශාක වලට සමානකමක් දක්වයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
