INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('92c781d2-e3f8-4d05-91a0-e39eee3efab9', '3ce1ee07-d551-5aa8-9ee4-83cdd15997b7', 'අසමාකාර ලෙස ඝන වූ සෛල බිත්ති දරන බැවිනි.', 'අසමාකාර ලෙස ඝන වූ සෛල බිත්ති දරන බැවිනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a7de9f9-75d6-4b30-b739-f7f6cf1a2884', '3ce1ee07-d551-5aa8-9ee4-83cdd15997b7', 'ලිග්නින් වලින් ඝන වී ඇති බැවිනි.', 'ලිග්නින් වලින් ඝන වී ඇති බැවිනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ae34b03f-6bd3-4580-a0c7-3c8ea674b710', '3ce1ee07-d551-5aa8-9ee4-83cdd15997b7', 'ශාකවල සනාල පටකවල ඇති බැවිනි.', 'ශාකවල සනාල පටකවල ඇති බැවිනි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b1d149e5-524a-5910-810d-ac25ea4a94f7', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 14, '<p>ප්‍රරෝහ අග්‍රස්ථ විභාජකය</p>', '<p>ප්‍රරෝහ අග්‍රස්ථ විභාජකය</p>', NULL, 'අග්‍රස්ථ විභාජක (Apical meristem) සැදී ඇත්තේ නොකඩවා සෛල විභාජනයට ලක්විය හැකි, විභේදනය නොවූ (undifferentiated) සෛල වලිනි. එය දායක වන්නේ කඳේ උස වැඩි වීමට (ප්‍රාථමික වර්ධනයට) පමණි. කඳේ විෂ්කම්භය වැඩි කරන්නේ පාර්ශ්වික විභාජක මගිනි.', 'අග්‍රස්ථ විභාජක (Apical meristem) සැදී ඇත්තේ නොකඩවා සෛල විභාජනයට ලක්විය හැකි, විභේදනය නොවූ (undifferentiated) සෛල වලිනි. එය දායක වන්නේ කඳේ උස වැඩි වීමට (ප්‍රාථමික වර්ධනයට) පමණි. කඳේ විෂ්කම්භය වැඩි කරන්නේ පාර්ශ්වික විභාජක මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f5f29a65-4769-4b77-83a7-b54176543274', 'b1d149e5-524a-5910-810d-ac25ea4a94f7', 'කඳේ උස සහ විෂ්කම්භය වැඩි කරයි.', 'කඳේ උස සහ විෂ්කම්භය වැඩි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
